"""Proof Systems and Consensus Mechanisms
=======================================

This module implements custom proof systems and consensus mechanisms
for the Spotify AI Agent blockchain, including Proof-of-Listen,
Proof-of-Engagement, reputation systems, and consensus metrics.

Features:
- Proof-of-Listen consensus mechanism
- Proof-of-Engagement validation
- Reputation-based consensus
- Consensus performance metrics
- Validator management and selection
- Byzantine fault tolerance

Author: Fahed Mlaiel
Date: 2025-01-28
"""
import asyncio
import logging
import hashlib
import json
import random
from typing import Dict, List, Optional, Any, Union, Tuple, Set
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from decimal import Decimal
from enum import Enum
import numpy as np

logger = logging.getLogger(__name__)


class ConsensusType(str, Enum):
    """Types of consensus mechanisms."""
    PROOF_OF_LISTEN = "proof_of_listen"
    PROOF_OF_ENGAGEMENT = "proof_of_engagement"
    PROOF_OF_STAKE = "proof_of_stake"
    REPUTATION_BASED = "reputation_based"
    HYBRID = "hybrid"


class ValidatorStatus(str, Enum):
    """Validator node status."""
    ACTIVE = "active"
    INACTIVE = "inactive"
    JAILED = "jailed"
    SLASHED = "slashed"
    PENDING = "pending"


class ProofType(str, Enum):
    """Types of proofs."""
    LISTENING_PROOF = "listening_proof"
    ENGAGEMENT_PROOF = "engagement_proof"
    STAKE_PROOF = "stake_proof"
    REPUTATION_PROOF = "reputation_proof"


@dataclass
class ListeningProof:
    """Proof of listening activity."""
    proof_id: str
    user_address: str
    track_id: str
    artist_address: str
    duration_seconds: int
    completion_rate: float
    engagement_score: float
    timestamp: datetime
    proof_hash: str
    validation_score: float = 0.0
    validated_by: List[str] = field(default_factory=list)


@dataclass
class EngagementProof:
    """Proof of user engagement."""
    proof_id: str
    user_address: str
    engagement_type: str  # like, share, comment, playlist_add
    content_id: str
    engagement_value: float
    context_data: Dict[str, Any]
    timestamp: datetime
    proof_hash: str
    validation_score: float = 0.0


@dataclass
class ValidatorNode:
    """Blockchain validator node."""
    validator_id: str
    address: str
    stake_amount: Decimal
    reputation_score: float
    status: ValidatorStatus
    listening_power: int
    engagement_power: int
    total_validations: int
    successful_validations: int
    last_active: datetime
    commission_rate: Decimal = Decimal("0.05")
    joined_at: datetime = field(default_factory=datetime.utcnow)
    slashed_amount: Decimal = Decimal("0")


@dataclass
class ConsensusRound:
    """Consensus round data."""
    round_id: str
    round_number: int
    consensus_type: ConsensusType
    proposer: str
    validators: List[str]
    proofs_included: List[str]
    votes: Dict[str, bool]
    finalized: bool = False
    finalized_at: Optional[datetime] = None
    rewards_distributed: Decimal = Decimal("0")
    started_at: datetime = field(default_factory=datetime.utcnow)


class ProofOfListenConsensus:
    """Proof-of-Listen consensus mechanism."""
    
    def __init__(self, config: Dict[str, Any]):
        """Initialize Proof-of-Listen consensus."""
        self.config = config
        self.listening_proofs: Dict[str, ListeningProof] = {}
        self.validators: Dict[str, ValidatorNode] = {}
        self.consensus_rounds: Dict[str, ConsensusRound] = {}
        self.current_round: Optional[ConsensusRound] = None
        
        # Consensus parameters
        self.min_validators = config.get("min_validators", 5)
        self.max_validators = config.get("max_validators", 21)
        self.round_duration = config.get("round_duration", 60)  # seconds
        self.min_listening_time = config.get("min_listening_time", 30)  # seconds
        self.proof_validity_period = config.get("proof_validity_period", 3600)  # seconds
        
        # Initialize system
        self._initialize_genesis_validators()
    
    def _initialize_genesis_validators(self):
        """Initialize genesis validators."""
        genesis_validators = [
            {"address": f"0x{i:040x}", "stake": Decimal("100000")}
            for i in range(1, 6)  # 5 genesis validators
        ]
        
        for i, validator_data in enumerate(genesis_validators):
            validator = ValidatorNode(
                validator_id=f"genesis_validator_{i+1}",
                address=validator_data["address"],
                stake_amount=validator_data["stake"],
                reputation_score=1.0,
                status=ValidatorStatus.ACTIVE,
                listening_power=100,
                engagement_power=100,
                total_validations=0,
                successful_validations=0,
                last_active=datetime.utcnow()
            )
            
            self.validators[validator.validator_id] = validator
        
        logger.info(f"Initialized {len(genesis_validators)} genesis validators")
    
    async def submit_listening_proof(self,
                                   user_address: str,
                                   track_id: str,
                                   artist_address: str,
                                   duration_seconds: int,
                                   completion_rate: float,
                                   engagement_data: Dict[str, Any]) -> str:
        """Submit a proof of listening for validation."""
        try:
            # Validate minimum listening time
            if duration_seconds < self.min_listening_time:
                raise ValueError(f"Listening duration {duration_seconds}s below minimum {self.min_listening_time}s")
            
            # Calculate engagement score
            engagement_score = self._calculate_engagement_score(engagement_data)
            
            # Generate proof ID and hash
            proof_id = f"listen_proof_{int(datetime.utcnow().timestamp())}_{hash(user_address)}"
            proof_data = {
                "user_address": user_address,
                "track_id": track_id,
                "artist_address": artist_address,
                "duration_seconds": duration_seconds,
                "completion_rate": completion_rate,
                "engagement_score": engagement_score,
                "timestamp": datetime.utcnow().isoformat()
            }
            
            proof_hash = hashlib.sha256(json.dumps(proof_data, sort_keys=True).encode()).hexdigest()
            
            # Create listening proof
            listening_proof = ListeningProof(
                proof_id=proof_id,
                user_address=user_address,
                track_id=track_id,
                artist_address=artist_address,
                duration_seconds=duration_seconds,
                completion_rate=completion_rate,
                engagement_score=engagement_score,
                timestamp=datetime.utcnow(),
                proof_hash=proof_hash
            )
            
            # Store proof
            self.listening_proofs[proof_id] = listening_proof
            
            # Queue proof for validation
            await self._queue_proof_for_validation(listening_proof)
            
            logger.info(f"Submitted listening proof {proof_id} for {duration_seconds}s")
            return proof_id
            
        except Exception as e:
            logger.error(f"Error submitting listening proof: {e}")
            raise
    
    def _calculate_engagement_score(self, engagement_data: Dict[str, Any]) -> float:
        """Calculate engagement score from interaction data."""
        try:
            base_score = 1.0
            
            # Volume level engagement
            volume_consistency = engagement_data.get("volume_consistency", 1.0)
            base_score *= volume_consistency
            
            # Skip behavior
            skip_count = engagement_data.get("skip_count", 0)
            skip_penalty = max(0, 1.0 - (skip_count * 0.1))
            base_score *= skip_penalty
            
            # Repeat listening bonus
            repeat_count = engagement_data.get("repeat_count", 0)
            repeat_bonus = min(1.5, 1.0 + (repeat_count * 0.1))
            base_score *= repeat_bonus
            
            # Social interactions
            if engagement_data.get("liked", False):
                base_score *= 1.2
            
            if engagement_data.get("shared", False):
                base_score *= 1.3
            
            if engagement_data.get("added_to_playlist", False):
                base_score *= 1.1
            
            # Time of day consistency (indicates organic listening)
            time_consistency = engagement_data.get("time_consistency", 1.0)
            base_score *= time_consistency
            
            return min(base_score, 3.0)  # Cap at 3.0
            
        except Exception as e:
            logger.error(f"Error calculating engagement score: {e}")
            return 1.0
    
    async def _queue_proof_for_validation(self, proof: ListeningProof):
        """Queue proof for validator consensus."""
        try:
            # Add to current consensus round or create new one
            if not self.current_round or self._should_start_new_round():
                await self._start_new_consensus_round()
            
            if self.current_round:
                self.current_round.proofs_included.append(proof.proof_id)
                logger.info(f"Added proof {proof.proof_id} to consensus round {self.current_round.round_id}")
            
        except Exception as e:
            logger.error(f"Error queuing proof for validation: {e}")
    
    def _should_start_new_round(self) -> bool:
        """Check if a new consensus round should be started."""
        if not self.current_round:
            return True
        
        # Check if current round has been running too long
        time_elapsed = (datetime.utcnow() - self.current_round.started_at).total_seconds()
        if time_elapsed > self.round_duration:
            return True
        
        # Check if current round has enough proofs
        if len(self.current_round.proofs_included) >= 100:  # Max proofs per round
            return True
        
        return False
    
    async def _start_new_consensus_round(self):
        """Start a new consensus round."""
        try:
            # Finalize current round if exists
            if self.current_round and not self.current_round.finalized:
                await self._finalize_consensus_round(self.current_round.round_id)
            
            # Select validators for new round
            selected_validators = await self._select_validators()
            
            # Choose proposer
            proposer = self._select_proposer(selected_validators)
            
            # Create new round
            round_number = len(self.consensus_rounds) + 1
            round_id = f"round_{round_number}_{int(datetime.utcnow().timestamp())}"
            
            new_round = ConsensusRound(
                round_id=round_id,
                round_number=round_number,
                consensus_type=ConsensusType.PROOF_OF_LISTEN,
                proposer=proposer,
                validators=selected_validators,
                proofs_included=[],
                votes={}
            )
            
            self.current_round = new_round
            self.consensus_rounds[round_id] = new_round
            
            # Start consensus process
            asyncio.create_task(self._run_consensus_round(round_id))
            
            logger.info(f"Started new consensus round {round_id} with {len(selected_validators)} validators")
            
        except Exception as e:
            logger.error(f"Error starting new consensus round: {e}")
    
    async def _select_validators(self) -> List[str]:
        """Select validators for consensus round based on listening power and reputation."""
        try:
            active_validators = [
                v for v in self.validators.values()
                if v.status == ValidatorStatus.ACTIVE
            ]
            
            if len(active_validators) < self.min_validators:
                raise ValueError(f"Insufficient active validators: {len(active_validators)}")
            
            # Calculate selection weights based on listening power and reputation
            weighted_validators = []
            for validator in active_validators:
                weight = validator.listening_power * validator.reputation_score
                weighted_validators.append((validator.validator_id, weight))
            
            # Sort by weight and select top validators
            weighted_validators.sort(key=lambda x: x[1], reverse=True)
            selected_count = min(len(weighted_validators), self.max_validators)
            
            selected = [v[0] for v in weighted_validators[:selected_count]]
            
            return selected
            
        except Exception as e:
            logger.error(f"Error selecting validators: {e}")
            return []
    
    def _select_proposer(self, validators: List[str]) -> str:
        """Select round proposer from validators."""
        if not validators:
            return ""
        
        # Weighted random selection based on listening power
        weights = []
        for validator_id in validators:
            validator = self.validators.get(validator_id)
            if validator:
                weights.append(validator.listening_power)
            else:
                weights.append(1)
        
        if not weights:
            return validators[0]
        
        # Weighted random selection
        total_weight = sum(weights)
        if total_weight == 0:
            return validators[0]
        
        normalized_weights = [w / total_weight for w in weights]
        selected_index = np.random.choice(len(validators), p=normalized_weights)
        
        return validators[selected_index]
    
    async def _run_consensus_round(self, round_id: str):
        """Run consensus round process."""
        try:
            if round_id not in self.consensus_rounds:
                return
            
            consensus_round = self.consensus_rounds[round_id]
            
            # Wait for proofs to be submitted
            await asyncio.sleep(self.round_duration / 2)
            
            # Validate proofs
            await self._validate_round_proofs(consensus_round)
            
            # Collect validator votes
            await self._collect_validator_votes(consensus_round)
            
            # Wait for voting period
            await asyncio.sleep(self.round_duration / 2)
            
            # Finalize round
            await self._finalize_consensus_round(round_id)
            
        except Exception as e:
            logger.error(f"Error running consensus round {round_id}: {e}")
    
    async def _validate_round_proofs(self, consensus_round: ConsensusRound):
        """Validate proofs in consensus round."""
        try:
            for proof_id in consensus_round.proofs_included:
                if proof_id in self.listening_proofs:
                    proof = self.listening_proofs[proof_id]
                    
                    # Perform validation checks
                    validation_score = await self._validate_listening_proof(proof)
                    proof.validation_score = validation_score
                    
                    logger.debug(f"Validated proof {proof_id} with score {validation_score}")
            
        except Exception as e:
            logger.error(f"Error validating round proofs: {e}")
    
    async def _validate_listening_proof(self, proof: ListeningProof) -> float:
        """Validate individual listening proof."""
        try:
            validation_score = 1.0
            
            # Check proof age
            proof_age = (datetime.utcnow() - proof.timestamp).total_seconds()
            if proof_age > self.proof_validity_period:
                validation_score *= 0.5  # Penalize old proofs
            
            # Check completion rate reasonableness
            if proof.completion_rate < 0.3:  # Very low completion
                validation_score *= 0.7
            elif proof.completion_rate > 0.9:  # High completion
                validation_score *= 1.2
            
            # Check engagement score reasonableness
            if proof.engagement_score < 0.5:
                validation_score *= 0.8
            elif proof.engagement_score > 2.0:
                validation_score *= 1.1
            
            # Check duration reasonableness
            if proof.duration_seconds < self.min_listening_time:
                validation_score = 0.0  # Invalid
            elif proof.duration_seconds > 1800:  # 30 minutes
                validation_score *= 0.9  # Slight penalty for very long sessions
            
            # Anti-bot checks (simplified)
            if self._is_potentially_bot_activity(proof):
                validation_score *= 0.3
            
            return max(0.0, min(validation_score, 1.0))
            
        except Exception as e:
            logger.error(f"Error validating listening proof: {e}")
            return 0.0
    
    def _is_potentially_bot_activity(self, proof: ListeningProof) -> bool:
        """Check if proof shows signs of bot activity."""
        try:
            # Check for perfect patterns (bots often have perfect behavior)
            if (proof.completion_rate == 1.0 and 
                proof.engagement_score == 1.0 and
                proof.duration_seconds % 60 == 0):  # Perfect minute durations
                return True
            
            # Check for rapid sequential submissions from same user
            user_proofs = [
                p for p in self.listening_proofs.values()
                if p.user_address == proof.user_address and
                abs((p.timestamp - proof.timestamp).total_seconds()) < 60
            ]
            
            if len(user_proofs) > 5:  # Too many proofs in short time
                return True
            
            return False
            
        except Exception as e:
            logger.error(f"Error checking bot activity: {e}")
            return False
    
    async def _collect_validator_votes(self, consensus_round: ConsensusRound):
        """Collect votes from validators."""
        try:
            for validator_id in consensus_round.validators:
                validator = self.validators.get(validator_id)
                if not validator:
                    continue
                
                # Simulate validator vote (in production, validators would vote independently)
                vote = await self._simulate_validator_vote(validator, consensus_round)
                consensus_round.votes[validator_id] = vote
                
                # Update validator activity
                validator.last_active = datetime.utcnow()
                validator.total_validations += 1
                if vote:
                    validator.successful_validations += 1
            
            logger.info(f"Collected {len(consensus_round.votes)} validator votes for round {consensus_round.round_id}")
            
        except Exception as e:
            logger.error(f"Error collecting validator votes: {e}")
    
    async def _simulate_validator_vote(self,
                                     validator: ValidatorNode,
                                     consensus_round: ConsensusRound) -> bool:
        """Simulate validator vote based on proof validation."""
        try:
            # Calculate average validation score of proofs
            total_score = 0.0
            valid_proofs = 0
            
            for proof_id in consensus_round.proofs_included:
                if proof_id in self.listening_proofs:
                    proof = self.listening_proofs[proof_id]
                    total_score += proof.validation_score
                    valid_proofs += 1
            
            if valid_proofs == 0:
                return False
            
            average_score = total_score / valid_proofs
            
            # Validator votes yes if average score is above threshold
            vote_threshold = 0.7
            validator_vote = average_score >= vote_threshold
            
            # Add some randomness based on validator reputation
            if validator.reputation_score < 0.8:
                # Less reliable validators have some randomness
                if random.random() < 0.1:  # 10% random incorrect vote
                    validator_vote = not validator_vote
            
            return validator_vote
            
        except Exception as e:
            logger.error(f"Error simulating validator vote: {e}")
            return False
    
    async def _finalize_consensus_round(self, round_id: str):
        """Finalize consensus round and distribute rewards."""
        try:
            if round_id not in self.consensus_rounds:
                return
            
            consensus_round = self.consensus_rounds[round_id]
            
            if consensus_round.finalized:
                return
            
            # Calculate consensus result
            total_votes = len(consensus_round.votes)
            yes_votes = sum(1 for vote in consensus_round.votes.values() if vote)
            
            consensus_reached = yes_votes > (total_votes * 2 / 3)  # 2/3 majority
            
            # Distribute rewards if consensus reached
            if consensus_reached:
                rewards_distributed = await self._distribute_consensus_rewards(consensus_round)
                consensus_round.rewards_distributed = rewards_distributed
            
            # Mark round as finalized
            consensus_round.finalized = True
            consensus_round.finalized_at = datetime.utcnow()
            
            # Update validator reputations
            await self._update_validator_reputations(consensus_round, consensus_reached)
            
            logger.info(f"Finalized consensus round {round_id}: {'SUCCESS' if consensus_reached else 'FAILED'}")
            
        except Exception as e:
            logger.error(f"Error finalizing consensus round {round_id}: {e}")
    
    async def _distribute_consensus_rewards(self, consensus_round: ConsensusRound) -> Decimal:
        """Distribute rewards to validators and proof submitters."""
        try:
            total_rewards = Decimal("1000")  # Base reward per round
            
            # Validator rewards (70% of total)
            validator_rewards = total_rewards * Decimal("0.7")
            validator_count = len(consensus_round.validators)
            
            if validator_count > 0:
                reward_per_validator = validator_rewards / Decimal(validator_count)
                
                for validator_id in consensus_round.validators:
                    validator = self.validators.get(validator_id)
                    if validator:
                        # Distribute reward (mock implementation)
                        logger.debug(f"Distributed {reward_per_validator} tokens to validator {validator_id}")
            
            # Proof submitter rewards (30% of total)
            proof_rewards = total_rewards * Decimal("0.3")
            valid_proofs = len([
                p for p in consensus_round.proofs_included
                if p in self.listening_proofs and 
                self.listening_proofs[p].validation_score > 0.5
            ])
            
            if valid_proofs > 0:
                reward_per_proof = proof_rewards / Decimal(valid_proofs)
                
                for proof_id in consensus_round.proofs_included:
                    if (proof_id in self.listening_proofs and 
                        self.listening_proofs[proof_id].validation_score > 0.5):
                        proof = self.listening_proofs[proof_id]
                        # Distribute reward to proof submitter (mock implementation)
                        logger.debug(f"Distributed {reward_per_proof} tokens to {proof.user_address}")
            
            return total_rewards
            
        except Exception as e:
            logger.error(f"Error distributing consensus rewards: {e}")
            return Decimal("0")
    
    async def _update_validator_reputations(self,
                                          consensus_round: ConsensusRound,
                                          consensus_reached: bool):
        """Update validator reputation scores based on consensus participation."""
        try:
            for validator_id, vote in consensus_round.votes.items():
                validator = self.validators.get(validator_id)
                if not validator:
                    continue
                
                # Update reputation based on vote accuracy
                if consensus_reached and vote:
                    # Correct vote for successful consensus
                    validator.reputation_score = min(1.0, validator.reputation_score + 0.01)
                elif not consensus_reached and not vote:
                    # Correct vote for failed consensus
                    validator.reputation_score = min(1.0, validator.reputation_score + 0.005)
                else:
                    # Incorrect vote
                    validator.reputation_score = max(0.1, validator.reputation_score - 0.02)
                
                # Update listening power based on reputation
                validator.listening_power = int(100 * validator.reputation_score)
            
        except Exception as e:
            logger.error(f"Error updating validator reputations: {e}")
    
    async def get_consensus_status(self) -> Dict[str, Any]:
        """Get current consensus system status."""
        try:
            active_validators = len([
                v for v in self.validators.values()
                if v.status == ValidatorStatus.ACTIVE
            ])
            
            total_proofs = len(self.listening_proofs)
            validated_proofs = len([
                p for p in self.listening_proofs.values()
                if p.validation_score > 0.5
            ])
            
            recent_rounds = [
                r for r in self.consensus_rounds.values()
                if (datetime.utcnow() - r.started_at).total_seconds() < 3600  # Last hour
            ]
            
            successful_rounds = len([r for r in recent_rounds if r.finalized])
            
            current_round_info = None
            if self.current_round:
                current_round_info = {
                    "round_id": self.current_round.round_id,
                    "round_number": self.current_round.round_number,
                    "proposer": self.current_round.proposer,
                    "validator_count": len(self.current_round.validators),
                    "proofs_included": len(self.current_round.proofs_included),
                    "votes_collected": len(self.current_round.votes),
                    "started_at": self.current_round.started_at.isoformat()
                }
            
            return {
                "consensus_type": ConsensusType.PROOF_OF_LISTEN,
                "active_validators": active_validators,
                "total_validators": len(self.validators),
                "total_proofs": total_proofs,
                "validated_proofs": validated_proofs,
                "validation_rate": round(validated_proofs / max(total_proofs, 1) * 100, 2),
                "recent_rounds": len(recent_rounds),
                "successful_rounds": successful_rounds,
                "success_rate": round(successful_rounds / max(len(recent_rounds), 1) * 100, 2),
                "current_round": current_round_info,
                "system_health": "healthy" if active_validators >= self.min_validators else "degraded"
            }
            
        except Exception as e:
            logger.error(f"Error getting consensus status: {e}")
            return {"error": str(e)}


class ProofOfEngagementValidator:
    """Proof-of-Engagement validation system."""
    
    def __init__(self, consensus_system: ProofOfListenConsensus):
        """Initialize engagement validator."""
        self.consensus_system = consensus_system
        self.engagement_proofs: Dict[str, EngagementProof] = {}
        self.engagement_weights = {
            "like": 1.0,
            "share": 2.0,
            "comment": 1.5,
            "playlist_add": 1.2,
            "follow_artist": 3.0,
            "purchase": 5.0
        }
    
    async def submit_engagement_proof(self,
                                    user_address: str,
                                    engagement_type: str,
                                    content_id: str,
                                    context_data: Dict[str, Any]) -> str:
        """Submit proof of engagement."""
        try:
            if engagement_type not in self.engagement_weights:
                raise ValueError(f"Engagement type {engagement_type} not supported")
            
            # Calculate engagement value
            base_value = self.engagement_weights[engagement_type]
            context_multiplier = self._calculate_context_multiplier(context_data)
            engagement_value = base_value * context_multiplier
            
            # Generate proof
            proof_id = f"engage_proof_{int(datetime.utcnow().timestamp())}_{hash(user_address)}"
            proof_data = {
                "user_address": user_address,
                "engagement_type": engagement_type,
                "content_id": content_id,
                "engagement_value": engagement_value,
                "context_data": context_data,
                "timestamp": datetime.utcnow().isoformat()
            }
            
            proof_hash = hashlib.sha256(json.dumps(proof_data, sort_keys=True).encode()).hexdigest()
            
            engagement_proof = EngagementProof(
                proof_id=proof_id,
                user_address=user_address,
                engagement_type=engagement_type,
                content_id=content_id,
                engagement_value=engagement_value,
                context_data=context_data,
                timestamp=datetime.utcnow(),
                proof_hash=proof_hash
            )
            
            self.engagement_proofs[proof_id] = engagement_proof
            
            # Validate engagement
            validation_score = await self._validate_engagement_proof(engagement_proof)
            engagement_proof.validation_score = validation_score
            
            logger.info(f"Submitted engagement proof {proof_id}: {engagement_type} with value {engagement_value}")
            return proof_id
            
        except Exception as e:
            logger.error(f"Error submitting engagement proof: {e}")
            raise
    
    def _calculate_context_multiplier(self, context_data: Dict[str, Any]) -> float:
        """Calculate context multiplier for engagement value."""
        multiplier = 1.0
        
        # Time-based multiplier
        if "time_spent_before_action" in context_data:
            time_spent = context_data["time_spent_before_action"]
            if time_spent > 60:  # More than 1 minute
                multiplier *= 1.2
            elif time_spent < 10:  # Less than 10 seconds
                multiplier *= 0.8
        
        # Authenticity signals
        if context_data.get("human_verification", False):
            multiplier *= 1.5
        
        if context_data.get("social_verification", False):
            multiplier *= 1.3
        
        # Frequency penalty for repeated actions
        recent_actions = context_data.get("recent_similar_actions", 0)
        if recent_actions > 5:
            multiplier *= 0.7
        
        return multiplier
    
    async def _validate_engagement_proof(self, proof: EngagementProof) -> float:
        """Validate engagement proof."""
        try:
            validation_score = 1.0
            
            # Check for spam patterns
            if self._is_spam_engagement(proof):
                validation_score *= 0.2
            
            # Check engagement value reasonableness
            if proof.engagement_value > 10.0:  # Very high engagement
                validation_score *= 0.8
            
            # Check context data quality
            context_quality = self._assess_context_quality(proof.context_data)
            validation_score *= context_quality
            
            return max(0.0, min(validation_score, 1.0))
            
        except Exception as e:
            logger.error(f"Error validating engagement proof: {e}")
            return 0.0
    
    def _is_spam_engagement(self, proof: EngagementProof) -> bool:
        """Check if engagement appears to be spam."""
        # Check for rapid repeated engagements
        recent_proofs = [
            p for p in self.engagement_proofs.values()
            if (p.user_address == proof.user_address and
                p.engagement_type == proof.engagement_type and
                abs((p.timestamp - proof.timestamp).total_seconds()) < 300)  # 5 minutes
        ]
        
        return len(recent_proofs) > 3
    
    def _assess_context_quality(self, context_data: Dict[str, Any]) -> float:
        """Assess quality of context data."""
        quality_score = 1.0
        
        # Check for required fields
        required_fields = ["time_spent_before_action", "user_agent", "ip_hash"]
        missing_fields = sum(1 for field in required_fields if field not in context_data)
        quality_score *= (1.0 - missing_fields * 0.1)
        
        # Check for verification signals
        if context_data.get("human_verification"):
            quality_score *= 1.2
        
        if context_data.get("device_fingerprint"):
            quality_score *= 1.1
        
        return max(0.1, quality_score)


class ReputationSystem:
    """Reputation-based consensus system."""
    
    def __init__(self):
        """Initialize reputation system."""
        self.user_reputations: Dict[str, float] = {}
        self.reputation_history: Dict[str, List[Dict[str, Any]]] = {}
    
    async def update_user_reputation(self,
                                   user_address: str,
                                   action: str,
                                   impact: float,
                                   context: Dict[str, Any]) -> float:
        """Update user reputation based on action."""
        try:
            current_reputation = self.user_reputations.get(user_address, 0.5)  # Start at neutral
            
            # Calculate reputation change
            reputation_change = self._calculate_reputation_change(action, impact, context)
            new_reputation = max(0.0, min(1.0, current_reputation + reputation_change))
            
            # Update reputation
            self.user_reputations[user_address] = new_reputation
            
            # Record history
            if user_address not in self.reputation_history:
                self.reputation_history[user_address] = []
            
            self.reputation_history[user_address].append({
                "action": action,
                "impact": impact,
                "reputation_change": reputation_change,
                "new_reputation": new_reputation,
                "timestamp": datetime.utcnow().isoformat(),
                "context": context
            })
            
            logger.info(f"Updated reputation for {user_address}: {new_reputation} (change: {reputation_change})")
            return new_reputation
            
        except Exception as e:
            logger.error(f"Error updating user reputation: {e}")
            return self.user_reputations.get(user_address, 0.5)
    
    def _calculate_reputation_change(self,
                                   action: str,
                                   impact: float,
                                   context: Dict[str, Any]) -> float:
        """Calculate reputation change for an action."""
        base_changes = {
            "quality_listening": 0.01,
            "verified_engagement": 0.02,
            "content_creation": 0.05,
            "spam_behavior": -0.1,
            "manipulation_attempt": -0.2,
            "community_contribution": 0.03
        }
        
        base_change = base_changes.get(action, 0.0)
        
        # Apply impact multiplier
        change = base_change * impact
        
        # Apply context modifiers
        if context.get("verified", False):
            change *= 1.5
        
        if context.get("peer_reviewed", False):
            change *= 1.2
        
        return change
    
    async def get_user_reputation(self, user_address: str) -> Dict[str, Any]:
        """Get user reputation details."""
        try:
            reputation = self.user_reputations.get(user_address, 0.5)
            history = self.reputation_history.get(user_address, [])
            
            # Calculate reputation tier
            if reputation >= 0.9:
                tier = "diamond"
            elif reputation >= 0.8:
                tier = "platinum"
            elif reputation >= 0.7:
                tier = "gold"
            elif reputation >= 0.6:
                tier = "silver"
            else:
                tier = "bronze"
            
            return {
                "user_address": user_address,
                "reputation_score": reputation,
                "reputation_tier": tier,
                "total_actions": len(history),
                "recent_changes": history[-10:] if history else [],
                "reputation_trend": self._calculate_reputation_trend(history)
            }
            
        except Exception as e:
            logger.error(f"Error getting user reputation: {e}")
            return {"error": str(e)}
    
    def _calculate_reputation_trend(self, history: List[Dict[str, Any]]) -> str:
        """Calculate reputation trend from history."""
        if len(history) < 5:
            return "neutral"
        
        recent_changes = [h["reputation_change"] for h in history[-5:]]
        avg_change = sum(recent_changes) / len(recent_changes)
        
        if avg_change > 0.01:
            return "improving"
        elif avg_change < -0.01:
            return "declining"
        else:
            return "stable"


class ConsensusMetrics:
    """Consensus system performance metrics."""
    
    def __init__(self, consensus_system: ProofOfListenConsensus):
        """Initialize consensus metrics."""
        self.consensus_system = consensus_system
        self.metrics_history: List[Dict[str, Any]] = []
    
    async def collect_metrics(self) -> Dict[str, Any]:
        """Collect current consensus metrics."""
        try:
            metrics = {
                "timestamp": datetime.utcnow().isoformat(),
                "validator_count": len([
                    v for v in self.consensus_system.validators.values()
                    if v.status == ValidatorStatus.ACTIVE
                ]),
                "total_proofs": len(self.consensus_system.listening_proofs),
                "round_count": len(self.consensus_system.consensus_rounds),
                "finalized_rounds": len([
                    r for r in self.consensus_system.consensus_rounds.values()
                    if r.finalized
                ]),
                "average_validation_score": self._calculate_average_validation_score(),
                "network_participation": self._calculate_network_participation(),
                "consensus_efficiency": self._calculate_consensus_efficiency()
            }
            
            # Store metrics
            self.metrics_history.append(metrics)
            
            # Keep only last 100 metrics
            if len(self.metrics_history) > 100:
                self.metrics_history = self.metrics_history[-100:]
            
            return metrics
            
        except Exception as e:
            logger.error(f"Error collecting consensus metrics: {e}")
            return {"error": str(e)}
    
    def _calculate_average_validation_score(self) -> float:
        """Calculate average validation score of all proofs."""
        proofs = list(self.consensus_system.listening_proofs.values())
        if not proofs:
            return 0.0
        
        total_score = sum(p.validation_score for p in proofs)
        return total_score / len(proofs)
    
    def _calculate_network_participation(self) -> float:
        """Calculate network participation rate."""
        active_validators = len([
            v for v in self.consensus_system.validators.values()
            if v.status == ValidatorStatus.ACTIVE
        ])
        
        total_validators = len(self.consensus_system.validators)
        if total_validators == 0:
            return 0.0
        
        return active_validators / total_validators
    
    def _calculate_consensus_efficiency(self) -> float:
        """Calculate consensus efficiency (successful rounds / total rounds)."""
        rounds = list(self.consensus_system.consensus_rounds.values())
        if not rounds:
            return 0.0
        
        successful_rounds = len([r for r in rounds if r.finalized])
        return successful_rounds / len(rounds)
    
    async def generate_performance_report(self, hours: int = 24) -> Dict[str, Any]:
        """Generate consensus performance report."""
        try:
            cutoff_time = datetime.utcnow() - timedelta(hours=hours)
            
            # Filter recent metrics
            recent_metrics = [
                m for m in self.metrics_history
                if datetime.fromisoformat(m["timestamp"]) >= cutoff_time
            ]
            
            if not recent_metrics:
                return {"message": "No metrics available for the specified period"}
            
            # Calculate performance statistics
            avg_validation_score = np.mean([m["average_validation_score"] for m in recent_metrics])
            avg_participation = np.mean([m["network_participation"] for m in recent_metrics])
            avg_efficiency = np.mean([m["consensus_efficiency"] for m in recent_metrics])
            
            # Calculate trends
            validation_trend = self._calculate_trend([m["average_validation_score"] for m in recent_metrics])
            participation_trend = self._calculate_trend([m["network_participation"] for m in recent_metrics])
            efficiency_trend = self._calculate_trend([m["consensus_efficiency"] for m in recent_metrics])
            
            return {
                "report_period_hours": hours,
                "metrics_collected": len(recent_metrics),
                "performance_averages": {
                    "validation_score": round(avg_validation_score, 3),
                    "network_participation": round(avg_participation, 3),
                    "consensus_efficiency": round(avg_efficiency, 3)
                },
                "performance_trends": {
                    "validation_score": validation_trend,
                    "network_participation": participation_trend,
                    "consensus_efficiency": efficiency_trend
                },
                "current_status": await self.consensus_system.get_consensus_status(),
                "generated_at": datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Error generating performance report: {e}")
            return {"error": str(e)}
    
    def _calculate_trend(self, values: List[float]) -> str:
        """Calculate trend from list of values."""
        if len(values) < 2:
            return "insufficient_data"
        
        # Simple linear trend calculation
        x = list(range(len(values)))
        slope = np.polyfit(x, values, 1)[0]
        
        if slope > 0.01:
            return "improving"
        elif slope < -0.01:
            return "declining"
        else:
            return "stable"
