"""Double Signing Detection for Blockchain Consensus Security
=========================================================

Detects and prevents double signing attacks in blockchain consensus,
a critical security mechanism for maintaining network integrity.

Author: Fahed Mlaiel <mlaiel@live.de>
⚠️ STRICT COPYRIGHT WARNING - Unauthorized use prohibited ⚠️
"""
import asyncio
import logging
import hashlib
from datetime import datetime, timedelta
from typing import Dict, List, Optional, Any, Set, Tuple
from dataclasses import dataclass, field
from enum import Enum
import json

logger = logging.getLogger(__name__)

class ViolationType(Enum):
    """Types of double signing violations."""
    DOUBLE_SIGN_BLOCK = "double_sign_block"
    DOUBLE_SIGN_VOTE = "double_sign_vote"
    CONFLICTING_PROPOSAL = "conflicting_proposal"
    INVALID_SIGNATURE = "invalid_signature"

class EvidenceStatus(Enum):
    """Status of slashing evidence."""
    PENDING = "pending"
    VERIFIED = "verified"
    DISPUTED = "disputed"
    EXECUTED = "executed"
    REJECTED = "rejected"

@dataclass
class DoubleSignEvidence:
    """Evidence of double signing violation."""
    validator_id: str
    violation_type: ViolationType
    block_height: int
    timestamp: datetime
    evidence_hash: str
    signature_a: str
    signature_b: str
    block_hash_a: str
    block_hash_b: str
    consensus_round: int
    evidence_data: Dict[str, Any] = field(default_factory=dict)
    status: EvidenceStatus = EvidenceStatus.PENDING
    severity_score: float = 0.0
    reporter_id: Optional[str] = None

@dataclass
class ValidatorSigningRecord:
    """Record of validator signing activity."""
    validator_id: str
    last_signed_height: int
    last_signed_hash: str
    signature_count: int = 0
    violation_count: int = 0
    reputation_score: float = 1.0
    signing_history: List[Dict] = field(default_factory=list)

class DoubleSigningDetector:
    """
    Advanced double signing detection system with AI-powered analysis
    and real-time monitoring for blockchain consensus security.
    """
    
    def __init__(self, config: Dict[str, Any] = None):
        self.config = config or {}
        self.signing_records: Dict[str, ValidatorSigningRecord] = {}
        self.evidence_cache: List[DoubleSignEvidence] = []
        self.active_monitoring = True
        
        # Configuration parameters
        self.max_evidence_age = timedelta(days=7)  # Keep evidence for 7 days
        self.min_severity_threshold = 0.7  # Minimum severity for automatic slashing
        self.reputation_decay_rate = 0.95  # Daily reputation decay for violations
        
        # Advanced detection parameters
        self.time_window_seconds = 30  # Time window to check for double signing
        self.max_concurrent_proposals = 1  # Max proposals a validator can make simultaneously
        
        logger.info("DoubleSigningDetector initialized with advanced security monitoring")
    
    async def detect_double_signing(self, 
                                  validator_id: str,
                                  block_height: int,
                                  block_hash: str,
                                  signature: str,
                                  timestamp: datetime = None) -> Optional[DoubleSignEvidence]:
        """
        Detect double signing violations in real-time.
        
        Args:
            validator_id: ID of the validator
            block_height: Block height being signed
            block_hash: Hash of the block being signed
            signature: Cryptographic signature
            timestamp: Time of signing (default: now)
            
        Returns:
            DoubleSignEvidence if violation detected, None otherwise
        """
        if timestamp is None:
            timestamp = datetime.now()
        
        logger.debug(f"Checking double signing for validator {validator_id} at height {block_height}")
        
        # Get or create signing record for validator
        if validator_id not in self.signing_records:
            self.signing_records[validator_id] = ValidatorSigningRecord(
                validator_id=validator_id,
                last_signed_height=0,
                last_signed_hash=""
            )
        
        record = self.signing_records[validator_id]
        
        # Check for double signing at same height
        violation = await self._check_height_double_signing(
            record, block_height, block_hash, signature, timestamp
        )
        
        if violation:
            logger.warning(f"Double signing detected: {violation.validator_id} at height {violation.block_height}")
            
            # Add to evidence cache
            self.evidence_cache.append(violation)
            
            # Update validator reputation
            await self._update_validator_reputation(validator_id, -0.3)  # Significant penalty
            
            # Trigger immediate security response
            await self._trigger_security_response(violation)
            
            return violation
        
        # Update signing record (no violation)
        await self._update_signing_record(record, block_height, block_hash, signature, timestamp)
        
        return None
    
    async def _check_height_double_signing(self,
                                         record: ValidatorSigningRecord,
                                         block_height: int,
                                         block_hash: str,
                                         signature: str,
                                         timestamp: datetime) -> Optional[DoubleSignEvidence]:
        """Check for double signing at the same block height."""
        
        # Look for recent signings at the same height
        recent_signings = [
            entry for entry in record.signing_history
            if (entry['height'] == block_height and 
                timestamp - entry['timestamp'] < timedelta(seconds=self.time_window_seconds))
        ]
        
        for existing_signing in recent_signings:
            if existing_signing['block_hash'] != block_hash:
                # Double signing detected!
                violation_hash = self._generate_evidence_hash(
                    record.validator_id, block_height, block_hash, existing_signing['block_hash']
                )
                
                severity = await self._calculate_violation_severity(
                    record, block_height, existing_signing
                )
                
                evidence = DoubleSignEvidence(
                    validator_id=record.validator_id,
                    violation_type=ViolationType.DOUBLE_SIGN_BLOCK,
                    block_height=block_height,
                    timestamp=timestamp,
                    evidence_hash=violation_hash,
                    signature_a=signature,
                    signature_b=existing_signing['signature'],
                    block_hash_a=block_hash,
                    block_hash_b=existing_signing['block_hash'],
                    consensus_round=0,  # Could be extracted from context
                    status=EvidenceStatus.PENDING,
                    severity_score=severity
                )
                
                return evidence
        
        return None
    
    async def _calculate_violation_severity(self,
                                          record: ValidatorSigningRecord,
                                          block_height: int,
                                          existing_signing: Dict) -> float:
        """Calculate the severity score of a violation (0.0 to 1.0)."""
        base_severity = 0.8  # Base severity for double signing
        
        # Factors that increase severity
        severity_factors = []
        
        # Reputation factor (lower reputation = higher severity)
        reputation_factor = (1.0 - record.reputation_score) * 0.2
        severity_factors.append(reputation_factor)
        
        # Repeat offender factor
        if record.violation_count > 0:
            repeat_factor = min(record.violation_count * 0.1, 0.3)
            severity_factors.append(repeat_factor)
        
        # Time proximity factor (closer in time = more severe)
        time_diff = abs((datetime.now() - existing_signing['timestamp']).total_seconds())
        if time_diff < 10:  # Very close in time
            time_factor = 0.2
        elif time_diff < 30:  # Within time window
            time_factor = 0.1
        else:
            time_factor = 0.0
        severity_factors.append(time_factor)
        
        # Calculate final severity
        final_severity = min(base_severity + sum(severity_factors), 1.0)
        
        logger.debug(f"Calculated violation severity: {final_severity} for validator {record.validator_id}")
        return final_severity
    
    async def _update_signing_record(self,
                                   record: ValidatorSigningRecord,
                                   block_height: int,
                                   block_hash: str,
                                   signature: str,
                                   timestamp: datetime):
        """Update validator's signing record."""
        
        # Add to signing history
        signing_entry = {
            'height': block_height,
            'block_hash': block_hash,
            'signature': signature,
            'timestamp': timestamp
        }
        record.signing_history.append(signing_entry)
        
        # Keep only recent history (for performance)
        cutoff_time = timestamp - timedelta(hours=24)
        record.signing_history = [
            entry for entry in record.signing_history
            if entry['timestamp'] > cutoff_time
        ]
        
        # Update record
        record.last_signed_height = block_height
        record.last_signed_hash = block_hash
        record.signature_count += 1
        
        logger.debug(f"Updated signing record for validator {record.validator_id}")
    
    async def _update_validator_reputation(self, validator_id: str, change: float):
        """Update validator reputation score."""
        if validator_id in self.signing_records:
            record = self.signing_records[validator_id]
            old_reputation = record.reputation_score
            record.reputation_score = max(0.0, min(1.0, record.reputation_score + change))
            
            if change < 0:
                record.violation_count += 1
            
            logger.info(f"Validator {validator_id} reputation: {old_reputation:.3f} → {record.reputation_score:.3f}")
    
    def _generate_evidence_hash(self, validator_id: str, height: int, hash_a: str, hash_b: str) -> str:
        """Generate unique hash for evidence."""
        evidence_string = f"{validator_id}_{height}_{hash_a}_{hash_b}_{datetime.now().isoformat()}"
        return hashlib.sha256(evidence_string.encode()).hexdigest()
    
    async def _trigger_security_response(self, evidence: DoubleSignEvidence):
        """Trigger immediate security response to double signing."""
        logger.critical(f"SECURITY ALERT: Double signing detected by validator {evidence.validator_id}")
        
        # Immediate actions
        actions_taken = []
        
        # 1. Alert monitoring systems
        await self._send_security_alert(evidence)
        actions_taken.append("security_alert_sent")
        
        # 2. If severity is high enough, recommend immediate slashing
        if evidence.severity_score >= self.min_severity_threshold:
            await self._recommend_immediate_slashing(evidence)
            actions_taken.append("slashing_recommended")
        
        # 3. Update network monitoring
        await self._update_network_monitoring(evidence)
        actions_taken.append("monitoring_updated")
        
        # 4. Log for forensic analysis
        await self._log_forensic_evidence(evidence)
        actions_taken.append("forensic_logged")
        
        logger.info(f"Security response completed: {', '.join(actions_taken)}")
    
    async def _send_security_alert(self, evidence: DoubleSignEvidence):
        """Send security alert to monitoring systems."""
        alert_data = {
            'type': 'double_signing_violation',
            'validator_id': evidence.validator_id,
            'severity': evidence.severity_score,
            'block_height': evidence.block_height,
            'timestamp': evidence.timestamp.isoformat(),
            'evidence_hash': evidence.evidence_hash
        }
        
        # Here you would integrate with your alert system
        # For now, we'll log it
        logger.critical(f"SECURITY ALERT: {json.dumps(alert_data, indent=2)}")
    
    async def _recommend_immediate_slashing(self, evidence: DoubleSignEvidence):
        """Recommend immediate slashing for severe violations."""
        logger.critical(f"RECOMMENDING IMMEDIATE SLASHING for validator {evidence.validator_id}")
        
        # Calculate slashing percentage based on severity
        slashing_percentage = min(evidence.severity_score * 0.05, 0.1)  # Max 10% slash
        
        slashing_recommendation = {
            'validator_id': evidence.validator_id,
            'evidence_hash': evidence.evidence_hash,
            'recommended_slash_percentage': slashing_percentage,
            'reason': 'double_signing_violation',
            'severity_score': evidence.severity_score,
            'auto_execute': evidence.severity_score >= 0.9  # Auto-execute for extreme cases
        }
        
        # Here you would send this to the slashing executor
        logger.critical(f"SLASHING RECOMMENDATION: {json.dumps(slashing_recommendation, indent=2)}")
    
    async def _update_network_monitoring(self, evidence: DoubleSignEvidence):
        """Update network monitoring with violation information."""
        # This would integrate with your network monitoring system
        logger.warning(f"Network monitoring updated with violation: {evidence.evidence_hash}")
    
    async def _log_forensic_evidence(self, evidence: DoubleSignEvidence):
        """Log evidence for forensic analysis."""
        forensic_log = {
            'timestamp': datetime.now().isoformat(),
            'evidence_type': 'double_signing',
            'validator_id': evidence.validator_id,
            'block_height': evidence.block_height,
            'evidence_hash': evidence.evidence_hash,
            'signatures': {
                'signature_a': evidence.signature_a,
                'signature_b': evidence.signature_b
            },
            'block_hashes': {
                'hash_a': evidence.block_hash_a,
                'hash_b': evidence.block_hash_b
            },
            'severity_score': evidence.severity_score,
            'status': evidence.status.value
        }
        
        # This would be stored in a secure forensic database
        logger.info(f"Forensic evidence logged: {evidence.evidence_hash}")
    
    async def get_validator_reputation(self, validator_id: str) -> float:
        """Get current reputation score for a validator."""
        if validator_id in self.signing_records:
            return self.signing_records[validator_id].reputation_score
        return 1.0  # New validators start with perfect reputation
    
    async def get_recent_violations(self, days: int = 7) -> List[DoubleSignEvidence]:
        """Get recent violations within specified days."""
        cutoff_time = datetime.now() - timedelta(days=days)
        return [
            evidence for evidence in self.evidence_cache
            if evidence.timestamp > cutoff_time
        ]
    
    async def verify_evidence(self, evidence_hash: str) -> bool:
        """Verify the authenticity of slashing evidence."""
        # Find evidence by hash
        evidence = None
        for e in self.evidence_cache:
            if e.evidence_hash == evidence_hash:
                evidence = e
                break
        
        if not evidence:
            logger.error(f"Evidence not found: {evidence_hash}")
            return False
        
        # Verify signatures and hashes
        # This would involve cryptographic verification
        # For now, we'll simulate verification
        
        logger.info(f"Evidence verification completed for: {evidence_hash}")
        evidence.status = EvidenceStatus.VERIFIED
        return True
    
    async def cleanup_old_evidence(self):
        """Clean up old evidence and signing records."""
        cutoff_time = datetime.now() - self.max_evidence_age
        
        # Clean evidence cache
        old_count = len(self.evidence_cache)
        self.evidence_cache = [
            evidence for evidence in self.evidence_cache
            if evidence.timestamp > cutoff_time
        ]
        
        # Clean signing history
        for record in self.signing_records.values():
            record.signing_history = [
                entry for entry in record.signing_history
                if entry['timestamp'] > cutoff_time
            ]
        
        cleaned_count = old_count - len(self.evidence_cache)
        if cleaned_count > 0:
            logger.info(f"Cleaned up {cleaned_count} old evidence records")

# Example usage in consensus monitoring
async def main():
    """Example usage of DoubleSigningDetector."""
    detector = DoubleSigningDetector()
    
    # Simulate normal signing
    evidence1 = await detector.detect_double_signing(
        validator_id="validator_001",
        block_height=1000,
        block_hash="hash_abc123",
        signature="sig_abc123"
    )
    print(f"First signing - Evidence: {evidence1}")
    
    # Simulate double signing (same height, different hash)
    evidence2 = await detector.detect_double_signing(
        validator_id="validator_001",
        block_height=1000,  # Same height!
        block_hash="hash_def456",  # Different hash!
        signature="sig_def456"
    )
    print(f"Double signing - Evidence: {evidence2 is not None}")
    
    if evidence2:
        print(f"Violation detected: {evidence2.violation_type.value}")
        print(f"Severity: {evidence2.severity_score}")
        
        # Verify evidence
        is_valid = await detector.verify_evidence(evidence2.evidence_hash)
        print(f"Evidence verification: {'PASSED' if is_valid else 'FAILED'}")

