#!/usr/bin/env python3
"""Consensus Alert Handler Module

This module provides specialized handlers for blockchain consensus-related alerts.
It contains business logic for detecting, processing, and responding to consensus
issues in the blockchain network.

Author: Fahed Mlaiel <mlaiel@live.de>
⚠️ STRICT COPYRIGHT WARNING - Unauthorized use prohibited ⚠️

Business Context:
- Part of Spotify AI Agent + Protection system
- Handles consensus monitoring for content creator protection workflow
- Ensures blockchain integrity for creator rights management
- Integrates with multi-format content upload and AI protection systems
"""
import asyncio
import logging
from datetime import datetime, timezone, timedelta
from typing import Dict, List, Optional, Any, Union, Tuple
from dataclasses import dataclass, asdict
from enum import Enum
import statistics
import numpy as np

from ..models.alert import Alert, AlertSeverity
from ..alert_manager import AlertManager


class ConsensusState(Enum):
    """Blockchain consensus states."""
    HEALTHY = "healthy"
    DEGRADED = "degraded"
    STALLED = "stalled"
    FORKED = "forked"
    PARTITIONED = "partitioned"
    RECOVERING = "recovering"


class ValidatorStatus(Enum):
    """Validator node status."""
    ACTIVE = "active"
    INACTIVE = "inactive"
    OFFLINE = "offline"
    SYNCING = "syncing"
    MISBEHAVING = "misbehaving"
    SLASHED = "slashed"


@dataclass
class ConsensusMetrics:
    """Blockchain consensus metrics."""
    participation_rate: float
    finalization_time: float
    last_finalized_block: int
    active_validators: int
    total_validators: int
    network_hash_rate: float
    fork_count: int
    stall_duration: float
    timestamp: datetime
    
    @property
    def participation_percentage(self) -> float:
        """Get participation rate as percentage."""
        return self.participation_rate * 100
    
    @property
    def validator_participation_rate(self) -> float:
        """Get validator participation rate."""
        if self.total_validators == 0:
            return 0.0
        return (self.active_validators / self.total_validators) * 100


@dataclass
class ValidatorInfo:
    """Information about a validator node."""
    validator_id: str
    address: str
    status: ValidatorStatus
    last_seen: datetime
    blocks_produced: int
    votes_cast: int
    stake_amount: float
    reputation_score: float
    uptime_percentage: float
    
    @property
    def is_healthy(self) -> bool:
        """Check if validator is in healthy state."""
        return (self.status == ValidatorStatus.ACTIVE and 
                self.uptime_percentage > 95.0 and
                self.reputation_score > 0.8)


class ConsensusAlertHandler:
    """
    Specialized handler for blockchain consensus monitoring alerts.
    
    Features:
    - Real-time consensus participation monitoring
    - Block finalization tracking and stall detection
    - Validator health monitoring and failure detection
    - Network partition detection and analysis
    - Fork detection and resolution tracking
    - Performance degradation analysis
    - Recovery monitoring and validation
    - Business impact assessment for creator platform
    """
    
    def __init__(self, alert_manager: AlertManager):
        """
        Initialize consensus alert handler.
        
        Args:
            alert_manager: Main alert manager instance
        """
        self.logger = logging.getLogger(__name__)
        self.alert_manager = alert_manager
        
        # Consensus monitoring state
        self.current_state = ConsensusState.HEALTHY
        self.metrics_history: List[ConsensusMetrics] = []
        self.validator_registry: Dict[str, ValidatorInfo] = {}
        
        # Alert thresholds (loaded from config)
        self.thresholds = {
            'participation_critical': 67.0,  # Below 67% participation = critical
            'participation_warning': 75.0,   # Below 75% = warning
            'finalization_critical': 600,    # 10 minutes without finalization = critical
            'finalization_warning': 300,     # 5 minutes = warning
            'validator_offline_critical': 33, # 33% validators offline = critical
            'validator_offline_warning': 20,  # 20% = warning
            'stall_emergency': 1800,          # 30 minutes stall = emergency
            'fork_critical': 3,               # 3+ forks = critical
            'partition_threshold': 40         # 40% network split = partition
        }
        
        # Business impact tracking
        self.business_impact_metrics = {
            'creator_uploads_affected': 0,
            'content_processing_delayed': 0,
            'rights_verification_failed': 0,
            'revenue_impact_estimated': 0.0
        }
        
        # Alert suppression and correlation
        self.active_consensus_alerts: Dict[str, Alert] = {}
        self.last_health_check = datetime.now(timezone.utc)
        
        self.logger.info("Consensus alert handler initialized")
    
    async def process_consensus_metrics(self, metrics: Dict[str, Any]) -> List[Alert]:
        """
        Process incoming consensus metrics and generate alerts.
        
        Args:
            metrics: Raw consensus metrics from blockchain node
            
        Returns:
            List[Alert]: Generated alerts
        """
        try:
            # Parse and validate metrics
            consensus_metrics = self._parse_metrics(metrics)
            
            # Store metrics history
            self.metrics_history.append(consensus_metrics)
            self._cleanup_old_metrics()
            
            # Analyze metrics and generate alerts
            alerts = []
            
            # Check participation rate
            participation_alerts = await self._check_participation_rate(consensus_metrics)
            alerts.extend(participation_alerts)
            
            # Check finalization status
            finalization_alerts = await self._check_finalization_status(consensus_metrics)
            alerts.extend(finalization_alerts)
            
            # Check for consensus stalls
            stall_alerts = await self._check_consensus_stalls(consensus_metrics)
            alerts.extend(stall_alerts)
            
            # Check for network partitions
            partition_alerts = await self._check_network_partitions(consensus_metrics)
            alerts.extend(partition_alerts)
            
            # Check for forks
            fork_alerts = await self._check_forks(consensus_metrics)
            alerts.extend(fork_alerts)
            
            # Update consensus state
            self._update_consensus_state(consensus_metrics)
            
            # Assess business impact
            await self._assess_business_impact(consensus_metrics, alerts)
            
            self.logger.debug(f"Processed consensus metrics, generated {len(alerts)} alerts")
            
            return alerts
            
        except Exception as e:
            self.logger.error(f"Failed to process consensus metrics: {e}")
            return []
    
    def _parse_metrics(self, raw_metrics: Dict[str, Any]) -> ConsensusMetrics:
        """
        Parse raw metrics into structured ConsensusMetrics object.
        
        Args:
            raw_metrics: Raw metrics from blockchain node
            
        Returns:
            ConsensusMetrics: Parsed metrics
        """
        return ConsensusMetrics(
            participation_rate=float(raw_metrics.get('participation_rate', 0.0)),
            finalization_time=float(raw_metrics.get('finalization_time', 0.0)),
            last_finalized_block=int(raw_metrics.get('last_finalized_block', 0)),
            active_validators=int(raw_metrics.get('active_validators', 0)),
            total_validators=int(raw_metrics.get('total_validators', 1)),
            network_hash_rate=float(raw_metrics.get('network_hash_rate', 0.0)),
            fork_count=int(raw_metrics.get('fork_count', 0)),
            stall_duration=float(raw_metrics.get('stall_duration', 0.0)),
            timestamp=datetime.now(timezone.utc)
        )
    
    def _cleanup_old_metrics(self):
        """Clean up old metrics to prevent memory bloat."""
        cutoff_time = datetime.now(timezone.utc) - timedelta(hours=24)
        self.metrics_history = [
            m for m in self.metrics_history 
            if m.timestamp > cutoff_time
        ]
    
    async def _check_participation_rate(self, metrics: ConsensusMetrics) -> List[Alert]:
        """
        Check consensus participation rate and generate alerts.
        
        Args:
            metrics: Current consensus metrics
            
        Returns:
            List[Alert]: Participation-related alerts
        """
        alerts = []
        participation_pct = metrics.participation_percentage
        
        # Critical participation threshold
        if participation_pct < self.thresholds['participation_critical']:
            alert = Alert(
                alert_type="consensus_participation_critical",
                title=f"Critical: Consensus Participation Dropped to {participation_pct:.1f}%",
                description=(
                    f"Blockchain consensus participation has dropped to {participation_pct:.1f}%, "
                    f"which is below the critical threshold of {self.thresholds['participation_critical']}%. "
                    f"This indicates a serious issue with validator nodes or network connectivity. "
                    f"Immediate action is required to prevent network instability."
                ),
                severity=AlertSeverity.CRITICAL,
                source="consensus_monitor",
                metadata={
                    'participation_rate': participation_pct,
                    'threshold': self.thresholds['participation_critical'],
                    'active_validators': metrics.active_validators,
                    'total_validators': metrics.total_validators,
                    'business_impact': 'high',
                    'creator_platform_affected': True
                }
            )
            alerts.append(alert)
            
        # Warning participation threshold
        elif participation_pct < self.thresholds['participation_warning']:
            alert = Alert(
                alert_type="consensus_participation_warning",
                title=f"Warning: Consensus Participation Below Normal at {participation_pct:.1f}%",
                description=(
                    f"Blockchain consensus participation is {participation_pct:.1f}%, "
                    f"which is below the warning threshold of {self.thresholds['participation_warning']}%. "
                    f"This may indicate validator issues or network degradation. "
                    f"Monitor closely and investigate potential causes."
                ),
                severity=AlertSeverity.HIGH,
                source="consensus_monitor",
                metadata={
                    'participation_rate': participation_pct,
                    'threshold': self.thresholds['participation_warning'],
                    'active_validators': metrics.active_validators,
                    'total_validators': metrics.total_validators,
                    'business_impact': 'medium',
                    'creator_platform_affected': False
                }
            )
            alerts.append(alert)
        
        return alerts
    
    async def _check_finalization_status(self, metrics: ConsensusMetrics) -> List[Alert]:
        """
        Check block finalization status and timing.
        
        Args:
            metrics: Current consensus metrics
            
        Returns:
            List[Alert]: Finalization-related alerts
        """
        alerts = []
        finalization_time = metrics.finalization_time
        
        # Critical finalization delay
        if finalization_time > self.thresholds['finalization_critical']:
            alert = Alert(
                alert_type="finalization_critical_delay",
                title=f"Critical: Block Finalization Delayed {finalization_time:.0f}s",
                description=(
                    f"Block finalization has been delayed for {finalization_time:.0f} seconds, "
                    f"exceeding the critical threshold of {self.thresholds['finalization_critical']}s. "
                    f"This indicates a serious consensus issue that may prevent transaction processing. "
                    f"Last finalized block: {metrics.last_finalized_block}. "
                    f"Immediate investigation required."
                ),
                severity=AlertSeverity.CRITICAL,
                source="consensus_monitor",
                metadata={
                    'finalization_time': finalization_time,
                    'threshold': self.thresholds['finalization_critical'],
                    'last_finalized_block': metrics.last_finalized_block,
                    'business_impact': 'critical',
                    'creator_uploads_blocked': True,
                    'content_processing_halted': True
                }
            )
            alerts.append(alert)
            
        # Warning finalization delay
        elif finalization_time > self.thresholds['finalization_warning']:
            alert = Alert(
                alert_type="finalization_warning_delay",
                title=f"Warning: Block Finalization Slow at {finalization_time:.0f}s",
                description=(
                    f"Block finalization is taking {finalization_time:.0f} seconds, "
                    f"which exceeds the warning threshold of {self.thresholds['finalization_warning']}s. "
                    f"This may indicate network congestion or validator performance issues. "
                    f"Monitor for continued degradation."
                ),
                severity=AlertSeverity.HIGH,
                source="consensus_monitor",
                metadata={
                    'finalization_time': finalization_time,
                    'threshold': self.thresholds['finalization_warning'],
                    'last_finalized_block': metrics.last_finalized_block,
                    'business_impact': 'medium',
                    'creator_uploads_affected': False
                }
            )
            alerts.append(alert)
        
        return alerts
    
    async def _check_consensus_stalls(self, metrics: ConsensusMetrics) -> List[Alert]:
        """
        Check for consensus stalls (complete halt of block production).
        
        Args:
            metrics: Current consensus metrics
            
        Returns:
            List[Alert]: Stall-related alerts
        """
        alerts = []
        stall_duration = metrics.stall_duration
        
        # Emergency stall threshold
        if stall_duration > self.thresholds['stall_emergency']:
            alert = Alert(
                alert_type="consensus_stalled_emergency",
                title=f"EMERGENCY: Consensus Stalled for {stall_duration/60:.1f} Minutes",
                description=(
                    f"🚨 CONSENSUS EMERGENCY 🚨\n"
                    f"Blockchain consensus has been completely stalled for {stall_duration/60:.1f} minutes. "
                    f"No blocks are being produced or finalized. This is a critical system failure "
                    f"that requires immediate emergency response. All transaction processing is halted. "
                    f"Activate incident response team immediately."
                ),
                severity=AlertSeverity.EMERGENCY,
                source="consensus_monitor",
                metadata={
                    'stall_duration': stall_duration,
                    'stall_duration_minutes': stall_duration / 60,
                    'last_finalized_block': metrics.last_finalized_block,
                    'participation_rate': metrics.participation_percentage,
                    'business_impact': 'critical',
                    'system_failure': True,
                    'emergency_response_required': True,
                    'creator_platform_down': True,
                    'revenue_impact': 'severe'
                }
            )
            alerts.append(alert)
        
        return alerts
    
    async def _check_network_partitions(self, metrics: ConsensusMetrics) -> List[Alert]:
        """
        Check for network partition scenarios.
        
        Args:
            metrics: Current consensus metrics
            
        Returns:
            List[Alert]: Partition-related alerts
        """
        alerts = []
        
        # Calculate partition risk based on validator participation
        offline_validators = metrics.total_validators - metrics.active_validators
        offline_percentage = (offline_validators / metrics.total_validators) * 100
        
        if offline_percentage > self.thresholds['partition_threshold']:
            alert = Alert(
                alert_type="network_partition_detected",
                title=f"Network Partition Risk: {offline_percentage:.1f}% Validators Offline",
                description=(
                    f"Potential network partition detected with {offline_percentage:.1f}% of validators offline. "
                    f"This may indicate a network split where different parts of the network "
                    f"cannot communicate with each other. "
                    f"Active validators: {metrics.active_validators}/{metrics.total_validators}. "
                    f"Investigation required to determine if this is a partition or widespread outage."
                ),
                severity=AlertSeverity.CRITICAL,
                source="consensus_monitor",
                metadata={
                    'offline_percentage': offline_percentage,
                    'active_validators': metrics.active_validators,
                    'total_validators': metrics.total_validators,
                    'partition_risk': 'high',
                    'business_impact': 'critical',
                    'network_split_suspected': True
                }
            )
            alerts.append(alert)
        
        return alerts
    
    async def _check_forks(self, metrics: ConsensusMetrics) -> List[Alert]:
        """
        Check for blockchain forks.
        
        Args:
            metrics: Current consensus metrics
            
        Returns:
            List[Alert]: Fork-related alerts
        """
        alerts = []
        
        if metrics.fork_count > self.thresholds['fork_critical']:
            alert = Alert(
                alert_type="blockchain_fork_critical",
                title=f"Critical: {metrics.fork_count} Blockchain Forks Detected",
                description=(
                    f"Multiple blockchain forks detected: {metrics.fork_count} active forks. "
                    f"This indicates serious consensus disagreement among validators. "
                    f"Fork resolution is required to maintain network integrity. "
                    f"Monitor for chain reorganizations and potential double-spend risks."
                ),
                severity=AlertSeverity.CRITICAL,
                source="consensus_monitor",
                metadata={
                    'fork_count': metrics.fork_count,
                    'threshold': self.thresholds['fork_critical'],
                    'consensus_disagreement': True,
                    'business_impact': 'high',
                    'chain_integrity_risk': True
                }
            )
            alerts.append(alert)
        
        return alerts
    
    def _update_consensus_state(self, metrics: ConsensusMetrics):
        """
        Update the current consensus state based on metrics.
        
        Args:
            metrics: Current consensus metrics
        """
        participation_pct = metrics.participation_percentage
        
        if metrics.stall_duration > self.thresholds['stall_emergency']:
            self.current_state = ConsensusState.STALLED
        elif participation_pct < self.thresholds['participation_critical']:
            self.current_state = ConsensusState.DEGRADED
        elif metrics.fork_count > self.thresholds['fork_critical']:
            self.current_state = ConsensusState.FORKED
        elif (metrics.total_validators - metrics.active_validators) / metrics.total_validators > 0.4:
            self.current_state = ConsensusState.PARTITIONED
        elif (self.current_state in [ConsensusState.STALLED, ConsensusState.DEGRADED] and
              participation_pct > self.thresholds['participation_warning']):
            self.current_state = ConsensusState.RECOVERING
        else:
            self.current_state = ConsensusState.HEALTHY
    
    async def _assess_business_impact(self, metrics: ConsensusMetrics, alerts: List[Alert]):
        """
        Assess business impact on creator platform and content protection.
        
        Args:
            metrics: Current consensus metrics
            alerts: Generated alerts
        """
        try:
            # Reset business impact metrics
            self.business_impact_metrics = {
                'creator_uploads_affected': 0,
                'content_processing_delayed': 0,
                'rights_verification_failed': 0,
                'revenue_impact_estimated': 0.0
            }
            
            # Calculate impact based on consensus state
            if self.current_state == ConsensusState.STALLED:
                # Complete system halt
                self.business_impact_metrics['creator_uploads_affected'] = 100  # 100% affected
                self.business_impact_metrics['content_processing_delayed'] = 100
                self.business_impact_metrics['rights_verification_failed'] = 100
                self.business_impact_metrics['revenue_impact_estimated'] = 10000.0  # $10k/hour estimate
                
            elif self.current_state == ConsensusState.DEGRADED:
                # Partial impact based on participation rate
                impact_factor = 1.0 - (metrics.participation_percentage / 100.0)
                self.business_impact_metrics['creator_uploads_affected'] = int(impact_factor * 100)
                self.business_impact_metrics['content_processing_delayed'] = int(impact_factor * 75)
                self.business_impact_metrics['rights_verification_failed'] = int(impact_factor * 50)
                self.business_impact_metrics['revenue_impact_estimated'] = impact_factor * 5000.0
            
            # Add business impact metadata to critical alerts
            for alert in alerts:
                if alert.severity in [AlertSeverity.EMERGENCY, AlertSeverity.CRITICAL]:
                    alert.metadata.update(self.business_impact_metrics)
                    
                    # Add specific business context
                    alert.metadata.update({
                        'spotify_ai_impact': True,
                        'creator_platform_status': self.current_state.value,
                        'content_protection_affected': self.current_state != ConsensusState.HEALTHY,
                        'multi_format_upload_impact': self.current_state in [
                            ConsensusState.STALLED, ConsensusState.DEGRADED
                        ]
                    })
            
        except Exception as e:
            self.logger.error(f"Failed to assess business impact: {e}")
    
    async def handle_validator_status_change(self, validator_id: str, 
                                           old_status: ValidatorStatus, 
                                           new_status: ValidatorStatus) -> List[Alert]:
        """
        Handle validator status changes and generate appropriate alerts.
        
        Args:
            validator_id: Validator identifier
            old_status: Previous validator status
            new_status: New validator status
            
        Returns:
            List[Alert]: Generated alerts
        """
        alerts = []
        
        try:
            # Get validator info
            validator_info = self.validator_registry.get(validator_id)
            if not validator_info:
                self.logger.warning(f"Unknown validator: {validator_id}")
                return alerts
            
            # Generate alert based on status change
            if new_status == ValidatorStatus.OFFLINE and old_status == ValidatorStatus.ACTIVE:
                alert = Alert(
                    alert_type="validator_offline",
                    title=f"Validator Offline: {validator_id}",
                    description=(
                        f"Validator {validator_id} has gone offline and is no longer "
                        f"participating in consensus. This may affect network security "
                        f"and block production efficiency."
                    ),
                    severity=AlertSeverity.HIGH,
                    source="validator_monitor",
                    metadata={
                        'validator_id': validator_id,
                        'old_status': old_status.value,
                        'new_status': new_status.value,
                        'validator_address': validator_info.address,
                        'stake_amount': validator_info.stake_amount,
                        'uptime_percentage': validator_info.uptime_percentage
                    }
                )
                alerts.append(alert)
                
            elif new_status == ValidatorStatus.SLASHED:
                alert = Alert(
                    alert_type="validator_slashed",
                    title=f"CRITICAL: Validator Slashed - {validator_id}",
                    description=(
                        f"Validator {validator_id} has been slashed for malicious behavior "
                        f"or protocol violations. This is a serious security event that "
                        f"requires immediate investigation."
                    ),
                    severity=AlertSeverity.CRITICAL,
                    source="validator_monitor",
                    metadata={
                        'validator_id': validator_id,
                        'slashing_event': True,
                        'security_incident': True,
                        'validator_address': validator_info.address,
                        'stake_amount': validator_info.stake_amount,
                        'reputation_score': validator_info.reputation_score
                    }
                )
                alerts.append(alert)
            
            return alerts
            
        except Exception as e:
            self.logger.error(f"Failed to handle validator status change: {e}")
            return []
    
    def get_consensus_health_summary(self) -> Dict[str, Any]:
        """
        Get comprehensive consensus health summary.
        
        Returns:
            Dict[str, Any]: Health summary
        """
        if not self.metrics_history:
            return {"status": "no_data", "error": "No metrics available"}
        
        latest_metrics = self.metrics_history[-1]
        
        # Calculate health score (0-100)
        health_score = 100.0
        
        # Penalize low participation
        if latest_metrics.participation_percentage < 95:
            health_score -= (95 - latest_metrics.participation_percentage) * 2
        
        # Penalize slow finalization
        if latest_metrics.finalization_time > 30:
            health_score -= min(latest_metrics.finalization_time - 30, 50)
        
        # Penalize stalls
        if latest_metrics.stall_duration > 0:
            health_score -= min(latest_metrics.stall_duration / 10, 50)
        
        # Penalize forks
        health_score -= latest_metrics.fork_count * 10
        
        health_score = max(0, health_score)
        
        return {
            "consensus_state": self.current_state.value,
            "health_score": round(health_score, 1),
            "participation_rate": latest_metrics.participation_percentage,
            "finalization_time": latest_metrics.finalization_time,
            "active_validators": latest_metrics.active_validators,
            "total_validators": latest_metrics.total_validators,
            "fork_count": latest_metrics.fork_count,
            "stall_duration": latest_metrics.stall_duration,
            "business_impact": self.business_impact_metrics,
            "last_updated": latest_metrics.timestamp.isoformat(),
            "active_alerts": len(self.active_consensus_alerts),
            "system_status": "operational" if health_score > 80 else "degraded" if health_score > 50 else "critical"
        }


# Export classes for use by other modules
__all__ = [
    'ConsensusAlertHandler',
    'ConsensusMetrics',
    'ValidatorInfo',
    'ConsensusState',
    'ValidatorStatus'
]
