from typing import Dict, List, Optional, Any, Union
from enum import Enum
from decimal import Decimal


class BlockchainNetwork(Enum):
    """Supported blockchain networks."""
    ETHEREUM = "ethereum"
    POLYGON = "polygon"
    BINANCE_SMART_CHAIN = "binance_smart_chain"
    AVALANCHE = "avalanche"
    SOLANA = "solana"
    CARDANO = "cardano"
    POLKADOT = "polkadot"
    NEAR = "near"
    FLOW = "flow"


class ContractType(Enum):
    """Types of smart contracts."""
    COLLABORATION_CONTRACT = "collaboration_contract"
    RIGHTS_MANAGEMENT = "rights_management"
    REVENUE_SHARING = "revenue_sharing"
    NFT_CREATOR = "nft_creator"
    ROYALTY_DISTRIBUTOR = "royalty_distributor"
    CONTENT_LICENSING = "content_licensing"
    DISPUTE_RESOLUTION = "dispute_resolution"


class NFTStandard(Enum):
    """NFT standards supported."""
    ERC721 = "erc721"
    ERC1155 = "erc1155"
    SPL_TOKEN = "spl_token"  # Solana
    NEP171 = "nep171"  # NEAR
    FLOW_NFT = "flow_nft"  # Flow


@dataclass
class NetworkConfiguration:
    """Configuration for a specific blockchain network."""
    network_name: str
    rpc_url: str
    chain_id: int
    currency_symbol: str
    block_explorer_url: str
    
    # Gas settings
    gas_limit: int = 200000
    max_gas_limit: int = 500000
    gas_price_gwei: Optional[int] = None
    max_fee_per_gas_gwei: Optional[int] = None
    max_priority_fee_per_gas_gwei: Optional[int] = None
    
    # Transaction settings
    confirmation_blocks: int = 3
    transaction_timeout_seconds: int = 300
    max_retry_attempts: int = 5
    
    # Network-specific settings
    supports_eip1559: bool = True
    supports_smart_contracts: bool = True
    supports_nfts: bool = True
    average_block_time_seconds: int = 15


