@dataclass
class BlockchainConfiguration:
    """Main blockchain configuration class."""
    # Network configurations
    enabled_networks: List[BlockchainNetwork] = field(default_factory=lambda: [
        BlockchainNetwork.ETHEREUM,
        BlockchainNetwork.POLYGON
    ])
    primary_network: BlockchainNetwork = BlockchainNetwork.POLYGON
    
    # Network settings
    network_configs: Dict[str, NetworkConfiguration] = field(default_factory=lambda: {
        "ethereum": NetworkConfiguration(
            network_name="Ethereum Mainnet",
            rpc_url="https://mainnet.infura.io/v3/" + os.getenv("INFURA_PROJECT_ID", ""),
            chain_id=1,
            currency_symbol="ETH",
            block_explorer_url="https://etherscan.io",
            gas_limit=200000,
            confirmation_blocks=3
        ),
        "polygon": NetworkConfiguration(
            network_name="Polygon Mainnet",
            rpc_url="https://polygon-rpc.com",
            chain_id=137,
            currency_symbol="MATIC",
            block_explorer_url="https://polygonscan.com",
            gas_limit=150000,
            confirmation_blocks=5
        )
    })
    
    # Component configurations
    contract_addresses: SmartContractAddresses = field(default_factory=SmartContractAddresses)
    ipfs_config: IPFSConfiguration = field(default_factory=IPFSConfiguration)
    nft_config: NFTConfiguration = field(default_factory=NFTConfiguration)
    revenue_sharing: RevenueSharing = field(default_factory=RevenueSharing)
    security: SecuritySettings = field(default_factory=SecuritySettings)
    
    # Global settings
    enable_blockchain_features: bool = True
    blockchain_service_timeout: int = 60
    max_concurrent_transactions: int = 5
    
    # Wallet configuration
    wallet_private_key: str = field(default_factory=lambda: os.getenv("BLOCKCHAIN_PRIVATE_KEY", ""))
    wallet_mnemonic: str = field(default_factory=lambda: os.getenv("WALLET_MNEMONIC", ""))
    
    # Development settings
    enable_testnet: bool = field(default_factory=lambda: os.getenv("ENVIRONMENT", "production") != "production")
    testnet_faucet_enabled: bool = True
    
    def validate_blockchain_configuration(self) -> List[str]:
        """Validate blockchain configuration settings."""
        errors = []
        
        if not self.enabled_networks:
            errors.append("At least one blockchain network must be enabled")
        
        if self.primary_network not in self.enabled_networks:
            errors.append("Primary network must be in enabled networks list")
        
        if not self.wallet_private_key and not self.wallet_mnemonic:
            errors.append("Either wallet private key or mnemonic must be provided")
        
        if self.revenue_sharing.platform_fee_percentage < 0 or \
           self.revenue_sharing.platform_fee_percentage > 100:
            errors.append("Platform fee percentage must be between 0 and 100")
        
        if self.nft_config.default_royalty_percentage > self.nft_config.max_royalty_percentage:
            errors.append("Default royalty percentage cannot exceed maximum")
        
        # Validate network configurations
        for network_name, network_config in self.network_configs.items():
            if not network_config.rpc_url:
                errors.append(f"RPC URL required for network: {network_name}")
            
            if network_config.chain_id <= 0:
                errors.append(f"Invalid chain ID for network: {network_name}")
        
        return errors
    
    def get_network_config(self, network: BlockchainNetwork) -> Optional[NetworkConfiguration]:
        """Get configuration for a specific network."""
        return self.network_configs.get(network.value)
    
    def get_contract_address(self, contract_type: ContractType, network: BlockchainNetwork) -> Optional[str]:
        """Get contract address for specific type and network."""
        contract_mappings = {
            ContractType.COLLABORATION_CONTRACT: self.contract_addresses.collaboration_factory,
            ContractType.RIGHTS_MANAGEMENT: self.contract_addresses.rights_management,
            ContractType.REVENUE_SHARING: self.contract_addresses.revenue_sharing,
            ContractType.NFT_CREATOR: self.contract_addresses.nft_creator,
            ContractType.ROYALTY_DISTRIBUTOR: self.contract_addresses.royalty_distributor
        }
        
        contract_dict = contract_mappings.get(contract_type, {})
        return contract_dict.get(network.value)


# Factory functions for different blockchain configurations
def create_minimal_blockchain_config() -> BlockchainConfiguration:
    """Create minimal blockchain configuration for basic features."""
    config = BlockchainConfiguration()
    config.enabled_networks = [BlockchainNetwork.POLYGON]
    config.nft_config.enable_batch_minting = False
    config.revenue_sharing.enable_automatic_distribution = False
    config.security.require_hardware_wallet = False
    return config


def create_enterprise_blockchain_config() -> BlockchainConfiguration:
    """Create enterprise blockchain configuration with all features."""
    config = BlockchainConfiguration()
    config.enabled_networks = [
        BlockchainNetwork.ETHEREUM,
        BlockchainNetwork.POLYGON,
        BlockchainNetwork.BINANCE_SMART_CHAIN
    ]
    config.security.require_hardware_wallet = True
    config.security.enable_multi_signature = True
    config.revenue_sharing.enable_automatic_distribution = True
    config.nft_config.enable_batch_minting = True
    config.max_concurrent_transactions = 20
    return config


def create_development_blockchain_config() -> BlockchainConfiguration:
    """Create development blockchain configuration for testing."""
    config = BlockchainConfiguration()
    config.enable_testnet = True
    config.testnet_faucet_enabled = True
    config.security.require_hardware_wallet = False
    config.security.enable_multi_signature = False
    config.blockchain_service_timeout = 30
    return config


# Default blockchain configuration
DEFAULT_BLOCKCHAIN_CONFIG = BlockchainConfiguration()
