class BudgetAllocationManager:
    """Manages treasury budget allocations."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        treasury_manager: TreasuryManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.treasury = treasury_manager
        
    async def create_budget_allocation(
        self,
        allocation_data: BudgetAllocation,
        governance_proposal_id: str
    ) -> Dict[str, Any]:
        """Create budget allocation for fiscal period."""
        try:
            allocation_id = str(uuid4())
            
            allocation = BudgetAllocationModel(
                id=allocation_id,
                fiscal_period=allocation_data.fiscal_period,
                category=allocation_data.category.value,
                allocated_amount=allocation_data.allocated_amount,
                currency=allocation_data.currency,
                governance_proposal_id=governance_proposal_id,
                approval_date=datetime.utcnow()
            )
            
            async with self.db.session() as session:
                session.add(allocation)
                await session.commit()
            
            logger.info(f"Budget allocation {allocation_id} created for {allocation_data.fiscal_period}")
            
            return {
                'allocation_id': allocation_id,
                'fiscal_period': allocation_data.fiscal_period,
                'category': allocation_data.category.value,
                'allocated_amount': str(allocation_data.allocated_amount),
                'created_at': allocation.created_at.isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to create budget allocation: {str(e)}")
            raise
    
    async def track_spending(
        self,
        allocation_id: str,
        amount: Decimal,
        description: str,
        transaction_id: str
    ) -> Dict[str, Any]:
        """Track spending against budget allocation."""
        try:
            async with self.db.session() as session:
                allocation = await session.get(BudgetAllocationModel, allocation_id)
                if not allocation:
                    raise ValueError("Budget allocation not found")
                
                # Update spent amount
                allocation.spent_amount = (allocation.spent_amount or 0) + amount
                
                # Update spending breakdown
                if not allocation.spending_breakdown:
                    allocation.spending_breakdown = {}
                
                spending_entry = {
                    'amount': str(amount),
                    'description': description,
                    'transaction_id': transaction_id,
                    'timestamp': datetime.utcnow().isoformat()
                }
                
                if 'transactions' not in allocation.spending_breakdown:
                    allocation.spending_breakdown['transactions'] = []
                allocation.spending_breakdown['transactions'].append(spending_entry)
                
                # Update utilization rate
                allocation.utilization_rate = float(allocation.spent_amount / allocation.allocated_amount)
                allocation.updated_at = datetime.utcnow()
                
                await session.commit()
            
            return {
                'allocation_id': allocation_id,
                'spent_amount': str(amount),
                'total_spent': str(allocation.spent_amount),
                'utilization_rate': allocation.utilization_rate,
                'updated_at': allocation.updated_at.isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to track spending: {str(e)}")
            raise
    
    async def get_budget_summary(
        self,
        fiscal_period: str
    ) -> Dict[str, Any]:
        """Get budget summary for fiscal period."""
        try:
            async with self.db.session() as session:
                allocations = await session.query(BudgetAllocationModel).filter(
                    BudgetAllocationModel.fiscal_period == fiscal_period
                ).all()
                
                summary = {
                    'fiscal_period': fiscal_period,
                    'total_allocated': Decimal('0'),
                    'total_spent': Decimal('0'),
                    'total_committed': Decimal('0'),
                    'categories': {},
                    'overall_utilization': 0.0
                }
                
                for allocation in allocations:
                    summary['total_allocated'] += allocation.allocated_amount
                    summary['total_spent'] += allocation.spent_amount or 0
                    summary['total_committed'] += allocation.committed_amount or 0
                    
                    summary['categories'][allocation.category] = {
                        'allocated': str(allocation.allocated_amount),
                        'spent': str(allocation.spent_amount or 0),
                        'committed': str(allocation.committed_amount or 0),
                        'utilization_rate': allocation.utilization_rate
                    }
                
                if summary['total_allocated'] > 0:
                    summary['overall_utilization'] = float(
                        summary['total_spent'] / summary['total_allocated']
                    )
                
                # Convert Decimal to string for JSON serialization
                summary['total_allocated'] = str(summary['total_allocated'])
                summary['total_spent'] = str(summary['total_spent'])
                summary['total_committed'] = str(summary['total_committed'])
                
                return summary
                
        except Exception as e:
            logger.error(f"Failed to get budget summary: {str(e)}")
            return {}


class TreasuryAnalytics:
    """Analytics for treasury operations."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        analytics_manager: AnalyticsManager
    ):
        self.db = db_connection
        self.analytics = analytics_manager
        
    async def calculate_funding_roi(
        self,
        proposal_id: str
    ) -> Dict[str, Any]:
        """Calculate ROI for funded proposal."""
        try:
            async with self.db.session() as session:
                proposal = await session.get(FundingProposalModel, proposal_id)
                if not proposal:
                    return {}
                
                # Get success metrics and actual performance
                success_metrics = proposal.success_metrics or []
                actual_performance = await self._get_actual_performance(proposal_id)
                
                roi_analysis = {
                    'proposal_id': proposal_id,
                    'investment': str(proposal.disbursed_amount or 0),
                    'currency': proposal.currency,
                    'duration_months': proposal.project_duration_months,
                    'success_metrics': success_metrics,
                    'actual_performance': actual_performance,
                    'roi_score': 0.0,
                    'impact_assessment': {}
                }
                
                # Calculate ROI based on metrics achievement
                if success_metrics and actual_performance:
                    achievement_scores = []
                    for metric in success_metrics:
                        metric_name = metric['name']
                        target_value = metric['target_value']
                        actual_value = actual_performance.get(metric_name, 0)
                        
                        if target_value > 0:
                            achievement_ratio = actual_value / target_value
                            achievement_scores.append(min(achievement_ratio, 2.0))  # Cap at 200%
                    
                    if achievement_scores:
                        roi_analysis['roi_score'] = sum(achievement_scores) / len(achievement_scores)
                
                return roi_analysis
                
        except Exception as e:
            logger.error(f"Failed to calculate funding ROI: {str(e)}")
            return {}
    
    async def get_treasury_health_metrics(self) -> Dict[str, Any]:
        """Get overall treasury health metrics."""
        try:
            # Get current treasury balance
            treasury_balance = await self.analytics.get_treasury_balance()
            
            # Get funding velocity
            funding_velocity = await self._calculate_funding_velocity()
            
            # Get success rate
            success_rate = await self._calculate_funding_success_rate()
            
            # Get diversification metrics
            diversification = await self._calculate_portfolio_diversification()
            
            health_metrics = {
                'treasury_balance': treasury_balance,
                'funding_velocity': funding_velocity,
                'success_rate': success_rate,
                'portfolio_diversification': diversification,
                'health_score': 0.0,
                'recommendations': [],
                'calculated_at': datetime.utcnow().isoformat()
            }
            
            # Calculate overall health score
            scores = [
                funding_velocity.get('score', 0.5),
                success_rate.get('score', 0.5),
                diversification.get('score', 0.5)
            ]
            health_metrics['health_score'] = sum(scores) / len(scores)
            
            # Generate recommendations
            if health_metrics['health_score'] < 0.6:
                health_metrics['recommendations'].append("Consider reviewing funding criteria")
            if funding_velocity.get('score', 0.5) < 0.4:
                health_metrics['recommendations'].append("Funding velocity is low")
            
            return health_metrics
            
        except Exception as e:
            logger.error(f"Failed to get treasury health metrics: {str(e)}")
            return {}
    
