import asyncio
import math
from abc import ABC, abstractmethod
from datetime import datetime, timedelta
from enum import Enum
from typing import Dict, List, Optional, Union, Any, Tuple
from dataclasses import dataclass
from uuid import uuid4

import numpy as np
from pydantic import BaseModel, Field
from sqlalchemy import Column, String, DateTime, Integer, Float, Boolean, JSON, ForeignKey
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import relationship

from ....core.database import DatabaseConnection
from ....core.cache import CacheManager
from ....core.security import SecurityManager
from ....utils.logger import get_logger
from .proposal_manager import ProposalStatus

logger = get_logger(__name__)
Base = declarative_base()


class VoteType(Enum):
    """Types of votes that can be cast."""
    FOR = "for"
    AGAINST = "against"
    ABSTAIN = "abstain"


class VotingPowerSource(Enum):
    """Sources of voting power."""
    TOKEN_BALANCE = "token_balance"
    REPUTATION_SCORE = "reputation_score"
    DELEGATED_POWER = "delegated_power"
    STAKED_TOKENS = "staked_tokens"
    HYBRID_CALCULATION = "hybrid_calculation"


@dataclass
class VoteWeight:
    """Represents the weight and source of a vote."""
    base_weight: float
    adjusted_weight: float
    source: VotingPowerSource
    multipliers: Dict[str, float]
    decay_factor: float = 1.0


@dataclass
class VotingPower:
    """Comprehensive voting power calculation."""
    user_id: str
    total_power: float
    token_power: float
    reputation_power: float
    delegated_power: float
    stake_multiplier: float
    participation_bonus: float
    calculated_at: datetime


class VoteModel(Base):
    """SQLAlchemy model for individual votes."""
    __tablename__ = "governance_votes"
    
    id = Column(String, primary_key=True)
    proposal_id = Column(String, ForeignKey('governance_proposals.id'), nullable=False)
    voter_id = Column(String, nullable=False)
    vote_type = Column(String(10), nullable=False)
    voting_power = Column(Float, nullable=False)
    weight_breakdown = Column(JSON)
    timestamp = Column(DateTime, default=datetime.utcnow)
    signature = Column(String)
    is_delegated = Column(Boolean, default=False)
    delegator_id = Column(String)
    metadata = Column(JSON)


class DelegationModel(Base):
    """SQLAlchemy model for vote delegations."""
    __tablename__ = "vote_delegations"
    
    id = Column(String, primary_key=True)
    delegator_id = Column(String, nullable=False)
    delegate_id = Column(String, nullable=False)
    proposal_id = Column(String, ForeignKey('governance_proposals.id'))
    delegation_type = Column(String(20), default="general")  # general, specific, category
    power_percentage = Column(Float, default=100.0)
    created_at = Column(DateTime, default=datetime.utcnow)
    expires_at = Column(DateTime)
    is_active = Column(Boolean, default=True)
    conditions = Column(JSON)


class VotingSystemInterface(ABC):
    """Abstract interface for voting systems."""
    
    @abstractmethod
    async def calculate_voting_power(self, user_id: str, proposal_id: str) -> VotingPower:
        """Calculate voting power for a user on a specific proposal."""
        pass
    
    @abstractmethod
    async def cast_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType,
        signature: str
    ) -> Dict[str, Any]:
        """Cast a vote on a proposal."""
        pass
    
    @abstractmethod
    async def validate_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType
    ) -> Tuple[bool, List[str]]:
        """Validate if a vote can be cast."""
        pass


class TokenBasedVoting(VotingSystemInterface):
    """Traditional token-weighted voting system."""
    
    def __init__(
        self, 
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        
    async def calculate_voting_power(self, user_id: str, proposal_id: str) -> VotingPower:
        """Calculate token-based voting power."""
        try:
            # Get user's token balance
            token_balance = await self._get_user_token_balance(user_id)
            
            # Get staking bonus
            stake_multiplier = await self._get_stake_multiplier(user_id)
            
            # Get participation bonus
            participation_bonus = await self._get_participation_bonus(user_id)
            
            # Calculate total power
            base_power = token_balance
            staked_power = base_power * stake_multiplier
            total_power = staked_power + participation_bonus
            
            return VotingPower(
                user_id=user_id,
                total_power=total_power,
                token_power=base_power,
                reputation_power=0.0,
                delegated_power=0.0,
                stake_multiplier=stake_multiplier,
                participation_bonus=participation_bonus,
                calculated_at=datetime.utcnow()
            )
            
        except Exception as e:
            logger.error(f"Failed to calculate token voting power for {user_id}: {str(e)}")
            return VotingPower(
                user_id=user_id,
                total_power=0.0,
                token_power=0.0,
                reputation_power=0.0,
                delegated_power=0.0,
                stake_multiplier=1.0,
                participation_bonus=0.0,
                calculated_at=datetime.utcnow()
            )
    
    async def cast_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType,
        signature: str
    ) -> Dict[str, Any]:
        """Cast a token-weighted vote."""
        try:
            # Validate vote
            is_valid, errors = await self.validate_vote(user_id, proposal_id, vote_type)
            if not is_valid:
                raise ValueError(f"Vote validation failed: {', '.join(errors)}")
            
            # Calculate voting power
            voting_power = await self.calculate_voting_power(user_id, proposal_id)
            
            # Verify signature
            vote_data = f"{user_id}{proposal_id}{vote_type.value}{voting_power.total_power}"
            if not await self.security.verify_signature(vote_data, signature, user_id):
                raise ValueError("Invalid vote signature")
            
            # Create vote record
            vote_id = str(uuid4())
            vote = VoteModel(
                id=vote_id,
                proposal_id=proposal_id,
                voter_id=user_id,
                vote_type=vote_type.value,
                voting_power=voting_power.total_power,
                weight_breakdown={
                    'token_power': voting_power.token_power,
                    'stake_multiplier': voting_power.stake_multiplier,
                    'participation_bonus': voting_power.participation_bonus
                },
                signature=signature,
                metadata={
                    'voting_system': 'token_based',
                    'calculation_timestamp': voting_power.calculated_at.isoformat()
                }
            )
            
            # Save vote
            async with self.db.session() as session:
                session.add(vote)
                await session.commit()
            
            # Update proposal vote counts
            await self._update_proposal_votes(proposal_id, vote_type, voting_power.total_power)
            
            # Cache vote
            await self.cache.set(
                f"vote:{proposal_id}:{user_id}",
                {
                    'vote_id': vote_id,
                    'vote_type': vote_type.value,
                    'voting_power': voting_power.total_power,
                    'timestamp': vote.timestamp.isoformat()
                },
                expire=86400
            )
            
            logger.info(f"Token vote cast: {user_id} voted {vote_type.value} on {proposal_id}")
            
            return {
                'vote_id': vote_id,
                'voting_power_used': voting_power.total_power,
                'vote_type': vote_type.value,
                'timestamp': vote.timestamp.isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to cast token vote: {str(e)}")
            raise
    
    async def validate_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType
    ) -> Tuple[bool, List[str]]:
        """Validate token-based vote."""
        errors = []
        
        # Check if user already voted
        existing_vote = await self.cache.get(f"vote:{proposal_id}:{user_id}")
        if existing_vote:
            errors.append("User has already voted on this proposal")
        
        # Check if proposal is in voting phase
        proposal_status = await self._get_proposal_status(proposal_id)
        if proposal_status != ProposalStatus.VOTING_ACTIVE.value:
            errors.append("Proposal is not in voting phase")
        
        # Check if user has minimum token balance
        token_balance = await self._get_user_token_balance(user_id)
        if token_balance < 1.0:
            errors.append("User does not have minimum token balance to vote")
        
        # Check if voting period is still active
        voting_end = await self._get_voting_end_time(proposal_id)
        if voting_end and datetime.utcnow() > voting_end:
            errors.append("Voting period has ended")
        
        return len(errors) == 0, errors
    
    async def _get_user_token_balance(self, user_id: str) -> float:
        """Get user's token balance."""
        # This would integrate with the token/wallet system
