class DelegatedVoting(VotingSystemInterface):
    """Delegated voting system allowing vote delegation."""
    
    def __init__(
        self, 
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        
    async def calculate_voting_power(self, user_id: str, proposal_id: str) -> VotingPower:
        """Calculate delegated voting power."""
        try:
            # Get user's own power
            own_power = await self._get_own_voting_power(user_id)
            
            # Get delegated power from others
            delegated_power = await self._get_delegated_power(user_id, proposal_id)
            
            total_power = own_power + delegated_power
            
            return VotingPower(
                user_id=user_id,
                total_power=total_power,
                token_power=own_power,
                reputation_power=0.0,
                delegated_power=delegated_power,
                stake_multiplier=1.0,
                participation_bonus=0.0,
                calculated_at=datetime.utcnow()
            )
            
        except Exception as e:
            logger.error(f"Failed to calculate delegated voting power for {user_id}: {str(e)}")
            return VotingPower(
                user_id=user_id,
                total_power=0.0,
                token_power=0.0,
                reputation_power=0.0,
                delegated_power=0.0,
                stake_multiplier=1.0,
                participation_bonus=0.0,
                calculated_at=datetime.utcnow()
            )
    
    async def cast_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType,
        signature: str
    ) -> Dict[str, Any]:
        """Cast a delegated vote."""
        return await self._cast_delegated_vote(user_id, proposal_id, vote_type, signature)
    
    async def validate_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType
    ) -> Tuple[bool, List[str]]:
        """Validate delegated vote."""
        return await self._validate_delegated_vote(user_id, proposal_id, vote_type)
    
    async def delegate_vote(
        self, 
        delegator_id: str, 
        delegate_id: str,
        proposal_id: Optional[str] = None,
        power_percentage: float = 100.0,
        expires_at: Optional[datetime] = None
    ) -> Dict[str, Any]:
        """Delegate voting power to another user."""
        try:
            delegation_id = str(uuid4())
            
            delegation = DelegationModel(
                id=delegation_id,
                delegator_id=delegator_id,
                delegate_id=delegate_id,
                proposal_id=proposal_id,
                power_percentage=power_percentage,
                expires_at=expires_at,
                delegation_type="specific" if proposal_id else "general"
            )
            
            async with self.db.session() as session:
                session.add(delegation)
                await session.commit()
            
            logger.info(f"Vote delegated: {delegator_id} -> {delegate_id}")
            
            return {
                'delegation_id': delegation_id,
                'delegator_id': delegator_id,
                'delegate_id': delegate_id,
                'power_percentage': power_percentage,
                'expires_at': expires_at.isoformat() if expires_at else None
            }
            
        except Exception as e:
            logger.error(f"Failed to delegate vote: {str(e)}")
            raise
    
    async def revoke_delegation(self, delegation_id: str, delegator_id: str) -> bool:
        """Revoke a vote delegation."""
        try:
            async with self.db.session() as session:
                delegation = await session.get(DelegationModel, delegation_id)
                if not delegation or delegation.delegator_id != delegator_id:
                    return False
                
                delegation.is_active = False
                await session.commit()
            
            logger.info(f"Delegation {delegation_id} revoked by {delegator_id}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to revoke delegation: {str(e)}")
            return False
    
    async def _get_own_voting_power(self, user_id: str) -> float:
        """Get user's own voting power."""
        return 50.0
    
    async def _get_delegated_power(self, user_id: str, proposal_id: str) -> float:
        """Get power delegated to user."""
        return 25.0
    
    async def _cast_delegated_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType,
        signature: str
    ) -> Dict[str, Any]:
        """Cast delegated vote implementation."""
        return {'vote_id': str(uuid4()), 'status': 'cast'}
    
    async def _validate_delegated_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType
    ) -> Tuple[bool, List[str]]:
        """Validate delegated vote implementation."""
        return True, []


class VotingSystem:
    """Main voting system coordinator."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        
        # Initialize voting systems
        self.token_voting = TokenBasedVoting(db_connection, cache_manager, security_manager)
        self.reputation_voting = ReputationBasedVoting(db_connection, cache_manager, security_manager)
        self.quadratic_voting = QuadraticVoting(db_connection, cache_manager, security_manager)
        self.delegated_voting = DelegatedVoting(db_connection, cache_manager, security_manager)
        
        self.systems = {
            'token_weighted': self.token_voting,
            'reputation_based': self.reputation_voting,
            'quadratic_voting': self.quadratic_voting,
            'delegated_voting': self.delegated_voting
        }
    
    async def initialize(self):
        """Initialize the voting system."""
        logger.info("Initializing Voting System")
        
        # Create database tables
        async with self.db.engine.begin() as conn:
            await conn.run_sync(Base.metadata.create_all)
        
        logger.info("Voting System initialized successfully")
    
    async def cast_vote(
        self,
        user_id: str,
        proposal_id: str,
        vote_type: VoteType,
        voting_mechanism: str,
        signature: str
    ) -> Dict[str, Any]:
        """Cast a vote using specified mechanism."""
        if voting_mechanism not in self.systems:
            raise ValueError(f"Unknown voting mechanism: {voting_mechanism}")
        
        system = self.systems[voting_mechanism]
        return await system.cast_vote(user_id, proposal_id, vote_type, signature)
    
    async def get_voting_power(
        self,
        user_id: str,
        proposal_id: str,
        voting_mechanism: str
    ) -> VotingPower:
        """Get voting power for user using specified mechanism."""
        if voting_mechanism not in self.systems:
            raise ValueError(f"Unknown voting mechanism: {voting_mechanism}")
        
        system = self.systems[voting_mechanism]
        return await system.calculate_voting_power(user_id, proposal_id)
    
    async def get_proposal_results(self, proposal_id: str) -> Dict[str, Any]:
        """Get comprehensive voting results for a proposal."""
        try:
            async with self.db.session() as session:
                # Get all votes for proposal
                votes = await session.query(VoteModel).filter(
                    VoteModel.proposal_id == proposal_id
                ).all()
                
                # Calculate results
                results = {
                    'proposal_id': proposal_id,
                    'total_votes': len(votes),
                    'votes_for': sum(v.voting_power for v in votes if v.vote_type == 'for'),
                    'votes_against': sum(v.voting_power for v in votes if v.vote_type == 'against'),
                    'votes_abstain': sum(v.voting_power for v in votes if v.vote_type == 'abstain'),
                    'total_voting_power': sum(v.voting_power for v in votes),
                    'unique_voters': len(set(v.voter_id for v in votes)),
                    'voting_mechanisms_used': list(set(
                        v.metadata.get('voting_system', 'unknown') for v in votes
                    )),
                    'last_vote_timestamp': max(v.timestamp for v in votes) if votes else None
                }
                
                # Calculate percentages
                total_power = results['total_voting_power']
                if total_power > 0:
                    results['for_percentage'] = (results['votes_for'] / total_power) * 100
                    results['against_percentage'] = (results['votes_against'] / total_power) * 100
                    results['abstain_percentage'] = (results['votes_abstain'] / total_power) * 100
                else:
                    results['for_percentage'] = 0
                    results['against_percentage'] = 0
                    results['abstain_percentage'] = 0
                
                return results
                
        except Exception as e:
            logger.error(f"Failed to get proposal results for {proposal_id}: {str(e)}")
            return {}
