class GovernanceAnalytics:
    """Main governance analytics coordinator."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        analytics_manager: AnalyticsManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.analytics = analytics_manager
        
        # Initialize analytics components
        self.voting_metrics = VotingMetricsAnalyzer(db_connection, cache_manager)
        self.participation_analytics = ParticipationAnalytics(db_connection, cache_manager)
        self.decision_impact = DecisionImpactAnalysis(
            db_connection, cache_manager, analytics_manager
        )
        self.community_engagement = CommunityEngagement(db_connection, cache_manager)
    
    async def initialize(self):
        """Initialize governance analytics system."""
        logger.info("Initializing Governance Analytics")
        
        # Create database tables
        async with self.db.engine.begin() as conn:
            await conn.run_sync(Base.metadata.create_all)
        
        logger.info("Governance Analytics initialized successfully")
    
    async def generate_governance_health_report(self) -> GovernanceHealthScore:
        """Generate comprehensive governance health report."""
        try:
            # Get component scores
            participation_data = await self.participation_analytics.calculate_community_health()
            engagement_data = await self.community_engagement.calculate_engagement_score()
            
            # Calculate component scores
            participation_score = participation_data.get('overall_health_score', 0.5)
            engagement_score = engagement_data.get('overall_engagement_score', 0.5)
            
            # Mock other component calculations
            decision_quality_score = 0.78
            execution_success_score = 0.82
            decentralization_score = 0.71
            
            # Calculate overall score
            overall_score = (
                participation_score * 0.25 +
                decision_quality_score * 0.20 +
                engagement_score * 0.20 +
                execution_success_score * 0.20 +
                decentralization_score * 0.15
            )
            
            # Generate recommendations and warnings
            recommendations = []
            warning_flags = []
            
            if participation_score < 0.6:
                warning_flags.append("Low participation rates detected")
                recommendations.append("Implement participation incentive programs")
            
            if decision_quality_score < 0.7:
                warning_flags.append("Decision quality concerns identified")
                recommendations.append("Enhance proposal review processes")
            
            if decentralization_score < 0.6:
                warning_flags.append("Centralization risks detected")
                recommendations.append("Diversify voting power distribution")
            
            return GovernanceHealthScore(
                overall_score=overall_score,
                participation_score=participation_score,
                decision_quality_score=decision_quality_score,
                community_satisfaction_score=engagement_score,
                execution_success_score=execution_success_score,
                decentralization_score=decentralization_score,
                calculated_at=datetime.utcnow(),
                recommendations=recommendations,
                warning_flags=warning_flags
            )
            
        except Exception as e:
            logger.error(f"Failed to generate governance health report: {str(e)}")
            return GovernanceHealthScore(
                overall_score=0.5,
                participation_score=0.5,
                decision_quality_score=0.5,
                community_satisfaction_score=0.5,
                execution_success_score=0.5,
                decentralization_score=0.5,
                calculated_at=datetime.utcnow(),
                recommendations=["System error - manual review required"],
                warning_flags=["Analytics system malfunction"]
            )
    
    async def get_analytics_dashboard_data(self) -> Dict[str, Any]:
        """Get comprehensive analytics data for dashboard."""
        try:
            # Get all analytics components
            health_report = await self.generate_governance_health_report()
            voting_metrics = await self.voting_metrics.analyze_voting_patterns()
            participation_trends = await self.participation_analytics.analyze_participation_trends(
                TimeFrame.MONTHLY, 6
            )
            engagement_score = await self.community_engagement.calculate_engagement_score()
            
            return {
                'governance_health': {
                    'overall_score': health_report.overall_score,
                    'grade': self._get_health_grade(health_report.overall_score),
                    'component_scores': {
                        'participation': health_report.participation_score,
                        'decision_quality': health_report.decision_quality_score,
                        'community_satisfaction': health_report.community_satisfaction_score,
                        'execution_success': health_report.execution_success_score,
                        'decentralization': health_report.decentralization_score
                    },
                    'recommendations': health_report.recommendations,
                    'warning_flags': health_report.warning_flags
                },
                'voting_metrics': {
                    'total_votes': voting_metrics.total_votes,
                    'unique_voters': voting_metrics.unique_voters,
                    'participation_rate': voting_metrics.participation_rate,
                    'consensus_strength': voting_metrics.consensus_strength,
                    'power_distribution': voting_metrics.power_distribution
                },
                'participation_trends': participation_trends,
                'community_engagement': engagement_score,
                'last_updated': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to get dashboard data: {str(e)}")
            return {}
    
    def _get_health_grade(self, score: float) -> str:
        """Convert health score to letter grade."""
        if score >= 0.9:
            return 'A+'
        elif score >= 0.8:
            return 'A'
        elif score >= 0.7:
            return 'B'
        elif score >= 0.6:
            return 'C'
        elif score >= 0.5:
            return 'D'
        else:
            return 'F'
