import asyncio
import hashlib
import json
from datetime import datetime, timedelta
from enum import Enum
from typing import Dict, List, Optional, Union, Any, Tuple
from dataclasses import dataclass, field
from uuid import uuid4, UUID

import aioredis
from pydantic import BaseModel, Field, validator
from sqlalchemy import Column, String, DateTime, Integer, Text, Boolean, Float, JSON
from sqlalchemy.ext.declarative import declarative_base
from cryptography.fernet import Fernet

from ....core.database import DatabaseConnection
from ....core.cache import CacheManager
from ....core.security import SecurityManager
from ....utils.logger import get_logger
from ....utils.validators import validate_proposal_content

logger = get_logger(__name__)
Base = declarative_base()


class ProposalType(Enum):
    """Types of governance proposals supported by the platform."""
    PROTOCOL_UPGRADE = "protocol_upgrade"
    TREASURY_ALLOCATION = "treasury_allocation"
    FEATURE_REQUEST = "feature_request"
    PARAMETER_CHANGE = "parameter_change"
    POLICY_UPDATE = "policy_update"
    COMMUNITY_GRANT = "community_grant"
    SECURITY_UPDATE = "security_update"
    INTEGRATION_PROPOSAL = "integration_proposal"
    TOKENOMICS_CHANGE = "tokenomics_change"
    EMERGENCY_ACTION = "emergency_action"


class ProposalStatus(Enum):
    """Status states of governance proposals."""
    DRAFT = "draft"
    SUBMITTED = "submitted"
    UNDER_REVIEW = "under_review"
    VOTING_ACTIVE = "voting_active"
    VOTING_PASSED = "voting_passed"
    VOTING_FAILED = "voting_failed"
    EXECUTED = "executed"
    CANCELLED = "cancelled"
    EXPIRED = "expired"
    QUEUED_FOR_EXECUTION = "queued_for_execution"


class VotingMechanism(Enum):
    """Available voting mechanisms for proposals."""
    TOKEN_WEIGHTED = "token_weighted"
    REPUTATION_BASED = "reputation_based"
    QUADRATIC_VOTING = "quadratic_voting"
    DELEGATED_VOTING = "delegated_voting"
    HYBRID_CONSENSUS = "hybrid_consensus"


@dataclass
class ProposalMetadata:
    """Metadata structure for governance proposals."""
    category: str
    tags: List[str]
    impact_level: str  # low, medium, high, critical
    required_quorum: float
    voting_period_days: int
    execution_delay_hours: int
    author_reputation_required: int
    associated_contracts: List[str] = field(default_factory=list)
    dependencies: List[str] = field(default_factory=list)
    risk_assessment: Dict[str, Any] = field(default_factory=dict)


class ProposalModel(Base):
    """SQLAlchemy model for governance proposals."""
    __tablename__ = "governance_proposals"
    
    id = Column(String, primary_key=True)
    title = Column(String(255), nullable=False)
    description = Column(Text, nullable=False)
    proposal_type = Column(String(50), nullable=False)
    status = Column(String(50), nullable=False, default="draft")
    author_id = Column(String, nullable=False)
    created_at = Column(DateTime, default=datetime.utcnow)
    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    voting_start = Column(DateTime)
    voting_end = Column(DateTime)
    execution_time = Column(DateTime)
    metadata = Column(JSON)
    content_hash = Column(String(64))
    signature = Column(Text)
    votes_for = Column(Integer, default=0)
    votes_against = Column(Integer, default=0)
    votes_abstain = Column(Integer, default=0)
    total_voting_power = Column(Float, default=0.0)
    quorum_reached = Column(Boolean, default=False)
    execution_data = Column(JSON)
    audit_trail = Column(JSON, default=list)


class ProposalCreateRequest(BaseModel):
    """Request model for creating new proposals."""
    title: str = Field(..., min_length=10, max_length=255)
    description: str = Field(..., min_length=50, max_length=10000)
    proposal_type: ProposalType
    voting_mechanism: VotingMechanism
    metadata: Dict[str, Any]
    execution_data: Optional[Dict[str, Any]] = None
    
    @validator('title')
    def validate_title(cls, v):
        if not v.strip():
            raise ValueError("Title cannot be empty")
        return v.strip()
    
    @validator('description')
    def validate_description(cls, v):
        if not validate_proposal_content(v):
            raise ValueError("Description contains inappropriate content")
        return v.strip()


class ProposalValidator:
    """Validates proposals before submission and during lifecycle."""
    
    def __init__(self, security_manager: SecurityManager):
        self.security = security_manager
        
    async def validate_proposal_creation(
        self, 
        proposal_data: ProposalCreateRequest,
        author_id: str
    ) -> Tuple[bool, List[str]]:
        """Validate proposal creation request."""
        errors = []
        
        # Check author permissions
        author_reputation = await self._get_author_reputation(author_id)
        required_rep = proposal_data.metadata.get("author_reputation_required", 100)
        
        if author_reputation < required_rep:
            errors.append(f"Author reputation {author_reputation} below required {required_rep}")
        
        # Validate proposal content
        if not self._validate_content_quality(proposal_data.description):
            errors.append("Proposal description does not meet quality standards")
        
        # Check for duplicate proposals
        if await self._check_duplicate_proposal(proposal_data.title, author_id):
            errors.append("Similar proposal already exists")
        
        # Validate execution data if provided
        if proposal_data.execution_data:
            if not await self._validate_execution_data(
                proposal_data.proposal_type, 
                proposal_data.execution_data
            ):
                errors.append("Invalid execution data for proposal type")
        
        return len(errors) == 0, errors
    
    async def validate_proposal_submission(self, proposal_id: str) -> Tuple[bool, List[str]]:
        """Validate proposal before moving to submission state."""
        errors = []
        
        # Additional validation for submission
        proposal = await self._get_proposal(proposal_id)
        if not proposal:
            errors.append("Proposal not found")
            return False, errors
        
        # Check if proposal meets submission criteria
        if not self._has_sufficient_content(proposal):
            errors.append("Proposal lacks sufficient detail for submission")
        
        # Security validation
        if not await self.security.validate_proposal_security(proposal):
            errors.append("Proposal failed security validation")
        
        return len(errors) == 0, errors
    
    def _validate_content_quality(self, content: str) -> bool:
        """Validate proposal content quality."""
        word_count = len(content.split())
        if word_count < 50:
            return False
        
        # Check for structured content (basic requirements)
        required_sections = ['problem', 'solution', 'implementation']
        content_lower = content.lower()
        
        section_count = sum(1 for section in required_sections if section in content_lower)
        return section_count >= 2
    
    async def _get_author_reputation(self, author_id: str) -> int:
        """Get author's reputation score."""
        # This would integrate with the reputation system
        # For now, return mock data
        return 150
    
    async def _check_duplicate_proposal(self, title: str, author_id: str) -> bool:
        """Check for duplicate proposals."""
        # Implementation would check for similar titles/content
        return False
    
    async def _validate_execution_data(
        self, 
        proposal_type: ProposalType, 
        execution_data: Dict[str, Any]
    ) -> bool:
        """Validate execution data based on proposal type."""
        type_validators = {
            ProposalType.PROTOCOL_UPGRADE: self._validate_protocol_upgrade_data,
            ProposalType.TREASURY_ALLOCATION: self._validate_treasury_allocation_data,
            ProposalType.PARAMETER_CHANGE: self._validate_parameter_change_data,
        }
        
        validator_func = type_validators.get(proposal_type)
        if validator_func:
            return await validator_func(execution_data)
        
        return True
    
    async def _validate_protocol_upgrade_data(self, data: Dict[str, Any]) -> bool:
        """Validate protocol upgrade execution data."""
        required_fields = ['contract_address', 'upgrade_method', 'parameters']
        return all(field in data for field in required_fields)
    
    async def _validate_treasury_allocation_data(self, data: Dict[str, Any]) -> bool:
        """Validate treasury allocation execution data."""
        required_fields = ['recipient', 'amount', 'currency', 'milestone_conditions']
        return all(field in data for field in required_fields)
    
    async def _validate_parameter_change_data(self, data: Dict[str, Any]) -> bool:
        """Validate parameter change execution data."""
        required_fields = ['parameter_name', 'current_value', 'new_value', 'justification']
        return all(field in data for field in required_fields)
    
    async def _get_proposal(self, proposal_id: str) -> Optional[Dict]:
        """Get proposal by ID."""
        # Implementation would fetch from database
        return None
    
    def _has_sufficient_content(self, proposal: Dict) -> bool:
        """Check if proposal has sufficient content."""
        return len(proposal.get('description', '')) > 200


class ProposalCreator:
    """Handles creation and management of governance proposals."""
    
    def __init__(
        self, 
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        self.validator = ProposalValidator(security_manager)
        
    async def create_proposal(
        self, 
        proposal_data: ProposalCreateRequest,
        author_id: str,
        author_signature: str
    ) -> Dict[str, Any]:
        """Create a new governance proposal."""
        try:
            # Validate proposal
            is_valid, errors = await self.validator.validate_proposal_creation(
                proposal_data, author_id
            )
            
            if not is_valid:
                raise ValueError(f"Proposal validation failed: {', '.join(errors)}")
            
            # Generate proposal ID and hash
            proposal_id = str(uuid4())
            content_hash = self._generate_content_hash(proposal_data)
            
            # Verify author signature
            if not await self.security.verify_proposal_signature(
                content_hash, author_signature, author_id
            ):
                raise ValueError("Invalid author signature")
            
            # Create proposal metadata
            metadata = ProposalMetadata(
                category=proposal_data.metadata.get('category', 'general'),
                tags=proposal_data.metadata.get('tags', []),
                impact_level=proposal_data.metadata.get('impact_level', 'medium'),
                required_quorum=proposal_data.metadata.get('required_quorum', 0.1),
                voting_period_days=proposal_data.metadata.get('voting_period_days', 7),
                execution_delay_hours=proposal_data.metadata.get('execution_delay_hours', 24),
                author_reputation_required=proposal_data.metadata.get('author_reputation_required', 100)
            )
            
            # Create proposal record
            proposal = ProposalModel(
                id=proposal_id,
                title=proposal_data.title,
                description=proposal_data.description,
                proposal_type=proposal_data.proposal_type.value,
                author_id=author_id,
                metadata=metadata.__dict__,
                content_hash=content_hash,
                signature=author_signature,
                execution_data=proposal_data.execution_data,
                audit_trail=[{
                    'action': 'created',
                    'timestamp': datetime.utcnow().isoformat(),
                    'actor': author_id,
                    'details': 'Proposal created'
                }]
            )
            
            # Save to database
            async with self.db.session() as session:
                session.add(proposal)
                await session.commit()
            
            # Cache the proposal
            await self.cache.set(
                f"proposal:{proposal_id}",
                proposal.__dict__,
                expire=3600
            )
            
            # Emit proposal created event
            await self._emit_proposal_event('proposal_created', proposal_id, {
                'author_id': author_id,
                'title': proposal_data.title,
                'type': proposal_data.proposal_type.value
            })
            
            logger.info(f"Proposal {proposal_id} created by {author_id}")
            
            return {
                'proposal_id': proposal_id,
                'status': ProposalStatus.DRAFT.value,
                'content_hash': content_hash,
                'created_at': proposal.created_at.isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to create proposal: {str(e)}")
            raise
    
    async def submit_proposal(self, proposal_id: str, submitter_id: str) -> Dict[str, Any]:
        """Submit proposal for community review."""
        try:
            # Validate submission
            is_valid, errors = await self.validator.validate_proposal_submission(proposal_id)
            if not is_valid:
                raise ValueError(f"Submission validation failed: {', '.join(errors)}")
            
            # Update proposal status
            async with self.db.session() as session:
                proposal = await session.get(ProposalModel, proposal_id)
                if not proposal:
                    raise ValueError("Proposal not found")
                
                if proposal.status != ProposalStatus.DRAFT.value:
                    raise ValueError(f"Cannot submit proposal in {proposal.status} status")
                
                # Check if submitter is author or authorized
                if proposal.author_id != submitter_id:
                    if not await self.security.has_permission(submitter_id, 'submit_proposals'):
                        raise ValueError("Unauthorized to submit this proposal")
                
                # Update status and audit trail
                proposal.status = ProposalStatus.SUBMITTED.value
                proposal.updated_at = datetime.utcnow()
                
                audit_entry = {
                    'action': 'submitted',
                    'timestamp': datetime.utcnow().isoformat(),
                    'actor': submitter_id,
                    'details': 'Proposal submitted for review'
                }
                proposal.audit_trail.append(audit_entry)
                
                await session.commit()
            
            # Clear cache
            await self.cache.delete(f"proposal:{proposal_id}")
            
            # Emit event
            await self._emit_proposal_event('proposal_submitted', proposal_id, {
                'submitter_id': submitter_id
            })
            
            logger.info(f"Proposal {proposal_id} submitted by {submitter_id}")
            
            return {
                'proposal_id': proposal_id,
                'status': ProposalStatus.SUBMITTED.value,
                'submitted_at': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to submit proposal {proposal_id}: {str(e)}")
            raise
    
    async def get_proposal(self, proposal_id: str) -> Optional[Dict[str, Any]]:
        """Retrieve proposal by ID."""
        try:
            # Try cache first
            cached = await self.cache.get(f"proposal:{proposal_id}")
            if cached:
                return cached
            
            # Fetch from database
            async with self.db.session() as session:
                proposal = await session.get(ProposalModel, proposal_id)
                if not proposal:
                    return None
                
                proposal_data = {
                    'id': proposal.id,
                    'title': proposal.title,
                    'description': proposal.description,
                    'proposal_type': proposal.proposal_type,
                    'status': proposal.status,
                    'author_id': proposal.author_id,
                    'created_at': proposal.created_at.isoformat(),
                    'updated_at': proposal.updated_at.isoformat(),
                    'voting_start': proposal.voting_start.isoformat() if proposal.voting_start else None,
                    'voting_end': proposal.voting_end.isoformat() if proposal.voting_end else None,
                    'execution_time': proposal.execution_time.isoformat() if proposal.execution_time else None,
                    'metadata': proposal.metadata,
                    'content_hash': proposal.content_hash,
                    'votes_for': proposal.votes_for,
                    'votes_against': proposal.votes_against,
                    'votes_abstain': proposal.votes_abstain,
                    'total_voting_power': proposal.total_voting_power,
                    'quorum_reached': proposal.quorum_reached,
                    'execution_data': proposal.execution_data,
                    'audit_trail': proposal.audit_trail
                }
                
                # Cache the result
                await self.cache.set(f"proposal:{proposal_id}", proposal_data, expire=1800)
                
                return proposal_data
                
        except Exception as e:
            logger.error(f"Failed to get proposal {proposal_id}: {str(e)}")
            return None
    
    async def list_proposals(
        self,
        status: Optional[ProposalStatus] = None,
        proposal_type: Optional[ProposalType] = None,
        author_id: Optional[str] = None,
        limit: int = 50,
        offset: int = 0
    ) -> List[Dict[str, Any]]:
        """List proposals with filtering options."""
        try:
            # Build cache key
            cache_key = f"proposals_list:{status}:{proposal_type}:{author_id}:{limit}:{offset}"
            cached = await self.cache.get(cache_key)
            if cached:
                return cached
            
            # Build query
            async with self.db.session() as session:
                query = session.query(ProposalModel)
                
                if status:
                    query = query.filter(ProposalModel.status == status.value)
                if proposal_type:
                    query = query.filter(ProposalModel.proposal_type == proposal_type.value)
                if author_id:
                    query = query.filter(ProposalModel.author_id == author_id)
                
                query = query.order_by(ProposalModel.created_at.desc())
                query = query.offset(offset).limit(limit)
                
                proposals = await query.all()
                
                result = []
                for proposal in proposals:
                    result.append({
                        'id': proposal.id,
                        'title': proposal.title,
                        'proposal_type': proposal.proposal_type,
                        'status': proposal.status,
                        'author_id': proposal.author_id,
                        'created_at': proposal.created_at.isoformat(),
                        'votes_for': proposal.votes_for,
                        'votes_against': proposal.votes_against,
                        'votes_abstain': proposal.votes_abstain,
                        'quorum_reached': proposal.quorum_reached
                    })
                
                # Cache results
                await self.cache.set(cache_key, result, expire=300)
                
                return result
                
        except Exception as e:
            logger.error(f"Failed to list proposals: {str(e)}")
            return []
    
    def _generate_content_hash(self, proposal_data: ProposalCreateRequest) -> str:
        """Generate SHA-256 hash of proposal content."""
        content = f"{proposal_data.title}{proposal_data.description}{proposal_data.proposal_type.value}"
        return hashlib.sha256(content.encode()).hexdigest()
    
    async def _emit_proposal_event(
        self, 
        event_type: str, 
        proposal_id: str, 
        data: Dict[str, Any]
    ):
        """Emit proposal-related event."""
        event_data = {
            'event_type': event_type,
            'proposal_id': proposal_id,
            'timestamp': datetime.utcnow().isoformat(),
            'data': data
        }
        
        # Publish to event bus
        await self.cache.publish('governance_events', json.dumps(event_data))


class ProposalManager:
    """Main manager class for proposal operations."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager
    ):
        self.creator = ProposalCreator(db_connection, cache_manager, security_manager)
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        
    async def initialize(self):
        """Initialize the proposal manager."""
        logger.info("Initializing Proposal Manager")
        
        # Create database tables if needed
        async with self.db.engine.begin() as conn:
            await conn.run_sync(Base.metadata.create_all)
        
        logger.info("Proposal Manager initialized successfully")
    
    # Delegate methods to creator
    async def create_proposal(self, *args, **kwargs):
        return await self.creator.create_proposal(*args, **kwargs)
    
    async def submit_proposal(self, *args, **kwargs):
        return await self.creator.submit_proposal(*args, **kwargs)
    
    async def get_proposal(self, *args, **kwargs):
        return await self.creator.get_proposal(*args, **kwargs)
    
    async def list_proposals(self, *args, **kwargs):
        return await self.creator.list_proposals(*args, **kwargs)
