class ReputationCalculator:
    """Calculates reputation scores based on various factors."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        
        # Configuration
        self.base_reputation = 100.0
        self.max_reputation = 10000.0
        self.decay_rate = 0.95  # Daily decay factor
        self.expertise_multipliers = {
            ExpertiseArea.TECHNICAL_DEVELOPMENT: 1.5,
            ExpertiseArea.MUSIC_PRODUCTION: 1.3,
            ExpertiseArea.BUSINESS_STRATEGY: 1.4,
            ExpertiseArea.COMMUNITY_MANAGEMENT: 1.2,
            ExpertiseArea.BLOCKCHAIN_TECHNOLOGY: 1.6
        }
    
    async def calculate_reputation(self, user_id: str) -> ReputationScore:
        """Calculate comprehensive reputation score for user."""
        try:
            # Get user data
            async with self.db.session() as session:
                user_rep = await session.get(UserReputationModel, user_id)
                if not user_rep:
                    user_rep = await self._initialize_user_reputation(user_id)
                
                # Get contributions
                contributions = await session.query(ContributionModel).filter(
                    ContributionModel.user_id == user_id
                ).all()
                
                # Get trust metrics
                trust_metrics = await session.get(TrustMetricModel, user_id)
                if not trust_metrics:
                    trust_metrics = await self._initialize_trust_metrics(user_id)
            
            # Calculate component scores
            base_score = await self._calculate_base_score(user_id)
            contribution_score = await self._calculate_contribution_score(contributions)
            expertise_score = await self._calculate_expertise_score(user_id, contributions)
            governance_score = await self._calculate_governance_score(user_id)
            trust_score = await self._calculate_trust_score(trust_metrics)
            
            # Apply time decay
            decay_factor = await self._calculate_decay_factor(user_id)
            
            # Calculate total score
            weighted_score = (
                base_score * 0.1 +
                contribution_score * 0.35 +
                expertise_score * 0.25 +
                governance_score * 0.20 +
                trust_score * 0.10
            )
            
            total_score = min(weighted_score * decay_factor, self.max_reputation)
            
            # Create reputation breakdown
            breakdown = {
                'base_score': base_score,
                'contribution_score': contribution_score,
                'expertise_score': expertise_score,
                'governance_score': governance_score,
                'trust_score': trust_score,
                'decay_factor': decay_factor,
                'weighted_score': weighted_score,
                'weights': {
                    'base': 0.1,
                    'contribution': 0.35,
                    'expertise': 0.25,
                    'governance': 0.20,
                    'trust': 0.10
                }
            }
            
            # Update database
            await self._update_user_reputation(user_id, total_score, breakdown)
            
            return ReputationScore(
                user_id=user_id,
                total_score=total_score,
                base_score=base_score,
                contribution_score=contribution_score,
                expertise_score=expertise_score,
                governance_score=governance_score,
                trust_score=trust_score,
                decay_factor=decay_factor,
                calculated_at=datetime.utcnow(),
                breakdown=breakdown
            )
            
        except Exception as e:
            logger.error(f"Failed to calculate reputation for {user_id}: {str(e)}")
            return ReputationScore(
                user_id=user_id,
                total_score=self.base_reputation,
                base_score=self.base_reputation,
                contribution_score=0.0,
                expertise_score=0.0,
                governance_score=0.0,
                trust_score=self.base_reputation,
                decay_factor=1.0,
                calculated_at=datetime.utcnow(),
                breakdown={}
            )
    
    async def _calculate_base_score(self, user_id: str) -> float:
        """Calculate base reputation score."""
        # Base score considers account age, verification status
        account_info = await self._get_account_info(user_id)
        
        # Account age bonus (up to 365 days)
        age_days = account_info.get('age_days', 0)
        age_bonus = min(age_days / 365.0 * 50, 50)  # Max 50 points for 1+ year
        
        # Verification bonus
        verification_bonus = 0
        if account_info.get('email_verified', False):
            verification_bonus += 10
        if account_info.get('identity_verified', False):
            verification_bonus += 20
        if account_info.get('kyc_completed', False):
            verification_bonus += 30
        
        return self.base_reputation + age_bonus + verification_bonus
    
    async def _calculate_contribution_score(
        self, 
        contributions: List[ContributionModel]
    ) -> float:
        """Calculate contribution-based reputation score."""
        if not contributions:
            return 0.0
        
        total_score = 0.0
        contribution_weights = {
            ContributionType.CONTENT_CREATION: 1.0,
            ContributionType.TECHNICAL_CONTRIBUTION: 1.5,
            ContributionType.GOVERNANCE_PARTICIPATION: 1.3,
            ContributionType.COMMUNITY_MODERATION: 1.2,
            ContributionType.QUALITY_CURATION: 1.1
        }
        
        for contribution in contributions:
            weight = contribution_weights.get(
                ContributionType(contribution.contribution_type), 1.0
            )
            
            # Calculate contribution value with quality and impact
            contribution_value = (
                contribution.value * 
                contribution.quality_score * 
                contribution.impact_score * 
                weight
            )
            
            # Verified contributions get bonus
            if contribution.verified:
                contribution_value *= 1.2
            
            # Time decay for older contributions
            days_old = (datetime.utcnow() - contribution.timestamp).days
            time_factor = math.exp(-days_old / 180.0)  # 6-month half-life
            
            total_score += contribution_value * time_factor
        
        return min(total_score, 2000.0)  # Cap contribution score
    
    async def _calculate_expertise_score(
        self, 
        user_id: str, 
        contributions: List[ContributionModel]
    ) -> float:
        """Calculate expertise-based reputation score."""
        # Analyze contributions by expertise area
        expertise_scores = {}
        
        for contribution in contributions:
            if contribution.expertise_area:
                area = contribution.expertise_area
                if area not in expertise_scores:
                    expertise_scores[area] = 0.0
                
                # Higher weight for verified expertise
                weight = 1.5 if contribution.verified else 1.0
                expertise_scores[area] += contribution.value * weight
        
        # Calculate weighted expertise score
        total_expertise = 0.0
        for area, score in expertise_scores.items():
            try:
                multiplier = self.expertise_multipliers.get(
                    ExpertiseArea(area), 1.0
                )
                total_expertise += score * multiplier
            except ValueError:
                # Handle unknown expertise areas
                total_expertise += score
        
        # Apply expertise diversity bonus
        diversity_bonus = min(len(expertise_scores) * 10, 50)
        
        return min(total_expertise + diversity_bonus, 1500.0)
    
    async def _calculate_governance_score(self, user_id: str) -> float:
        """Calculate governance participation score."""
        try:
            # Get governance participation data
            governance_data = await self._get_governance_participation(user_id)
            
            proposals_created = governance_data.get('proposals_created', 0)
            votes_cast = governance_data.get('votes_cast', 0)
            participation_rate = governance_data.get('participation_rate', 0.0)
            
            # Calculate score components
            proposal_score = min(proposals_created * 50, 500)  # Max 500 from proposals
            voting_score = min(votes_cast * 5, 300)  # Max 300 from voting
            participation_score = participation_rate * 200  # Max 200 from participation
            
            # Quality bonus for well-received proposals
            quality_bonus = governance_data.get('proposal_success_rate', 0.0) * 100
            
            total_score = proposal_score + voting_score + participation_score + quality_bonus
            
            return min(total_score, 1000.0)
            
        except Exception as e:
            logger.error(f"Failed to calculate governance score: {str(e)}")
            return 0.0
    
    async def _calculate_trust_score(self, trust_metrics: TrustMetricModel) -> float:
        """Calculate trust-based reputation score."""
        base_trust = 100.0
        
        # Verification bonuses
        verification_score = 0
        if trust_metrics.identity_verified:
            verification_score += 20
        if trust_metrics.email_verified:
            verification_score += 5
        if trust_metrics.social_media_verified:
            verification_score += 10
        if trust_metrics.kyc_completed:
            verification_score += 25
        
        # Behavioral trust
        behavioral_score = (
            trust_metrics.consistency_score * 30 +
            trust_metrics.reliability_score * 40 +
            trust_metrics.community_standing * 30
        )
        
        # Network trust
        network_score = min(trust_metrics.endorsements_received * 2, 50)
        
        # Penalties
        penalty_score = (
            trust_metrics.warnings_received * -10 +
            trust_metrics.temporary_restrictions * -25
        )
        
        total_trust = base_trust + verification_score + behavioral_score + network_score + penalty_score
        
        return max(total_trust, 0.0)  # Ensure non-negative
    
    async def _calculate_decay_factor(self, user_id: str) -> float:
        """Calculate time-based decay factor."""
        # Get last activity
        last_activity = await self._get_last_activity(user_id)
        if not last_activity:
            return 1.0
        
        days_inactive = (datetime.utcnow() - last_activity).days
        
        # Apply decay for inactivity (starts after 30 days)
        if days_inactive <= 30:
            return 1.0
        
        effective_days = days_inactive - 30
        decay_factor = self.decay_rate ** (effective_days / 30.0)  # Monthly decay
        
        return max(decay_factor, 0.1)  # Minimum 10% retention
    
    async def _initialize_user_reputation(self, user_id: str) -> UserReputationModel:
        """Initialize reputation record for new user."""
        user_rep = UserReputationModel(
            user_id=user_id,
            total_score=self.base_reputation,
            base_score=self.base_reputation
        )
        
        async with self.db.session() as session:
            session.add(user_rep)
            await session.commit()
        
        return user_rep
    
    async def _initialize_trust_metrics(self, user_id: str) -> TrustMetricModel:
        """Initialize trust metrics for new user."""
        trust_metrics = TrustMetricModel(user_id=user_id)
        
        async with self.db.session() as session:
            session.add(trust_metrics)
            await session.commit()
        
        return trust_metrics
    
    async def _update_user_reputation(
        self, 
        user_id: str, 
        total_score: float, 
        breakdown: Dict[str, Any]
    ):
        """Update user reputation in database."""
        async with self.db.session() as session:
            user_rep = await session.get(UserReputationModel, user_id)
            if not user_rep:
                return
            
            # Update scores
            user_rep.total_score = total_score
            user_rep.base_score = breakdown['base_score']
            user_rep.contribution_score = breakdown['contribution_score']
            user_rep.expertise_score = breakdown['expertise_score']
            user_rep.governance_score = breakdown['governance_score']
            user_rep.trust_score = breakdown['trust_score']
            
            # Update peak score if applicable
            if total_score > user_rep.peak_score:
                user_rep.peak_score = total_score
                user_rep.peak_score_date = datetime.utcnow()
            
            # Add to history
            if not user_rep.score_history:
                user_rep.score_history = []
            
            user_rep.score_history.append({
                'score': total_score,
                'timestamp': datetime.utcnow().isoformat(),
                'breakdown': breakdown
            })
            
            # Keep only last 30 entries
            user_rep.score_history = user_rep.score_history[-30:]
            
            user_rep.calculation_metadata = {
                'last_calculation': datetime.utcnow().isoformat(),
                'calculation_version': '1.0'
            }
            
            await session.commit()
    
    async def _get_account_info(self, user_id: str) -> Dict[str, Any]:
        """Get account information for user."""
        # This would integrate with user management system
        return {
            'age_days': 180,
            'email_verified': True,
            'identity_verified': False,
            'kyc_completed': False
        }
    
    async def _get_governance_participation(self, user_id: str) -> Dict[str, Any]:
        """Get governance participation data."""
        # This would integrate with governance system
        return {
            'proposals_created': 3,
            'votes_cast': 25,
            'participation_rate': 0.75,
            'proposal_success_rate': 0.67
        }
    
    async def _get_last_activity(self, user_id: str) -> Optional[datetime]:
        """Get user's last activity timestamp."""
        # This would integrate with activity tracking
        return datetime.utcnow() - timedelta(days=5)


class ContributionTracker:
    """Tracks user contributions for reputation calculation."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager
    ):
        self.db = db_connection
        self.cache = cache_manager
    
    async def record_contribution(
        self,
        user_id: str,
        contribution_type: ContributionType,
        value: float,
        quality_score: float = 1.0,
        metadata: Optional[Dict[str, Any]] = None
    ) -> str:
        """Record a user contribution."""
        try:
            contribution_id = str(uuid4())
            
            contribution = ContributionModel(
                id=contribution_id,
                user_id=user_id,
                contribution_type=contribution_type.value,
                value=value,
                quality_score=quality_score,
                metadata=metadata or {}
            )
            
            async with self.db.session() as session:
                session.add(contribution)
                await session.commit()
            
            # Clear reputation cache to trigger recalculation
            await self.cache.delete(f"reputation:{user_id}")
            
            logger.info(f"Contribution recorded: {user_id} - {contribution_type.value}")
            
            return contribution_id
            
        except Exception as e:
            logger.error(f"Failed to record contribution: {str(e)}")
            raise
    
    async def verify_contribution(
        self,
        contribution_id: str,
        verifier_id: str
    ) -> bool:
        """Verify a user contribution."""
        try:
            async with self.db.session() as session:
                contribution = await session.get(ContributionModel, contribution_id)
                if not contribution:
                    return False
                
                contribution.verified = True
                contribution.verified_by = verifier_id
                contribution.verification_date = datetime.utcnow()
                
                await session.commit()
            
            # Clear reputation cache
            await self.cache.delete(f"reputation:{contribution.user_id}")
            
            return True
            
        except Exception as e:
            logger.error(f"Failed to verify contribution: {str(e)}")
            return False
    
    async def get_user_contributions(
        self,
        user_id: str,
        limit: int = 100
    ) -> List[Dict[str, Any]]:
        """Get user's contribution history."""
        try:
            async with self.db.session() as session:
                contributions = await session.query(ContributionModel).filter(
                    ContributionModel.user_id == user_id
                ).order_by(ContributionModel.timestamp.desc()).limit(limit).all()
                
                return [
                    {
                        'id': c.id,
                        'contribution_type': c.contribution_type,
                        'value': c.value,
                        'quality_score': c.quality_score,
                        'impact_score': c.impact_score,
                        'verified': c.verified,
                        'verified_by': c.verified_by,
                        'timestamp': c.timestamp.isoformat(),
                        'metadata': c.metadata
                    }
                    for c in contributions
                ]
                
        except Exception as e:
            logger.error(f"Failed to get user contributions: {str(e)}")
            return []


class ExpertiseScoring:
    """Manages expertise scoring and validation."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager
    ):
        self.db = db_connection
        self.cache = cache_manager
    
    async def assess_expertise(
        self,
        user_id: str,
        expertise_area: ExpertiseArea,
        evidence: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Assess user's expertise in specific area."""
        try:
            # Analyze evidence
            expertise_score = await self._calculate_expertise_score(
                user_id, expertise_area, evidence
            )
            
            # Determine confidence level
            confidence = await self._calculate_confidence(evidence)
            
            # Check for verification requirements
            verification_needed = expertise_score > 50 and confidence < 0.8
            
            assessment = {
                'user_id': user_id,
                'expertise_area': expertise_area.value,
                'score': expertise_score,
                'confidence': confidence,
                'verification_needed': verification_needed,
                'evidence_quality': await self._assess_evidence_quality(evidence),
                'assessed_at': datetime.utcnow().isoformat()
            }
            
            # Cache assessment
            await self.cache.set(
                f"expertise_assessment:{user_id}:{expertise_area.value}",
                assessment,
                expire=86400
            )
            
            return assessment
            
        except Exception as e:
            logger.error(f"Failed to assess expertise: {str(e)}")
            return {}
    
    async def _calculate_expertise_score(
        self,
        user_id: str,
        expertise_area: ExpertiseArea,
        evidence: Dict[str, Any]
    ) -> float:
        """Calculate expertise score based on evidence."""
        # This would analyze various forms of evidence
        base_score = 0.0
        
        # Portfolio/work samples
        if 'portfolio_items' in evidence:
            base_score += len(evidence['portfolio_items']) * 10
        
        # Community recognition
        if 'endorsements' in evidence:
            base_score += evidence['endorsements'] * 5
        
        # Platform activity
        if 'activity_score' in evidence:
            base_score += evidence['activity_score']
        
        return min(base_score, 100.0)
    
    async def _calculate_confidence(self, evidence: Dict[str, Any]) -> float:
        """Calculate confidence in expertise assessment."""
        confidence_factors = []
        
        if evidence.get('verified_credentials'):
            confidence_factors.append(0.9)
        if evidence.get('peer_reviews', 0) > 5:
            confidence_factors.append(0.8)
        if evidence.get('portfolio_quality', 0) > 0.7:
            confidence_factors.append(0.75)
        
        return np.mean(confidence_factors) if confidence_factors else 0.5
    
    async def _assess_evidence_quality(self, evidence: Dict[str, Any]) -> Dict[str, Any]:
        """Assess quality of provided evidence."""
        return {
            'completeness': len(evidence) / 10.0,  # Assume 10 ideal evidence types
            'verification_rate': evidence.get('verified_items', 0) / max(len(evidence), 1),
            'recency': evidence.get('recent_activity_score', 0.5)
        }


class TrustMetrics:
    """Manages trust metrics and social proof."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager
    ):
        self.db = db_connection
        self.cache = cache_manager
    
    async def update_trust_metrics(
        self,
        user_id: str,
        metric_updates: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Update trust metrics for user."""
        try:
            async with self.db.session() as session:
                trust_metrics = await session.get(TrustMetricModel, user_id)
                if not trust_metrics:
                    trust_metrics = TrustMetricModel(user_id=user_id)
                    session.add(trust_metrics)
                
                # Update metrics
                for metric, value in metric_updates.items():
                    if hasattr(trust_metrics, metric):
                        setattr(trust_metrics, metric, value)
                
                await session.commit()
            
            # Clear reputation cache
            await self.cache.delete(f"reputation:{user_id}")
            
            return {
                'user_id': user_id,
                'updated_metrics': list(metric_updates.keys()),
                'updated_at': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to update trust metrics: {str(e)}")
            return {}
    
