    """Calculates influence rankings based on reputation and network effects."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager
    ):
        self.db = db_connection
        self.cache = cache_manager
    
    async def calculate_influence_score(self, user_id: str) -> Dict[str, Any]:
        """Calculate overall influence score."""
        try:
            # Get reputation score
            reputation_calculator = ReputationCalculator(self.db, self.cache)
            reputation = await reputation_calculator.calculate_reputation(user_id)
            
            # Get network metrics
            network_score = await self._calculate_network_score(user_id)
            
            # Get activity influence
            activity_score = await self._calculate_activity_influence(user_id)
            
            # Calculate weighted influence
            influence_score = (
                reputation.total_score * 0.4 +
                network_score * 0.35 +
                activity_score * 0.25
            )
            
            return {
                'user_id': user_id,
                'influence_score': influence_score,
                'reputation_component': reputation.total_score,
                'network_component': network_score,
                'activity_component': activity_score,
                'calculated_at': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to calculate influence score: {str(e)}")
