class VotingMechanism:
    """Advanced voting mechanism with delegation support."""
    
    def __init__(self, governance_token: GovernanceToken):
        self.governance_token = governance_token
        self.logger = logging.getLogger(__name__)
        
        # Delegation tracking
        self.delegations: Dict[str, str] = {}  # voter -> delegate
        self.delegate_power: Dict[str, Decimal] = {}  # delegate -> total power
    
    async def delegate_votes(self, delegator: str, delegate: str) -> bool:
        """Delegate voting power to another address."""
        try:
            # Validate addresses
            if not Web3.isAddress(delegator) or not Web3.isAddress(delegate):
                raise ValueError("Invalid address format")
            
            # Cannot delegate to self
            if delegator.lower() == delegate.lower():
                raise ValueError("Cannot delegate to self")
            
            # Get delegator's voting power
            voting_power = await self._get_token_balance(delegator)
            if voting_power == 0:
                raise ValueError("No voting power to delegate")
            
            # Update delegation
            old_delegate = self.delegations.get(delegator)
            if old_delegate:
                # Remove power from old delegate
                self.delegate_power[old_delegate] = (
                    self.delegate_power.get(old_delegate, Decimal("0")) - voting_power
                )
            
            # Add power to new delegate
            self.delegations[delegator] = delegate
            self.delegate_power[delegate] = (
                self.delegate_power.get(delegate, Decimal("0")) + voting_power
            )
            
            self.logger.info(f"Votes delegated: {delegator} -> {delegate} ({voting_power})")
            return True
            
        except Exception as e:
            self.logger.error(f"Vote delegation failed: {e}")
            return False
    
    async def undelegate_votes(self, delegator: str) -> bool:
        """Remove vote delegation."""
        try:
            if delegator not in self.delegations:
                return False
            
            delegate = self.delegations[delegator]
            voting_power = await self._get_token_balance(delegator)
            
            # Remove power from delegate
            self.delegate_power[delegate] = (
                self.delegate_power.get(delegate, Decimal("0")) - voting_power
            )
            
            # Remove delegation
            del self.delegations[delegator]
            
            self.logger.info(f"Votes undelegated: {delegator} from {delegate}")
            return True
            
        except Exception as e:
            self.logger.error(f"Vote undelegation failed: {e}")
            return False
    
    async def get_voting_power(self, address: str, block_number: Optional[int] = None) -> Decimal:
        """Get total voting power for address (including delegated power)."""
        # Direct token balance
        direct_power = await self._get_token_balance(address, block_number)
        
        # Delegated power
        delegated_power = self.delegate_power.get(address, Decimal("0"))
        
        return direct_power + delegated_power
    
    async def get_delegation_info(self, address: str) -> Dict[str, Any]:
        """Get delegation information for address."""
        return {
            'is_delegating': address in self.delegations,
            'delegate_address': self.delegations.get(address),
            'received_delegations': self.delegate_power.get(address, Decimal("0")),
            'total_voting_power': await self.get_voting_power(address)
        }
    
    async def _get_token_balance(self, address: str, block_number: Optional[int] = None) -> Decimal:
        """Get governance token balance for address."""
        # This would query the actual governance token contract
        # Mock implementation
        return Decimal("1000")


class DecisionEngine:
    """Engine for processing governance decisions."""
    
    def __init__(self, governance_token: GovernanceToken):
        self.governance_token = governance_token
        self.logger = logging.getLogger(__name__)
    
    async def evaluate_proposal(self, proposal: Proposal) -> Dict[str, Any]:
        """Evaluate proposal and determine outcome."""
        try:
            # Calculate vote results
            proposal.calculate_results(
                self.governance_token.total_supply,
                self.governance_token.quorum_threshold
            )
            
            # Determine outcome
            outcome = self._determine_outcome(proposal)
            
            # Generate evaluation report
            evaluation = {
                'proposal_id': str(proposal.id),
                'outcome': outcome,
                'votes_for': str(proposal.votes_for),
                'votes_against': str(proposal.votes_against),
                'votes_abstain': str(proposal.votes_abstain),
                'total_votes': str(proposal.total_votes),
                'approval_percentage': proposal.get_approval_percentage(),
                'quorum_reached': proposal.quorum_reached,
                'quorum_percentage': float((proposal.total_votes / self.governance_token.total_supply) * 100),
                'required_quorum': float(self.governance_token.quorum_threshold),
                'evaluation_timestamp': datetime.utcnow().isoformat()
            }
            
            return evaluation
            
        except Exception as e:
            self.logger.error(f"Proposal evaluation failed: {e}")
            return {'error': str(e)}
    
    def _determine_outcome(self, proposal: Proposal) -> str:
        """Determine proposal outcome based on votes."""
        if not proposal.quorum_reached:
            return "FAILED_QUORUM"
        
        if proposal.votes_for > proposal.votes_against:
            return "APPROVED"
        else:
            return "REJECTED"


