    async def _governance_monitor(self) -> None:
        """Monitor governance system and process proposals."""
        while True:
            try:
                # Check proposal statuses
                await self._update_proposal_statuses()
                
                # Process voting results
                await self._process_voting_results()
                
                # Execute ready proposals
                await self._execute_ready_proposals()
                
                await asyncio.sleep(300)  # Check every 5 minutes
                
            except Exception as e:
                self.logger.error(f"Governance monitoring error: {e}")
                await asyncio.sleep(300)
    
    async def _update_proposal_statuses(self) -> None:
        """Update status of active proposals."""
        now = datetime.utcnow()
        
        for proposal in list(self.proposal_manager.active_proposals.values()):
            # Start voting if ready
            if (proposal.status == ProposalStatus.DRAFT and 
                proposal.voting_starts_at and now >= proposal.voting_starts_at):
                proposal.status = ProposalStatus.ACTIVE
            
            # End voting if time expired
            elif (proposal.status == ProposalStatus.ACTIVE and 
                  proposal.voting_ends_at and now >= proposal.voting_ends_at):
                evaluation = await self.decision_engine.evaluate_proposal(proposal)
                if evaluation['outcome'] == 'APPROVED':
                    proposal.status = ProposalStatus.SUCCEEDED
                else:
                    proposal.status = ProposalStatus.DEFEATED
    
    async def _process_voting_results(self) -> None:
        """Process voting results for active proposals."""
