class ThreatLevel(Enum):
    """Security threat levels."""
    LOW = 1
    MEDIUM = 2
    HIGH = 3
    CRITICAL = 4
    EMERGENCY = 5


class SecurityEventType(Enum):
    """Types of security events."""
    SUSPICIOUS_TRANSACTION = "suspicious_transaction"
    RATE_LIMIT_EXCEEDED = "rate_limit_exceeded"
    INVALID_SIGNATURE = "invalid_signature"
    UNAUTHORIZED_ACCESS = "unauthorized_access"
    LARGE_TRANSFER = "large_transfer"
    UNUSUAL_PATTERN = "unusual_pattern"
    MALICIOUS_CONTRACT = "malicious_contract"
    BRIDGE_EXPLOIT_ATTEMPT = "bridge_exploit_attempt"
    GOVERNANCE_ATTACK = "governance_attack"
    ORACLE_MANIPULATION = "oracle_manipulation"


class ComplianceStatus(Enum):
    """Compliance validation status."""
    COMPLIANT = "compliant"
    NON_COMPLIANT = "non_compliant"
    UNDER_REVIEW = "under_review"
    BLACKLISTED = "blacklisted"
    WHITELISTED = "whitelisted"


@dataclass
class SecurityEvent:
    """Security event data structure."""
    id: UUID = field(default_factory=uuid4)
    event_type: SecurityEventType = SecurityEventType.SUSPICIOUS_TRANSACTION
    threat_level: ThreatLevel = ThreatLevel.LOW
    timestamp: datetime = field(default_factory=datetime.utcnow)
    
    # Event details
    source_address: Optional[str] = None
    target_address: Optional[str] = None
    transaction_hash: Optional[str] = None
    chain_id: Optional[int] = None
    amount: Optional[Decimal] = None
    asset_id: Optional[str] = None
    
    # Security context
    ip_address: Optional[str] = None
    user_agent: Optional[str] = None
    geolocation: Optional[Dict[str, str]] = None
    
    # Analysis results
    risk_score: float = 0.0
    confidence: float = 0.0
    indicators: List[str] = field(default_factory=list)
    mitigation_actions: List[str] = field(default_factory=list)
    
    # Status
    is_resolved: bool = False
    resolution_notes: Optional[str] = None
    resolved_at: Optional[datetime] = None
    
    # Metadata
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class SecurityPolicy:
    """Security policy configuration."""
    id: UUID = field(default_factory=uuid4)
    name: str = ""
    description: str = ""
    is_active: bool = True
    
    # Policy rules
    max_transaction_amount: Optional[Decimal] = None
    max_daily_volume: Optional[Decimal] = None
    allowed_addresses: Set[str] = field(default_factory=set)
    blocked_addresses: Set[str] = field(default_factory=set)
    allowed_countries: Set[str] = field(default_factory=set)
    blocked_countries: Set[str] = field(default_factory=set)
    
    # Rate limiting
    max_transactions_per_hour: int = 100
    max_transactions_per_day: int = 1000
    
    # Security thresholds
    risk_score_threshold: float = 0.7
    auto_block_threshold: float = 0.9
    manual_review_threshold: float = 0.5
    
    # Compliance requirements
    kyc_required: bool = False
    aml_screening: bool = True
    sanctions_screening: bool = True
    
    # Metadata
    created_at: datetime = field(default_factory=datetime.utcnow)
    updated_at: datetime = field(default_factory=datetime.utcnow)


class ThreatDetector:
    """Advanced threat detection system."""
    
    def __init__(self, redis_client: aioredis.Redis):
        self.redis_client = redis_client
        self.logger = logging.getLogger(__name__)
        
        # Detection patterns
        self.suspicious_patterns = {
            'rapid_succession': {
                'max_transactions': 10,
                'time_window': 300,  # 5 minutes
                'risk_score': 0.6
            },
            'large_amounts': {
                'threshold_multiplier': 10,  # 10x average
                'risk_score': 0.8
            },
            'unusual_timing': {
                'off_hours_multiplier': 2.0,
                'risk_score': 0.4
            },
            'new_address': {
                'age_threshold': 86400,  # 24 hours
                'risk_score': 0.3
            }
        }
        
        # Known threat indicators
        self.threat_indicators = {
            'known_phishing_addresses': set(),
            'exploit_signatures': set(),
            'malicious_contracts': set(),
            'high_risk_ips': set()
        }
    
    async def analyze_transaction(self, 
                                 transaction_data: Dict[str, Any]) -> SecurityEvent:
        """Analyze transaction for security threats."""
        try:
            event = SecurityEvent(
                source_address=transaction_data.get('from'),
                target_address=transaction_data.get('to'),
                transaction_hash=transaction_data.get('hash'),
                amount=Decimal(str(transaction_data.get('amount', 0))),
                asset_id=transaction_data.get('asset_id')
            )
            
            # Run multiple detection algorithms
            risk_scores = []
            
            # Pattern-based detection
            pattern_score = await self._detect_suspicious_patterns(transaction_data)
            risk_scores.append(pattern_score)
            
            # Address reputation analysis
            address_score = await self._analyze_address_reputation(
                transaction_data.get('from')
            )
            risk_scores.append(address_score)
            
            # Amount analysis
            amount_score = await self._analyze_transaction_amount(
                transaction_data.get('amount', 0)
            )
            risk_scores.append(amount_score)
            
            # Timing analysis
            timing_score = await self._analyze_transaction_timing(
                transaction_data.get('timestamp', datetime.utcnow())
            )
            risk_scores.append(timing_score)
            
            # ML-based anomaly detection
            ml_score = await self._ml_anomaly_detection(transaction_data)
            risk_scores.append(ml_score)
            
            # Calculate overall risk score
            event.risk_score = max(risk_scores) if risk_scores else 0.0
            event.confidence = sum(risk_scores) / len(risk_scores) if risk_scores else 0.0
            
            # Determine threat level
            event.threat_level = self._calculate_threat_level(event.risk_score)
            
            # Generate mitigation recommendations
            event.mitigation_actions = await self._generate_mitigation_actions(event)
            
            return event
            
        except Exception as e:
            self.logger.error(f"Transaction analysis failed: {e}")
            return SecurityEvent(risk_score=0.5, threat_level=ThreatLevel.MEDIUM)
    
    async def _detect_suspicious_patterns(self, transaction_data: Dict[str, Any]) -> float:
        """Detect suspicious transaction patterns."""
        try:
            risk_score = 0.0
            sender = transaction_data.get('from')
            
            if not sender:
                return 0.0
            
            # Check rapid succession pattern
            recent_txs = await self._get_recent_transactions(sender, 300)
            if len(recent_txs) > self.suspicious_patterns['rapid_succession']['max_transactions']:
                risk_score = max(risk_score, self.suspicious_patterns['rapid_succession']['risk_score'])
            
            # Check for round number amounts (often suspicious)
            amount = float(transaction_data.get('amount', 0))
            if amount > 0 and amount == int(amount) and amount >= 1000:
                risk_score = max(risk_score, 0.3)
            
            # Check for contract interaction patterns
            if transaction_data.get('to') in self.threat_indicators['malicious_contracts']:
                risk_score = max(risk_score, 0.9)
            
            return risk_score
            
        except Exception as e:
            self.logger.error(f"Pattern detection failed: {e}")
            return 0.0
    
    async def _analyze_address_reputation(self, address: str) -> float:
        """Analyze address reputation and history."""
        try:
            if not address:
                return 0.0
            
            # Check against known threat lists
            if address in self.threat_indicators['known_phishing_addresses']:
                return 0.95
            
            # Check address age
            address_age = await self._get_address_age(address)
            if address_age < self.suspicious_patterns['new_address']['age_threshold']:
                return self.suspicious_patterns['new_address']['risk_score']
            
            # Check transaction history
            tx_count = await self._get_address_transaction_count(address)
            if tx_count < 5:  # Very new or inactive address
                return 0.4
            
            # Check for previous security events
            security_events = await self._get_address_security_events(address)
            if security_events:
                return min(0.8, len(security_events) * 0.1)
            
            return 0.0
            
        except Exception as e:
            self.logger.error(f"Address reputation analysis failed: {e}")
            return 0.0
    
    async def _analyze_transaction_amount(self, amount: float) -> float:
        """Analyze transaction amount for anomalies."""
        try:
            if amount <= 0:
                return 0.0
            
            # Get average transaction amount for comparison
            avg_amount = await self._get_average_transaction_amount()
            
            if amount > avg_amount * self.suspicious_patterns['large_amounts']['threshold_multiplier']:
                return self.suspicious_patterns['large_amounts']['risk_score']
            
            # Check for micro-transactions (potential dust attacks)
            if amount < 0.01:
                return 0.2
            
            return 0.0
            
        except Exception as e:
            self.logger.error(f"Amount analysis failed: {e}")
            return 0.0
    
    async def _analyze_transaction_timing(self, timestamp: datetime) -> float:
        """Analyze transaction timing patterns."""
        try:
            # Check if transaction is during off-hours (suspicious timing)
            hour = timestamp.hour
            if hour < 6 or hour > 22:  # Late night/early morning
                return self.suspicious_patterns['unusual_timing']['risk_score']
            
            # Check for weekend activity (context dependent)
            if timestamp.weekday() >= 5:  # Saturday or Sunday
                return 0.2
            
            return 0.0
            
        except Exception as e:
            self.logger.error(f"Timing analysis failed: {e}")
            return 0.0
    
    async def _ml_anomaly_detection(self, transaction_data: Dict[str, Any]) -> float:
        """Machine learning-based anomaly detection."""
        try:
            # This would implement actual ML models for anomaly detection
            # For now, return a mock score based on simple heuristics
            
            features = [
                float(transaction_data.get('amount', 0)),
                len(transaction_data.get('from', '')),
                len(transaction_data.get('to', '')),
                int(transaction_data.get('gas', 21000)),
            ]
            
            # Simple anomaly score calculation (would be replaced with actual ML model)
            anomaly_score = sum(features) / len(features) / 1000000
            return min(anomaly_score, 1.0)
            
        except Exception as e:
            self.logger.error(f"ML anomaly detection failed: {e}")
            return 0.0
    
    def _calculate_threat_level(self, risk_score: float) -> ThreatLevel:
        """Calculate threat level based on risk score."""
        if risk_score >= 0.9:
            return ThreatLevel.EMERGENCY
        elif risk_score >= 0.7:
            return ThreatLevel.CRITICAL
        elif risk_score >= 0.5:
            return ThreatLevel.HIGH
        elif risk_score >= 0.3:
            return ThreatLevel.MEDIUM
        else:
            return ThreatLevel.LOW
    
    async def _generate_mitigation_actions(self, event: SecurityEvent) -> List[str]:
        """Generate recommended mitigation actions."""
        actions = []
        
        if event.threat_level == ThreatLevel.EMERGENCY:
            actions.extend([
                "Immediately halt all bridge operations",
                "Alert security team",
                "Freeze suspected addresses",
                "Initiate incident response protocol"
            ])
        elif event.threat_level == ThreatLevel.CRITICAL:
            actions.extend([
                "Flag transaction for manual review",
                "Temporarily suspend sender address",
                "Increase monitoring for related addresses",
                "Generate security alert"
            ])
        elif event.threat_level == ThreatLevel.HIGH:
            actions.extend([
                "Queue for enhanced verification",
                "Require additional confirmations",
                "Log for investigation"
            ])
        
        return actions
    
