"""Data Validators - Comprehensive Validation Functions
===================================================

Robust validation utilities for blockchain bridge operations, ensuring
data integrity and security across all bridge transactions and operations
in the Spotify AI Agent ecosystem.

Author: Fahed Mlaiel <mlaiel@live.de>
Copyright: © 2025 Fahed Mlaiel. All rights reserved.
"""
import re
import logging
from decimal import Decimal, InvalidOperation
from typing import Dict, List, Optional, Any, Union
from dataclasses import dataclass
from enum import Enum

from web3 import Web3
from eth_typing import Address, HexStr
from eth_utils import is_address, is_checksum_address, to_checksum_address

from .constants import SUPPORTED_CHAINS, ERROR_CODES


class ValidationError(Exception):
    """Custom validation error."""
    
    def __init__(self, message: str, error_code: str = "VALIDATION_ERROR"):
        self.message = message
        self.error_code = error_code
        super().__init__(self.message)


class ValidationType(Enum):
    """Types of validations."""
    ADDRESS = "address"
    TRANSACTION = "transaction"
    AMOUNT = "amount"
    CHAIN = "chain"
    TOKEN = "token"
    SIGNATURE = "signature"


@dataclass
class ValidationResult:
    """Result of validation operation."""
    is_valid: bool = False
    error_message: str = ""
    error_code: str = ""
    validated_value: Optional[Any] = None
    suggestions: List[str] = None
    
    def __post_init__(self):
        if self.suggestions is None:
            self.suggestions = []


class AddressValidator:
    """Ethereum address validation utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        
        # Regex patterns
        self.hex_pattern = re.compile(r'^0x[a-fA-F0-9]{40}$')
        self.ens_pattern = re.compile(r'^[a-zA-Z0-9-]+\.eth$')
    
    def validate_ethereum_address(self, address: str) -> ValidationResult:
        """Validate Ethereum address format and checksum."""
        try:
            if not address:
                return ValidationResult(
                    is_valid=False,
                    error_message="Address cannot be empty",
                    error_code=ERROR_CODES["EMPTY_ADDRESS"]
                )
            
            # Clean address
            address = address.strip()
            
            # Check basic format
            if not self.hex_pattern.match(address):
                return ValidationResult(
                    is_valid=False,
                    error_message="Invalid address format",
                    error_code=ERROR_CODES["INVALID_FORMAT"],
                    suggestions=["Ensure address starts with 0x and has 40 hex characters"]
                )
            
            # Validate using web3
            if not is_address(address):
                return ValidationResult(
                    is_valid=False,
                    error_message="Invalid Ethereum address",
                    error_code=ERROR_CODES["INVALID_ADDRESS"]
                )
            
            # Check checksum if mixed case
            if address != address.lower() and address != address.upper():
                if not is_checksum_address(address):
                    return ValidationResult(
                        is_valid=False,
                        error_message="Invalid address checksum",
                        error_code=ERROR_CODES["INVALID_CHECKSUM"],
                        suggestions=[f"Correct checksum: {to_checksum_address(address)}"]
                    )
            
            # Return validated address with proper checksum
            validated_address = to_checksum_address(address)
            
            return ValidationResult(
                is_valid=True,
                validated_value=validated_address
            )
            
        except Exception as e:
            self.logger.error(f"Address validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )
    
    def validate_contract_address(self, 
                                address: str, 
                                web3_instance: Web3) -> ValidationResult:
        """Validate contract address and check if it's a contract."""
        try:
            # First validate basic address format
            basic_validation = self.validate_ethereum_address(address)
            if not basic_validation.is_valid:
                return basic_validation
            
            validated_address = basic_validation.validated_value
            
            # Check if address has contract code
            try:
                code = web3_instance.eth.get_code(validated_address)
                if code == b'':
                    return ValidationResult(
                        is_valid=False,
                        error_message="Address is not a contract",
                        error_code=ERROR_CODES["NOT_CONTRACT"],
                        suggestions=["Verify the contract address is correct and deployed"]
                    )
            except Exception:
                return ValidationResult(
                    is_valid=False,
                    error_message="Unable to verify contract status",
                    error_code=ERROR_CODES["NETWORK_ERROR"]
                )
            
            return ValidationResult(
                is_valid=True,
                validated_value=validated_address
            )
            
        except Exception as e:
            self.logger.error(f"Contract validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Contract validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )
    
    def validate_ens_name(self, ens_name: str) -> ValidationResult:
        """Validate ENS domain name format."""
        try:
            if not ens_name:
                return ValidationResult(
                    is_valid=False,
                    error_message="ENS name cannot be empty",
                    error_code=ERROR_CODES["EMPTY_VALUE"]
                )
            
            ens_name = ens_name.strip().lower()
            
            if not self.ens_pattern.match(ens_name):
                return ValidationResult(
                    is_valid=False,
                    error_message="Invalid ENS name format",
                    error_code=ERROR_CODES["INVALID_FORMAT"],
                    suggestions=["ENS names should end with .eth"]
                )
            
            return ValidationResult(
                is_valid=True,
                validated_value=ens_name
            )
            
        except Exception as e:
            self.logger.error(f"ENS validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"ENS validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )


class TransactionValidator:
    """Transaction validation utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.hash_pattern = re.compile(r'^0x[a-fA-F0-9]{64}$')
    
    def validate_transaction_hash(self, tx_hash: str) -> ValidationResult:
        """Validate transaction hash format."""
        try:
            if not tx_hash:
                return ValidationResult(
                    is_valid=False,
                    error_message="Transaction hash cannot be empty",
                    error_code=ERROR_CODES["EMPTY_VALUE"]
                )
            
            tx_hash = tx_hash.strip()
            
            if not self.hash_pattern.match(tx_hash):
                return ValidationResult(
                    is_valid=False,
                    error_message="Invalid transaction hash format",
                    error_code=ERROR_CODES["INVALID_FORMAT"],
                    suggestions=["Transaction hash should be 0x followed by 64 hex characters"]
                )
            
            return ValidationResult(
                is_valid=True,
                validated_value=tx_hash.lower()
            )
            
        except Exception as e:
            self.logger.error(f"Transaction hash validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Transaction hash validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )
    
    def validate_transaction_data(self, tx_data: Dict[str, Any]) -> ValidationResult:
        """Validate transaction data structure."""
        try:
            required_fields = ['to', 'value', 'gas', 'gasPrice']
            optional_fields = ['data', 'nonce', 'from']
            
            # Check required fields
            missing_fields = []
            for field in required_fields:
                if field not in tx_data:
                    missing_fields.append(field)
            
            if missing_fields:
                return ValidationResult(
                    is_valid=False,
                    error_message=f"Missing required fields: {', '.join(missing_fields)}",
                    error_code=ERROR_CODES["MISSING_FIELDS"]
                )
            
            # Validate field values
            address_validator = AddressValidator()
            amount_validator = AmountValidator()
            
            # Validate 'to' address
            to_validation = address_validator.validate_ethereum_address(tx_data['to'])
            if not to_validation.is_valid:
                return ValidationResult(
                    is_valid=False,
                    error_message=f"Invalid 'to' address: {to_validation.error_message}",
                    error_code=to_validation.error_code
                )
            
            # Validate 'from' address if provided
            if 'from' in tx_data:
                from_validation = address_validator.validate_ethereum_address(tx_data['from'])
                if not from_validation.is_valid:
                    return ValidationResult(
                        is_valid=False,
                        error_message=f"Invalid 'from' address: {from_validation.error_message}",
                        error_code=from_validation.error_code
                    )
            
            # Validate amounts
            for field in ['value', 'gas', 'gasPrice']:
                if field in tx_data:
                    amount_validation = amount_validator.validate_amount(tx_data[field])
                    if not amount_validation.is_valid:
                        return ValidationResult(
                            is_valid=False,
                            error_message=f"Invalid '{field}': {amount_validation.error_message}",
                            error_code=amount_validation.error_code
                        )
            
            return ValidationResult(
                is_valid=True,
                validated_value=tx_data
            )
            
        except Exception as e:
            self.logger.error(f"Transaction data validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Transaction data validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )


class AmountValidator:
    """Amount and value validation utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
    
    def validate_amount(self, 
                       amount: Union[str, int, float, Decimal],
                       min_value: Optional[Decimal] = None,
                       max_value: Optional[Decimal] = None,
                       decimals: int = 18) -> ValidationResult:
        """Validate amount format and range."""
        try:
            if amount is None:
                return ValidationResult(
                    is_valid=False,
                    error_message="Amount cannot be None",
                    error_code=ERROR_CODES["EMPTY_VALUE"]
                )
            
            # Convert to Decimal
            try:
                if isinstance(amount, str):
                    # Remove whitespace and common formatting
                    amount = amount.strip().replace(',', '')
                
                decimal_amount = Decimal(str(amount))
            except (InvalidOperation, ValueError):
                return ValidationResult(
                    is_valid=False,
                    error_message="Invalid amount format",
                    error_code=ERROR_CODES["INVALID_FORMAT"],
                    suggestions=["Ensure amount is a valid number"]
                )
            
            # Check for negative amounts
            if decimal_amount < 0:
                return ValidationResult(
                    is_valid=False,
                    error_message="Amount cannot be negative",
                    error_code=ERROR_CODES["NEGATIVE_VALUE"]
                )
            
            # Check minimum value
            if min_value is not None and decimal_amount < min_value:
                return ValidationResult(
                    is_valid=False,
                    error_message=f"Amount must be at least {min_value}",
                    error_code=ERROR_CODES["VALUE_TOO_LOW"]
                )
            
            # Check maximum value
            if max_value is not None and decimal_amount > max_value:
                return ValidationResult(
                    is_valid=False,
                    error_message=f"Amount cannot exceed {max_value}",
                    error_code=ERROR_CODES["VALUE_TOO_HIGH"]
                )
            
            # Check decimal places
            if decimal_amount.as_tuple().exponent < -decimals:
                return ValidationResult(
                    is_valid=False,
                    error_message=f"Amount cannot have more than {decimals} decimal places",
                    error_code=ERROR_CODES["TOO_MANY_DECIMALS"]
                )
            
            return ValidationResult(
                is_valid=True,
                validated_value=decimal_amount
            )
            
        except Exception as e:
            self.logger.error(f"Amount validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Amount validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )
    
    def validate_wei_amount(self, wei_amount: Union[str, int]) -> ValidationResult:
        """Validate Wei amount (smallest Ethereum unit)."""
        try:
            # Convert to int
            try:
                wei_int = int(wei_amount)
            except (ValueError, TypeError):
                return ValidationResult(
                    is_valid=False,
                    error_message="Wei amount must be an integer",
                    error_code=ERROR_CODES["INVALID_FORMAT"]
                )
            
            # Check for negative amounts
            if wei_int < 0:
                return ValidationResult(
                    is_valid=False,
                    error_message="Wei amount cannot be negative",
                    error_code=ERROR_CODES["NEGATIVE_VALUE"]
                )
            
            # Check reasonable upper bound (1 billion ETH in Wei)
            max_wei = 10**27  # 1 billion ETH
            if wei_int > max_wei:
                return ValidationResult(
                    is_valid=False,
                    error_message="Wei amount exceeds reasonable limit",
                    error_code=ERROR_CODES["VALUE_TOO_HIGH"]
                )
            
            return ValidationResult(
                is_valid=True,
                validated_value=wei_int
            )
            
        except Exception as e:
            self.logger.error(f"Wei validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Wei validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )


class ChainValidator:
    """Blockchain network validation utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
    
    def validate_chain_id(self, chain_id: Union[str, int]) -> ValidationResult:
        """Validate blockchain chain ID."""
        try:
            # Convert to int
            try:
                chain_id_int = int(chain_id)
            except (ValueError, TypeError):
                return ValidationResult(
                    is_valid=False,
                    error_message="Chain ID must be a number",
                    error_code=ERROR_CODES["INVALID_FORMAT"]
                )
            
            # Check if supported
            if chain_id_int not in SUPPORTED_CHAINS:
                return ValidationResult(
                    is_valid=False,
                    error_message=f"Unsupported chain ID: {chain_id_int}",
                    error_code=ERROR_CODES["UNSUPPORTED_CHAIN"],
                    suggestions=[f"Supported chains: {list(SUPPORTED_CHAINS.keys())}"]
                )
            
            return ValidationResult(
                is_valid=True,
                validated_value=chain_id_int
            )
            
        except Exception as e:
            self.logger.error(f"Chain ID validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Chain ID validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )
    
    def validate_network_config(self, config: Dict[str, Any]) -> ValidationResult:
        """Validate network configuration."""
        try:
            required_fields = ['chain_id', 'name', 'rpc_url']
            optional_fields = ['explorer_url', 'native_currency', 'block_time']
            
            # Check required fields
            missing_fields = []
            for field in required_fields:
                if field not in config:
                    missing_fields.append(field)
            
            if missing_fields:
                return ValidationResult(
                    is_valid=False,
                    error_message=f"Missing required fields: {', '.join(missing_fields)}",
                    error_code=ERROR_CODES["MISSING_FIELDS"]
                )
            
            # Validate chain ID
            chain_validation = self.validate_chain_id(config['chain_id'])
            if not chain_validation.is_valid:
                return chain_validation
            
            # Validate RPC URL
            if not config['rpc_url'].startswith(('http://', 'https://', 'wss://')):
                return ValidationResult(
                    is_valid=False,
                    error_message="Invalid RPC URL format",
                    error_code=ERROR_CODES["INVALID_FORMAT"],
                    suggestions=["RPC URL should start with http://, https://, or wss://"]
                )
            
            return ValidationResult(
                is_valid=True,
                validated_value=config
            )
            
        except Exception as e:
            self.logger.error(f"Network config validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Network config validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )


class SignatureValidator:
    """Digital signature validation utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.signature_pattern = re.compile(r'^0x[a-fA-F0-9]{130}$')  # 65 bytes = 130 hex chars
    
    def validate_signature_format(self, signature: str) -> ValidationResult:
        """Validate signature format."""
        try:
            if not signature:
                return ValidationResult(
                    is_valid=False,
                    error_message="Signature cannot be empty",
                    error_code=ERROR_CODES["EMPTY_VALUE"]
                )
            
            signature = signature.strip()
            
            if not self.signature_pattern.match(signature):
                return ValidationResult(
                    is_valid=False,
                    error_message="Invalid signature format",
                    error_code=ERROR_CODES["INVALID_FORMAT"],
                    suggestions=["Signature should be 0x followed by 130 hex characters"]
                )
            
            return ValidationResult(
                is_valid=True,
                validated_value=signature.lower()
            )
            
        except Exception as e:
            self.logger.error(f"Signature validation error: {e}")
            return ValidationResult(
                is_valid=False,
                error_message=f"Signature validation error: {str(e)}",
                error_code=ERROR_CODES["VALIDATION_ERROR"]
            )


# Convenience functions
def validate_ethereum_address(address: str) -> ValidationResult:
    """Convenience function for address validation."""
    validator = AddressValidator()
    return validator.validate_ethereum_address(address)


def validate_transaction_hash(tx_hash: str) -> ValidationResult:
    """Convenience function for transaction hash validation."""
    validator = TransactionValidator()
    return validator.validate_transaction_hash(tx_hash)


def validate_amount(amount: Union[str, int, float, Decimal],
                   min_value: Optional[Decimal] = None,
                   max_value: Optional[Decimal] = None,
                   decimals: int = 18) -> ValidationResult:
    """Convenience function for amount validation."""
    validator = AmountValidator()
    return validator.validate_amount(amount, min_value, max_value, decimals)


def validate_chain_id(chain_id: Union[str, int]) -> ValidationResult:
    """Convenience function for chain ID validation."""
    validator = ChainValidator()
    return validator.validate_chain_id(chain_id)


def validate_signature_format(signature: str) -> ValidationResult:
    """Convenience function for signature validation."""
    validator = SignatureValidator()
    return validator.validate_signature_format(signature)


# Batch validation functions
async def validate_batch_addresses(addresses: List[str]) -> Dict[str, ValidationResult]:
    """Validate multiple addresses in batch."""
    validator = AddressValidator()
    results = {}
    
    for i, address in enumerate(addresses):
        results[f"address_{i}"] = validator.validate_ethereum_address(address)
    
    return results


async def validate_batch_amounts(amounts: List[Union[str, int, float, Decimal]]) -> Dict[str, ValidationResult]:
    """Validate multiple amounts in batch."""
    validator = AmountValidator()
    results = {}
    
    for i, amount in enumerate(amounts):
        results[f"amount_{i}"] = validator.validate_amount(amount)
    
    return results
