"""Content License Manager for Blockchain-Based Rights Management
============================================================

Advanced smart contract system for managing content licenses,
royalty distribution, and rights enforcement on blockchain.

Author: Fahed Mlaiel <mlaiel@live.de>
⚠️ STRICT COPYRIGHT WARNING - Unauthorized use prohibited ⚠️
"""
import asyncio
import logging
from datetime import datetime, timedelta
from typing import Dict, List, Optional, Any, Set
from dataclasses import dataclass, field
from enum import Enum
import json
import hashlib
from decimal import Decimal
import uuid

logger = logging.getLogger(__name__)

class LicenseType(Enum):
    """Types of content licenses."""
    EXCLUSIVE = "exclusive"
    NON_EXCLUSIVE = "non_exclusive"
    CREATIVE_COMMONS = "creative_commons"
    ROYALTY_FREE = "royalty_free"
    RIGHTS_MANAGED = "rights_managed"
    EDITORIAL = "editorial"
    COMMERCIAL = "commercial"

class LicenseStatus(Enum):
    """Status of a license."""
    ACTIVE = "active"
    PENDING = "pending"
    EXPIRED = "expired"
    REVOKED = "revoked"
    DISPUTED = "disputed"
    SUSPENDED = "suspended"

class RoyaltyType(Enum):
    """Types of royalty structures."""
    PERCENTAGE = "percentage"
    FIXED_AMOUNT = "fixed_amount"
    TIERED = "tiered"
    REVENUE_SHARE = "revenue_share"
    USAGE_BASED = "usage_based"

@dataclass
class ContentFingerprint:
    """Blockchain fingerprint of protected content."""
    fingerprint_hash: str
    content_type: str  # audio, video, image, text
    original_hash: str
    blockchain_tx_id: str
    timestamp: datetime
    creator_id: str
    metadata: Dict[str, Any] = field(default_factory=dict)

@dataclass
class LicenseTerms:
    """Terms and conditions of a content license."""
    license_type: LicenseType
    duration_days: Optional[int]  # None for perpetual
    territory: List[str]  # Country codes or ["worldwide"]
    usage_rights: List[str]  # ["commercial", "editorial", "derivative", etc.]
    royalty_type: RoyaltyType
    royalty_rate: Decimal  # Percentage or fixed amount
    exclusivity: bool
    transferable: bool
    sublicensable: bool
    attribution_required: bool
    restrictions: List[str] = field(default_factory=list)
    custom_terms: Dict[str, Any] = field(default_factory=dict)

@dataclass
class ContentLicense:
    """Complete content license record."""
    license_id: str
    content_fingerprint: ContentFingerprint
    licensor_id: str  # Rights holder
    licensee_id: str  # License holder
    terms: LicenseTerms
    status: LicenseStatus
    created_at: datetime
    expires_at: Optional[datetime]
    blockchain_contract_address: str
    transaction_hash: str
    license_fee: Decimal
    currency: str = "USD"
    payment_status: str = "pending"
    usage_count: int = 0
    revenue_generated: Decimal = field(default_factory=lambda: Decimal('0'))

@dataclass
class RoyaltyPayment:
    """Record of royalty payment."""
    payment_id: str
    license_id: str
    recipient_id: str
    amount: Decimal
    currency: str
    payment_date: datetime
    transaction_hash: str
    usage_period_start: datetime
    usage_period_end: datetime
    usage_count: int
    payment_status: str = "completed"

class ContentLicenseManager:
    """
    Advanced content license management system using blockchain
    for transparent, immutable, and automated rights management.
    """
    
    def __init__(self, blockchain_config: Dict[str, Any] = None):
        self.blockchain_config = blockchain_config or {}
        self.active_licenses: Dict[str, ContentLicense] = {}
        self.content_registry: Dict[str, ContentFingerprint] = {}
        self.royalty_payments: List[RoyaltyPayment] = []
        
        # Smart contract interfaces (simulated)
        self.license_contract_address = self.blockchain_config.get(
            'license_contract', '0x1234567890abcdef'
        )
        
        # Configuration
        self.min_license_duration = 1  # Minimum 1 day
        self.max_license_duration = 365 * 10  # Maximum 10 years
        self.default_royalty_rate = Decimal('0.05')  # 5%
        self.gas_price_gwei = 20
        
        logger.info("ContentLicenseManager initialized with blockchain integration")
    
    async def register_content(self,
                             content_data: bytes,
                             content_type: str,
                             creator_id: str,
                             metadata: Dict[str, Any] = None) -> ContentFingerprint:
        """
        Register content on blockchain and create immutable fingerprint.
        
        Args:
            content_data: Raw content data for fingerprinting
            content_type: Type of content (audio, video, image, text)
            creator_id: ID of the content creator
            metadata: Additional metadata
            
        Returns:
            ContentFingerprint with blockchain transaction details
        """
        try:
            # Generate content fingerprint
            fingerprint_hash = self._generate_content_fingerprint(content_data, content_type)
            
            # Create original content hash
            original_hash = hashlib.sha256(content_data).hexdigest()
            
            # Simulate blockchain transaction
            tx_id = await self._submit_to_blockchain({
                'action': 'register_content',
                'fingerprint_hash': fingerprint_hash,
                'content_type': content_type,
                'creator_id': creator_id,
                'original_hash': original_hash,
                'timestamp': datetime.now().isoformat(),
                'metadata': metadata or {}
            })
            
            # Create fingerprint record
            fingerprint = ContentFingerprint(
                fingerprint_hash=fingerprint_hash,
                content_type=content_type,
                original_hash=original_hash,
                blockchain_tx_id=tx_id,
                timestamp=datetime.now(),
                creator_id=creator_id,
                metadata=metadata or {}
            )
            
            # Store in registry
            self.content_registry[fingerprint_hash] = fingerprint
            
            logger.info(f"Content registered: {fingerprint_hash} by {creator_id}")
            return fingerprint
            
        except Exception as e:
            logger.error(f"Content registration failed: {e}")
            raise
    
    async def create_license(self,
                           content_fingerprint: str,
                           licensor_id: str,
                           licensee_id: str,
                           terms: LicenseTerms,
                           license_fee: Decimal,
                           currency: str = "USD") -> ContentLicense:
        """
        Create a new content license with blockchain smart contract.
        
        Args:
            content_fingerprint: Hash of the registered content
            licensor_id: Rights holder ID
            licensee_id: License purchaser ID
            terms: License terms and conditions
            license_fee: Fee for the license
            currency: Currency for payments
            
        Returns:
            ContentLicense with smart contract details
        """
        try:
            # Verify content exists
            if content_fingerprint not in self.content_registry:
                raise ValueError(f"Content not registered: {content_fingerprint}")
            
            content = self.content_registry[content_fingerprint]
            
            # Verify licensor owns the content
            if content.creator_id != licensor_id:
                raise ValueError(f"Licensor {licensor_id} does not own content {content_fingerprint}")
            
            # Generate unique license ID
            license_id = str(uuid.uuid4())
            
            # Calculate expiration date
            expires_at = None
            if terms.duration_days:
                expires_at = datetime.now() + timedelta(days=terms.duration_days)
            
            # Create smart contract
            contract_data = {
                'license_id': license_id,
                'content_fingerprint': content_fingerprint,
                'licensor_id': licensor_id,
                'licensee_id': licensee_id,
                'terms': self._serialize_license_terms(terms),
                'license_fee': str(license_fee),
                'currency': currency,
                'expires_at': expires_at.isoformat() if expires_at else None
            }
            
            # Deploy to blockchain
            contract_address, tx_hash = await self._deploy_license_contract(contract_data)
            
            # Create license record
            license_record = ContentLicense(
                license_id=license_id,
                content_fingerprint=content,
                licensor_id=licensor_id,
                licensee_id=licensee_id,
                terms=terms,
                status=LicenseStatus.PENDING,
                created_at=datetime.now(),
                expires_at=expires_at,
                blockchain_contract_address=contract_address,
                transaction_hash=tx_hash,
                license_fee=license_fee,
                currency=currency,
                payment_status="pending"
            )
            
            # Store license
            self.active_licenses[license_id] = license_record
            
            logger.info(f"License created: {license_id} for content {content_fingerprint}")
            return license_record
            
        except Exception as e:
            logger.error(f"License creation failed: {e}")
            raise
    
    async def execute_license_payment(self,
                                    license_id: str,
                                    payment_tx_hash: str) -> bool:
        """
        Execute license payment and activate license.
        
        Args:
            license_id: ID of the license
            payment_tx_hash: Blockchain transaction hash of payment
            
        Returns:
            True if payment successful and license activated
        """
        try:
            if license_id not in self.active_licenses:
                raise ValueError(f"License not found: {license_id}")
            
            license_record = self.active_licenses[license_id]
            
            # Verify payment on blockchain
            payment_verified = await self._verify_payment(
                payment_tx_hash,
                license_record.license_fee,
                license_record.licensee_id,
                license_record.licensor_id
            )
            
            if payment_verified:
                # Activate license
                license_record.status = LicenseStatus.ACTIVE
                license_record.payment_status = "completed"
                
                # Update smart contract
                await self._update_license_contract(
                    license_record.blockchain_contract_address,
                    {'status': 'active', 'payment_tx': payment_tx_hash}
                )
                
                logger.info(f"License payment executed and activated: {license_id}")
                return True
            else:
                logger.error(f"Payment verification failed for license: {license_id}")
                return False
                
        except Exception as e:
            logger.error(f"License payment execution failed: {e}")
            return False
    
    async def track_content_usage(self,
                                license_id: str,
                                usage_context: Dict[str, Any]) -> bool:
        """
        Track content usage for royalty calculation.
        
        Args:
            license_id: ID of the license being used
            usage_context: Context of content usage (platform, views, revenue, etc.)
            
        Returns:
            True if usage tracked successfully
        """
        try:
            if license_id not in self.active_licenses:
                raise ValueError(f"License not found: {license_id}")
            
            license_record = self.active_licenses[license_id]
            
            # Verify license is active
            if license_record.status != LicenseStatus.ACTIVE:
                raise ValueError(f"License not active: {license_id}")
            
            # Check if license has expired
            if license_record.expires_at and datetime.now() > license_record.expires_at:
                license_record.status = LicenseStatus.EXPIRED
                raise ValueError(f"License expired: {license_id}")
            
            # Track usage
            license_record.usage_count += 1
            
            # Calculate revenue if provided
            if 'revenue' in usage_context:
                revenue = Decimal(str(usage_context['revenue']))
                license_record.revenue_generated += revenue
                
                # Calculate and process royalties
                await self._process_royalty_payment(license_record, revenue, usage_context)
            
            # Log usage to blockchain
            await self._log_usage_to_blockchain(license_id, usage_context)
            
            logger.info(f"Content usage tracked for license: {license_id}")
            return True
            
        except Exception as e:
            logger.error(f"Usage tracking failed: {e}")
            return False
    
    async def _process_royalty_payment(self,
                                     license_record: ContentLicense,
                                     revenue: Decimal,
                                     usage_context: Dict[str, Any]):
        """Process royalty payment based on license terms."""
        try:
            terms = license_record.terms
            
            # Calculate royalty amount
            if terms.royalty_type == RoyaltyType.PERCENTAGE:
                royalty_amount = revenue * (terms.royalty_rate / 100)
            elif terms.royalty_type == RoyaltyType.FIXED_AMOUNT:
                royalty_amount = terms.royalty_rate
            elif terms.royalty_type == RoyaltyType.REVENUE_SHARE:
                royalty_amount = revenue * terms.royalty_rate
            else:
                # Usage-based or tiered - simplified calculation
                royalty_amount = terms.royalty_rate
            
            # Create royalty payment record
            payment = RoyaltyPayment(
                payment_id=str(uuid.uuid4()),
                license_id=license_record.license_id,
                recipient_id=license_record.licensor_id,
                amount=royalty_amount,
                currency=license_record.currency,
                payment_date=datetime.now(),
                transaction_hash="",  # Will be set after blockchain transaction
                usage_period_start=datetime.now() - timedelta(days=1),
                usage_period_end=datetime.now(),
                usage_count=1,
                payment_status="pending"
            )
            
            # Execute payment on blockchain
            tx_hash = await self._execute_royalty_payment(payment)
            payment.transaction_hash = tx_hash
            payment.payment_status = "completed"
            
            # Store payment record
            self.royalty_payments.append(payment)
            
            logger.info(f"Royalty payment processed: {royalty_amount} {license_record.currency}")
            
        except Exception as e:
            logger.error(f"Royalty payment processing failed: {e}")
    
    async def verify_license_validity(self,
                                    license_id: str,
                                    usage_context: Dict[str, Any] = None) -> bool:
        """
        Verify if a license is valid for use.
        
        Args:
            license_id: ID of the license to verify
            usage_context: Context of intended usage
            
        Returns:
            True if license is valid for use
        """
        try:
            if license_id not in self.active_licenses:
                logger.warning(f"License not found: {license_id}")
                return False
            
            license_record = self.active_licenses[license_id]
            
            # Check license status
            if license_record.status != LicenseStatus.ACTIVE:
                logger.warning(f"License not active: {license_id} (status: {license_record.status})")
                return False
            
            # Check expiration
            if license_record.expires_at and datetime.now() > license_record.expires_at:
                license_record.status = LicenseStatus.EXPIRED
                logger.warning(f"License expired: {license_id}")
                return False
            
            # Check usage rights if context provided
            if usage_context:
                if not self._verify_usage_rights(license_record.terms, usage_context):
                    logger.warning(f"Usage rights violation for license: {license_id}")
                    return False
            
            # Verify on blockchain
            blockchain_valid = await self._verify_license_on_blockchain(
                license_record.blockchain_contract_address
            )
            
            if not blockchain_valid:
                logger.warning(f"Blockchain verification failed for license: {license_id}")
                return False
            
            logger.info(f"License verification successful: {license_id}")
            return True
            
        except Exception as e:
            logger.error(f"License verification failed: {e}")
            return False
    
    async def revoke_license(self,
                           license_id: str,
                           reason: str,
                           revoked_by: str) -> bool:
        """
        Revoke a license and update blockchain.
        
        Args:
            license_id: ID of the license to revoke
            reason: Reason for revocation
            revoked_by: ID of who is revoking the license
            
        Returns:
            True if revocation successful
        """
        try:
            if license_id not in self.active_licenses:
                raise ValueError(f"License not found: {license_id}")
            
            license_record = self.active_licenses[license_id]
            
            # Verify authority to revoke
            if revoked_by != license_record.licensor_id:
                # Could also allow admin revocation
                raise ValueError(f"Insufficient authority to revoke license: {license_id}")
            
            # Update license status
            license_record.status = LicenseStatus.REVOKED
            
            # Update blockchain contract
            await self._update_license_contract(
                license_record.blockchain_contract_address,
                {
                    'status': 'revoked',
                    'revocation_reason': reason,
                    'revoked_by': revoked_by,
                    'revoked_at': datetime.now().isoformat()
                }
            )
            
            logger.info(f"License revoked: {license_id} by {revoked_by} - {reason}")
            return True
            
        except Exception as e:
            logger.error(f"License revocation failed: {e}")
            return False
    
    async def get_license_analytics(self, license_id: str) -> Dict[str, Any]:
        """
        Get comprehensive analytics for a license.
        
        Args:
            license_id: ID of the license
            
        Returns:
            Analytics data including usage, revenue, and performance
        """
        try:
            if license_id not in self.active_licenses:
                raise ValueError(f"License not found: {license_id}")
            
            license_record = self.active_licenses[license_id]
            
            # Calculate royalty payments for this license
            license_royalties = [
                payment for payment in self.royalty_payments
                if payment.license_id == license_id
            ]
            
            total_royalties = sum(payment.amount for payment in license_royalties)
            
            # Calculate performance metrics
            days_active = (datetime.now() - license_record.created_at).days or 1
            avg_daily_usage = license_record.usage_count / days_active
            avg_daily_revenue = float(license_record.revenue_generated) / days_active
            
            analytics = {
                'license_id': license_id,
                'status': license_record.status.value,
                'created_at': license_record.created_at.isoformat(),
                'days_active': days_active,
                'usage_metrics': {
                    'total_usage_count': license_record.usage_count,
                    'avg_daily_usage': avg_daily_usage,
                    'usage_trend': self._calculate_usage_trend(license_id)
                },
                'revenue_metrics': {
                    'total_revenue_generated': float(license_record.revenue_generated),
                    'total_royalties_paid': float(total_royalties),
                    'avg_daily_revenue': avg_daily_revenue,
                    'currency': license_record.currency
                },
                'license_terms': {
                    'license_type': license_record.terms.license_type.value,
                    'royalty_rate': float(license_record.terms.royalty_rate),
                    'royalty_type': license_record.terms.royalty_type.value,
                    'exclusivity': license_record.terms.exclusivity,
                    'territory': license_record.terms.territory
                },
                'blockchain_info': {
                    'contract_address': license_record.blockchain_contract_address,
                    'transaction_hash': license_record.transaction_hash
                }
            }
            
            logger.info(f"License analytics generated for: {license_id}")
            return analytics
            
        except Exception as e:
            logger.error(f"License analytics generation failed: {e}")
            return {}
    
    def _generate_content_fingerprint(self, content_data: bytes, content_type: str) -> str:
        """Generate unique fingerprint for content."""
        # This would use advanced fingerprinting algorithms
        # For now, use a combination of hashes
        sha256_hash = hashlib.sha256(content_data).hexdigest()
        md5_hash = hashlib.md5(content_data).hexdigest()
        
        # Combine with content type and timestamp
        fingerprint_data = f"{content_type}:{sha256_hash}:{md5_hash}:{datetime.now().isoformat()}"
        return hashlib.sha256(fingerprint_data.encode()).hexdigest()
    
    async def _submit_to_blockchain(self, data: Dict[str, Any]) -> str:
        """Submit data to blockchain (simulated)."""
        # This would interact with actual blockchain
        tx_id = f"tx_{hashlib.sha256(json.dumps(data, sort_keys=True).encode()).hexdigest()[:16]}"
        
        # Simulate blockchain delay
        await asyncio.sleep(0.1)
        
        logger.debug(f"Blockchain transaction submitted: {tx_id}")
        return tx_id
    
    async def _deploy_license_contract(self, contract_data: Dict[str, Any]) -> Tuple[str, str]:
        """Deploy license smart contract (simulated)."""
        # Generate contract address
        contract_address = f"0x{hashlib.sha256(json.dumps(contract_data, sort_keys=True).encode()).hexdigest()[:40]}"
        
        # Submit transaction
        tx_hash = await self._submit_to_blockchain({
            'action': 'deploy_contract',
            'contract_type': 'content_license',
            'data': contract_data
        })
        
        logger.debug(f"License contract deployed: {contract_address}")
        return contract_address, tx_hash
    
    async def _verify_payment(self,
                            payment_tx_hash: str,
                            expected_amount: Decimal,
                            payer: str,
                            recipient: str) -> bool:
        """Verify payment on blockchain (simulated)."""
        # This would query blockchain for transaction details
        # For simulation, return True if transaction hash looks valid
        if len(payment_tx_hash) >= 32 and payment_tx_hash.startswith(('tx_', '0x')):
            logger.debug(f"Payment verified: {payment_tx_hash}")
            return True
        return False
    
    async def _update_license_contract(self,
                                     contract_address: str,
                                     updates: Dict[str, Any]) -> str:
        """Update license contract (simulated)."""
        tx_hash = await self._submit_to_blockchain({
            'action': 'update_contract',
            'contract_address': contract_address,
            'updates': updates
        })
        
        logger.debug(f"Contract updated: {contract_address}")
        return tx_hash
    
    async def _log_usage_to_blockchain(self,
                                     license_id: str,
                                     usage_context: Dict[str, Any]) -> str:
        """Log content usage to blockchain (simulated)."""
        tx_hash = await self._submit_to_blockchain({
            'action': 'log_usage',
            'license_id': license_id,
            'usage_context': usage_context,
            'timestamp': datetime.now().isoformat()
        })
        
        logger.debug(f"Usage logged to blockchain: {license_id}")
        return tx_hash
    
    async def _execute_royalty_payment(self, payment: RoyaltyPayment) -> str:
        """Execute royalty payment on blockchain (simulated)."""
        tx_hash = await self._submit_to_blockchain({
            'action': 'royalty_payment',
            'payment_id': payment.payment_id,
            'recipient': payment.recipient_id,
            'amount': str(payment.amount),
            'currency': payment.currency
        })
        
        logger.debug(f"Royalty payment executed: {payment.payment_id}")
        return tx_hash
    
    def _serialize_license_terms(self, terms: LicenseTerms) -> Dict[str, Any]:
        """Serialize license terms for blockchain storage."""
        return {
            'license_type': terms.license_type.value,
            'duration_days': terms.duration_days,
            'territory': terms.territory,
            'usage_rights': terms.usage_rights,
            'royalty_type': terms.royalty_type.value,
            'royalty_rate': str(terms.royalty_rate),
            'exclusivity': terms.exclusivity,
            'transferable': terms.transferable,
            'sublicensable': terms.sublicensable,
            'attribution_required': terms.attribution_required,
            'restrictions': terms.restrictions,
            'custom_terms': terms.custom_terms
        }
    
    def _verify_usage_rights(self, terms: LicenseTerms, usage_context: Dict[str, Any]) -> bool:
        """Verify if usage is allowed under license terms."""
        # Check commercial usage
        if 'commercial' in usage_context.get('usage_type', []):
            if 'commercial' not in terms.usage_rights:
                return False
        
        # Check territory
        if 'territory' in usage_context:
            usage_territory = usage_context['territory']
            if 'worldwide' not in terms.territory and usage_territory not in terms.territory:
                return False
        
        # Check restrictions
        for restriction in terms.restrictions:
            if restriction in usage_context.get('usage_type', []):
                return False
        
        return True
    
    async def _verify_license_on_blockchain(self, contract_address: str) -> bool:
        """Verify license exists and is valid on blockchain (simulated)."""
        # This would query the blockchain contract
        # For simulation, check if address looks valid
        if len(contract_address) == 42 and contract_address.startswith('0x'):
            return True
        return False
    
    def _calculate_usage_trend(self, license_id: str) -> str:
        """Calculate usage trend for analytics."""
        # This would analyze historical usage data
        # For now, return a simulated trend
        trends = ["increasing", "stable", "decreasing"]
        return trends[hash(license_id) % len(trends)]

# Example usage
async def main():
    """Example usage of ContentLicenseManager."""
    license_manager = ContentLicenseManager()
    
    # Register content
    content_data = b"This is sample audio content data..."
    fingerprint = await license_manager.register_content(
        content_data=content_data,
        content_type="audio",
        creator_id="creator_001",
        metadata={"title": "Sample Song", "genre": "Electronic"}
    )
    print(f"Content registered: {fingerprint.fingerprint_hash}")
    
    # Create license terms
    terms = LicenseTerms(
        license_type=LicenseType.NON_EXCLUSIVE,
        duration_days=365,
        territory=["US", "CA", "UK"],
        usage_rights=["commercial", "digital"],
        royalty_type=RoyaltyType.PERCENTAGE,
        royalty_rate=Decimal('5.0'),  # 5%
        exclusivity=False,
        transferable=True,
        sublicensable=False,
        attribution_required=True
    )
    
    # Create license
    license_record = await license_manager.create_license(
        content_fingerprint=fingerprint.fingerprint_hash,
        licensor_id="creator_001",
        licensee_id="user_002",
        terms=terms,
        license_fee=Decimal('100.00')
    )
    print(f"License created: {license_record.license_id}")
    
    # Execute payment
    payment_success = await license_manager.execute_license_payment(
        license_id=license_record.license_id,
        payment_tx_hash="tx_payment_123456"
    )
    print(f"Payment executed: {payment_success}")
    
    # Track usage
    await license_manager.track_content_usage(
        license_id=license_record.license_id,
        usage_context={
            'platform': 'youtube',
            'views': 10000,
            'revenue': 50.00,
            'usage_type': ['commercial'],
            'territory': 'US'
        }
    )
    print("Usage tracked")
    
    # Get analytics
    analytics = await license_manager.get_license_analytics(license_record.license_id)
    print(f"License analytics: {json.dumps(analytics, indent=2)}")

if __name__ == "__main__":
    asyncio.run(main())
