"""Crypto Price Oracle for Blockchain Consensus
===========================================

Provides real-time cryptocurrency price feeds for blockchain consensus,
staking rewards calculation, and content monetization.

Author: Fahed Mlaiel <mlaiel@live.de>
⚠️ STRICT COPYRIGHT WARNING - Unauthorized use prohibited ⚠️
"""
import asyncio
import logging
import aiohttp
from datetime import datetime, timedelta
from typing import Dict, List, Optional, Any
from decimal import Decimal
import json

logger = logging.getLogger(__name__)

class CryptoPriceOracle:
    """
    Advanced cryptocurrency price oracle with multiple data sources,
    reliability mechanisms, and real-time price feeds.
    """
    
    def __init__(self, config: Dict[str, Any] = None):
        self.config = config or {}
        self.price_cache = {}
        self.cache_duration = timedelta(minutes=5)  # Cache prices for 5 minutes
        self.data_sources = [
            'coingecko',
            'coinbase',
            'binance',
            'kraken'
        ]
        self.session = None
        
    async def __aenter__(self):
        self.session = aiohttp.ClientSession()
        return self
        
    async def __aexit__(self, exc_type, exc_val, exc_tb):
        if self.session:
            await self.session.close()
    
    async def get_price(self, symbol: str, vs_currency: str = 'usd') -> Optional[Decimal]:
        """
        Get current price for a cryptocurrency symbol.
        
        Args:
            symbol: Cryptocurrency symbol (e.g., 'bitcoin', 'ethereum')
            vs_currency: Base currency for price (default: 'usd')
            
        Returns:
            Current price as Decimal or None if unavailable
        """
        cache_key = f"{symbol}_{vs_currency}"
        
        # Check cache first
        if cache_key in self.price_cache:
            cached_data = self.price_cache[cache_key]
            if datetime.now() - cached_data['timestamp'] < self.cache_duration:
                return cached_data['price']
        
        # Fetch from multiple sources for reliability
        prices = []
        for source in self.data_sources:
            try:
                price = await self._fetch_from_source(source, symbol, vs_currency)
                if price:
                    prices.append(price)
                    logger.debug(f"Price from {source}: {symbol} = {price} {vs_currency}")
            except Exception as e:
                logger.warning(f"Failed to fetch price from {source}: {e}")
                continue
        
        if not prices:
            logger.error(f"No price data available for {symbol}")
            return None
            
        # Use median price for stability
        final_price = self._calculate_median_price(prices)
        
        # Cache the result
        self.price_cache[cache_key] = {
            'price': final_price,
            'timestamp': datetime.now(),
            'sources_count': len(prices)
        }
        
        logger.info(f"Oracle price for {symbol}: {final_price} {vs_currency} (from {len(prices)} sources)")
        return final_price
    
    async def get_historical_prices(self, symbol: str, days: int = 30, vs_currency: str = 'usd') -> List[Dict]:
        """
        Get historical price data for trend analysis and AI predictions.
        
        Args:
            symbol: Cryptocurrency symbol
            days: Number of days of historical data
            vs_currency: Base currency
            
        Returns:
            List of price data points with timestamps
        """
        try:
            # Use CoinGecko for historical data (most reliable)
            url = f"https://api.coingecko.com/api/v3/coins/{symbol}/market_chart"
            params = {
                'vs_currency': vs_currency,
                'days': days,
                'interval': 'daily' if days > 1 else 'hourly'
            }
            
            async with self.session.get(url, params=params) as response:
                if response.status == 200:
                    data = await response.json()
                    prices = data.get('prices', [])
                    
                    # Format data for analytics
                    formatted_prices = []
                    for timestamp, price in prices:
                        formatted_prices.append({
                            'timestamp': datetime.fromtimestamp(timestamp / 1000),
                            'price': Decimal(str(price)),
                            'symbol': symbol,
                            'vs_currency': vs_currency
                        })
                    
                    logger.info(f"Retrieved {len(formatted_prices)} historical prices for {symbol}")
                    return formatted_prices
                else:
                    logger.error(f"Failed to fetch historical data: HTTP {response.status}")
                    return []
                    
        except Exception as e:
            logger.error(f"Error fetching historical prices: {e}")
            return []
    
    async def _fetch_from_source(self, source: str, symbol: str, vs_currency: str) -> Optional[Decimal]:
        """Fetch price from specific data source."""
        
        if source == 'coingecko':
            return await self._fetch_coingecko(symbol, vs_currency)
        elif source == 'coinbase':
            return await self._fetch_coinbase(symbol, vs_currency)
        elif source == 'binance':
            return await self._fetch_binance(symbol, vs_currency)
        elif source == 'kraken':
            return await self._fetch_kraken(symbol, vs_currency)
        else:
            logger.warning(f"Unknown price source: {source}")
            return None
    
    async def _fetch_coingecko(self, symbol: str, vs_currency: str) -> Optional[Decimal]:
        """Fetch price from CoinGecko API."""
        try:
            url = "https://api.coingecko.com/api/v3/simple/price"
            params = {'ids': symbol, 'vs_currencies': vs_currency}
            
            async with self.session.get(url, params=params) as response:
                if response.status == 200:
                    data = await response.json()
                    price = data.get(symbol, {}).get(vs_currency)
                    return Decimal(str(price)) if price else None
                return None
        except Exception as e:
            logger.debug(f"CoinGecko fetch error: {e}")
            return None
    
    async def _fetch_coinbase(self, symbol: str, vs_currency: str) -> Optional[Decimal]:
        """Fetch price from Coinbase API."""
        try:
            # Convert symbol to Coinbase format
            symbol_upper = symbol.upper()
            if symbol_upper == 'BITCOIN':
                symbol_upper = 'BTC'
            elif symbol_upper == 'ETHEREUM':
                symbol_upper = 'ETH'
            
            url = f"https://api.coinbase.com/v2/exchange-rates?currency={symbol_upper}"
            
            async with self.session.get(url) as response:
                if response.status == 200:
                    data = await response.json()
                    rates = data.get('data', {}).get('rates', {})
                    price = rates.get(vs_currency.upper())
                    return Decimal(str(price)) if price else None
                return None
        except Exception as e:
            logger.debug(f"Coinbase fetch error: {e}")
            return None
    
    async def _fetch_binance(self, symbol: str, vs_currency: str) -> Optional[Decimal]:
        """Fetch price from Binance API."""
        try:
            # Convert to Binance symbol format
            if symbol.lower() == 'bitcoin':
                trading_pair = 'BTCUSDT'
            elif symbol.lower() == 'ethereum':
                trading_pair = 'ETHUSDT'
            else:
                # Generic conversion
                trading_pair = f"{symbol.upper()}USDT"
            
            url = f"https://api.binance.com/api/v3/ticker/price?symbol={trading_pair}"
            
            async with self.session.get(url) as response:
                if response.status == 200:
                    data = await response.json()
                    price = data.get('price')
                    return Decimal(str(price)) if price else None
                return None
        except Exception as e:
            logger.debug(f"Binance fetch error: {e}")
            return None
    
    async def _fetch_kraken(self, symbol: str, vs_currency: str) -> Optional[Decimal]:
        """Fetch price from Kraken API."""
        try:
            # Convert to Kraken symbol format
            if symbol.lower() == 'bitcoin':
                pair = 'XXBTZUSD'
            elif symbol.lower() == 'ethereum':
                pair = 'XETHZUSD'
            else:
                return None  # Skip unsupported symbols
            
            url = f"https://api.kraken.com/0/public/Ticker?pair={pair}"
            
            async with self.session.get(url) as response:
                if response.status == 200:
                    data = await response.json()
                    result = data.get('result', {})
                    ticker = result.get(pair, {})
                    price_data = ticker.get('c', [])  # Last trade closed
                    price = price_data[0] if price_data else None
                    return Decimal(str(price)) if price else None
                return None
        except Exception as e:
            logger.debug(f"Kraken fetch error: {e}")
            return None
    
    def _calculate_median_price(self, prices: List[Decimal]) -> Decimal:
        """Calculate median price from multiple sources."""
        if not prices:
            return Decimal('0')
        
        sorted_prices = sorted(prices)
        n = len(sorted_prices)
        
        if n % 2 == 0:
            # Even number of prices - average of middle two
            middle1 = sorted_prices[n // 2 - 1]
            middle2 = sorted_prices[n // 2]
            return (middle1 + middle2) / 2
        else:
            # Odd number of prices - middle value
            return sorted_prices[n // 2]
    
    async def validate_price_feed(self, symbol: str, expected_range: tuple = None) -> bool:
        """
        Validate price feed integrity and detect anomalies.
        
        Args:
            symbol: Cryptocurrency symbol to validate
            expected_range: Optional tuple (min_price, max_price) for validation
            
        Returns:
            True if price feed is valid, False otherwise
        """
        try:
            current_price = await self.get_price(symbol)
            if not current_price:
                logger.warning(f"No price available for validation: {symbol}")
                return False
            
            # Check if price is within expected range
            if expected_range:
                min_price, max_price = expected_range
                if not (Decimal(str(min_price)) <= current_price <= Decimal(str(max_price))):
                    logger.error(f"Price {current_price} outside expected range {expected_range} for {symbol}")
                    return False
            
            # Check for price stability (compare with cache)
            cache_key = f"{symbol}_usd"
            if cache_key in self.price_cache:
                cached_price = self.price_cache[cache_key]['price']
                price_change_percent = abs((current_price - cached_price) / cached_price * 100)
                
                # Alert if price changed more than 50% (likely error)
                if price_change_percent > 50:
                    logger.error(f"Extreme price change detected: {price_change_percent:.2f}% for {symbol}")
                    return False
            
            logger.info(f"Price feed validation passed for {symbol}: {current_price}")
            return True
            
        except Exception as e:
            logger.error(f"Price validation failed for {symbol}: {e}")
            return False

# Usage example for the consensus system
async def main():
    """Example usage of CryptoPriceOracle in consensus context."""
    async with CryptoPriceOracle() as oracle:
        # Get current ETH price for staking rewards calculation
        eth_price = await oracle.get_price('ethereum')
        print(f"Current ETH price: ${eth_price}")
        
        # Get historical data for AI prediction models
        historical_data = await oracle.get_historical_prices('ethereum', days=7)
        print(f"Retrieved {len(historical_data)} historical data points")
        
        # Validate price feed integrity
        is_valid = await oracle.validate_price_feed('ethereum', (1000, 10000))
        print(f"Price feed validation: {'PASSED' if is_valid else 'FAILED'}")

if __name__ == "__main__":
    asyncio.run(main())
