class LicenseType(Enum):
    """Types of content licenses."""
    EXCLUSIVE = "exclusive"
    NON_EXCLUSIVE = "non_exclusive"
    CREATIVE_COMMONS = "creative_commons"
    ROYALTY_FREE = "royalty_free"
    RIGHTS_MANAGED = "rights_managed"
    SUBSCRIPTION_BASED = "subscription_based"
    PAY_PER_USE = "pay_per_use"
    REVENUE_SHARING = "revenue_sharing"
    ATTRIBUTION_REQUIRED = "attribution_required"
    COMMERCIAL_USE = "commercial_use"
    PERSONAL_USE_ONLY = "personal_use_only"
    EDUCATIONAL_USE = "educational_use"
    PROMOTIONAL_USE = "promotional_use"
    DERIVATIVE_WORKS_ALLOWED = "derivative_works_allowed"
    RESALE_RIGHTS = "resale_rights"
    SYNDICATION_RIGHTS = "syndication_rights"
    BROADCAST_RIGHTS = "broadcast_rights"
    STREAMING_RIGHTS = "streaming_rights"
    PRINT_RIGHTS = "print_rights"
    DIGITAL_RIGHTS = "digital_rights"


class LicenseStatus(Enum):
    """Status of license agreements."""
    DRAFT = "draft"
    PENDING_APPROVAL = "pending_approval"
    ACTIVE = "active"
    SUSPENDED = "suspended"
    EXPIRED = "expired"
    TERMINATED = "terminated"
    RENEWED = "renewed"
    VIOLATED = "violated"
    DISPUTED = "disputed"
    RENEGOTIATING = "renegotiating"
    ARCHIVED = "archived"


class UsageType(Enum):
    """Types of content usage."""
    VIEW = "view"
    DOWNLOAD = "download"
    STREAM = "stream"
    SHARE = "share"
    EMBED = "embed"
    REMIX = "remix"
    DERIVATIVE_CREATION = "derivative_creation"
    COMMERCIAL_USE = "commercial_use"
    BROADCAST = "broadcast"
    PRINT = "print"
    MERCHANDISE = "merchandise"
    ADVERTISING = "advertising"
    EDUCATION = "education"
    RESEARCH = "research"
    PERSONAL_USE = "personal_use"


class ViolationType(Enum):
    """Types of license violations."""
    UNAUTHORIZED_USE = "unauthorized_use"
    EXCEEDED_USAGE_LIMITS = "exceeded_usage_limits"
    COMMERCIAL_USE_WITHOUT_LICENSE = "commercial_use_without_license"
    MISSING_ATTRIBUTION = "missing_attribution"
    GEOGRAPHIC_RESTRICTION_VIOLATION = "geographic_restriction_violation"
    TIME_RESTRICTION_VIOLATION = "time_restriction_violation"
    PLATFORM_RESTRICTION_VIOLATION = "platform_restriction_violation"
    DERIVATIVE_WORK_VIOLATION = "derivative_work_violation"
    RESALE_WITHOUT_RIGHTS = "resale_without_rights"
    SUBLICENSING_VIOLATION = "sublicensing_violation"
    PAYMENT_DEFAULT = "payment_default"
    USAGE_REPORTING_VIOLATION = "usage_reporting_violation"
    DRM_CIRCUMVENTION = "drm_circumvention"
    WATERMARK_REMOVAL = "watermark_removal"
    METADATA_TAMPERING = "metadata_tampering"


@dataclass
class ContentLicense:
    """Comprehensive content licensing agreement."""
    license_id: str
    content_id: str
    licensor_id: str  # Creator/Rights holder
    licensee_id: str  # User/Platform using content
    license_name: str
    license_type: LicenseType
    license_status: LicenseStatus
    created_at: datetime
    effective_date: datetime
    expiration_date: Optional[datetime]
    auto_renewal: bool
    renewal_period_days: Optional[int]
    notice_period_days: int
    termination_conditions: List[str]
    
    # Usage Rights
    usage_types_allowed: List[UsageType]
    usage_limitations: Dict[str, Any]
    geographic_restrictions: List[str]  # ISO country codes
    platform_restrictions: List[str]
    time_restrictions: Dict[str, Any]  # time-of-day, days-of-week restrictions
    audience_restrictions: Dict[str, Any]  # age, demographic restrictions
    quality_restrictions: Dict[str, Any]  # resolution, bitrate limits
    modification_rights: Dict[str, bool]  # crop, resize, filter permissions
    derivative_rights: Dict[str, bool]  # remix, sample, transform rights
    
    # Financial Terms
    license_fee: Decimal
    currency: str
    payment_schedule: str  # upfront, monthly, per-use, revenue-share
    revenue_share_percentage: Optional[Decimal]
    minimum_guarantee: Optional[Decimal]
    usage_based_pricing: Dict[UsageType, Decimal]
    volume_discounts: List[Dict[str, Any]]
    payment_terms_days: int
    late_payment_penalty_rate: Decimal
    
    # Attribution Requirements
    attribution_required: bool
    attribution_format: Optional[str]
    attribution_placement: Optional[str]
    copyright_notice_required: bool
    watermark_required: bool
    metadata_preservation_required: bool
    
    # Reporting and Monitoring
    usage_reporting_required: bool
    reporting_frequency: str  # real-time, daily, weekly, monthly
    reporting_format: str
    audit_rights: bool
    monitoring_tools_required: List[str]
    
    # Technical Requirements
    drm_required: bool
    drm_specifications: Optional[Dict[str, Any]]
    access_control_required: bool
    encryption_required: bool
    content_protection_level: str  # basic, standard, premium
    
    # Legal Terms
    governing_law: str
    jurisdiction: str
    dispute_resolution: str  # arbitration, mediation, court
    limitation_of_liability: Optional[str]
    indemnification_clause: Optional[str]
    force_majeure_clause: bool
    
    # Smart Contract Integration
    smart_contract_address: Optional[str]
    blockchain_network: Optional[str]
    contract_abi: Optional[str]
    automated_execution: bool
    escrow_required: bool
    multi_signature_required: bool
    
    # Performance Metrics
    usage_count: int
    revenue_generated: Decimal
    compliance_score: float  # 0.0-1.0
    violation_count: int
    last_usage_date: Optional[datetime]
    last_payment_date: Optional[datetime]
    next_payment_due: Optional[datetime]
    
    # Relationships
    parent_license_id: Optional[str]  # For sub-licenses
    child_license_ids: List[str]
    related_license_ids: List[str]
    superseded_by_license_id: Optional[str]
    
    # Additional Metadata
    license_category: str
    industry_vertical: str
    use_case_description: str
    negotiation_history: List[Dict[str, Any]]
    amendment_history: List[Dict[str, Any]]
    compliance_history: List[Dict[str, Any]]
    additional_terms: Dict[str, Any]


