logger = get_logger(__name__)
Base = declarative_base()


class FundingStatus(Enum):
    """Status of funding proposals."""
    DRAFT = "draft"
    SUBMITTED = "submitted"
    UNDER_REVIEW = "under_review"
    APPROVED = "approved"
    REJECTED = "rejected"
    FUNDED = "funded"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"
    CANCELLED = "cancelled"
    MILESTONE_REVIEW = "milestone_review"


class GrantType(Enum):
    """Types of grants available."""
    DEVELOPMENT_GRANT = "development_grant"
    RESEARCH_GRANT = "research_grant"
    COMMUNITY_GRANT = "community_grant"
    MARKETING_GRANT = "marketing_grant"
    INFRASTRUCTURE_GRANT = "infrastructure_grant"
    SECURITY_AUDIT = "security_audit"
    INTEGRATION_GRANT = "integration_grant"
    HACKATHON_PRIZE = "hackathon_prize"


class BudgetCategory(Enum):
    """Budget allocation categories."""
    DEVELOPMENT = "development"
    MARKETING = "marketing"
    OPERATIONS = "operations"
    SECURITY = "security"
    RESEARCH = "research"
    COMMUNITY = "community"
    INFRASTRUCTURE = "infrastructure"
    RESERVES = "reserves"


@dataclass
class Milestone:
    """Milestone for funded projects."""
    id: str
    title: str
    description: str
    completion_criteria: List[str]
    funding_amount: Decimal
    due_date: datetime
    status: str  # pending, in_progress, completed, failed
    deliverables: List[str]
    verification_method: str


@dataclass
class FundingDecision:
    """Treasury funding decision record."""
    proposal_id: str
    decision: str  # approved, rejected, conditional
    amount_approved: Decimal
    conditions: List[str]
    voting_results: Dict[str, Any]
    decision_date: datetime
    decision_rationale: str


class FundingProposalModel(Base):
    """SQLAlchemy model for funding proposals."""
    __tablename__ = "treasury_funding_proposals"
    
    id = Column(String, primary_key=True)
    title = Column(String(255), nullable=False)
    description = Column(Text, nullable=False)
    proposer_id = Column(String, nullable=False)
    grant_type = Column(String(50), nullable=False)
    status = Column(String(30), nullable=False, default="draft")
    
    # Financial details
    requested_amount = Column(DECIMAL(18, 8), nullable=False)
    currency = Column(String(10), nullable=False, default="SPOTIFY_TOKEN")
    approved_amount = Column(DECIMAL(18, 8))
    disbursed_amount = Column(DECIMAL(18, 8), default=0)
    
    # Project details
    project_duration_months = Column(Integer)
    team_members = Column(JSON)
    milestones = Column(JSON)
    deliverables = Column(JSON)
    success_metrics = Column(JSON)
    
    # Governance
    governance_proposal_id = Column(String)
    voting_results = Column(JSON)
    approval_date = Column(DateTime)
    funding_start_date = Column(DateTime)
    funding_end_date = Column(DateTime)
    
    # Tracking
    progress_reports = Column(JSON, default=list)
    milestone_completions = Column(JSON, default=list)
    budget_utilization = Column(JSON, default=dict)
    
    # Metadata
    created_at = Column(DateTime, default=datetime.utcnow)
    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    metadata = Column(JSON)


class BudgetAllocationModel(Base):
    """SQLAlchemy model for budget allocations."""
    __tablename__ = "treasury_budget_allocations"
    
    id = Column(String, primary_key=True)
