class ReputationBasedVoting(VotingSystemInterface):
    """Reputation-weighted voting system."""
    
    def __init__(
        self, 
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        
    async def calculate_voting_power(self, user_id: str, proposal_id: str) -> VotingPower:
        """Calculate reputation-based voting power."""
        try:
            # Get user's reputation score
            reputation_score = await self._get_user_reputation(user_id)
            
            # Get category-specific expertise
            proposal_category = await self._get_proposal_category(proposal_id)
            expertise_multiplier = await self._get_expertise_multiplier(user_id, proposal_category)
            
            # Get contribution history weight
            contribution_weight = await self._get_contribution_weight(user_id)
            
            # Calculate adjusted power
            base_power = reputation_score
            expertise_power = base_power * expertise_multiplier
            total_power = expertise_power + contribution_weight
            
            return VotingPower(
                user_id=user_id,
                total_power=total_power,
                token_power=0.0,
                reputation_power=base_power,
                delegated_power=0.0,
                stake_multiplier=expertise_multiplier,
                participation_bonus=contribution_weight,
                calculated_at=datetime.utcnow()
            )
            
        except Exception as e:
            logger.error(f"Failed to calculate reputation voting power for {user_id}: {str(e)}")
            return VotingPower(
                user_id=user_id,
                total_power=0.0,
                token_power=0.0,
                reputation_power=0.0,
                delegated_power=0.0,
                stake_multiplier=1.0,
                participation_bonus=0.0,
                calculated_at=datetime.utcnow()
            )
    
    async def cast_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType,
        signature: str
    ) -> Dict[str, Any]:
        """Cast a reputation-weighted vote."""  
        # Similar implementation to token-based but using reputation
        return await self._cast_reputation_vote(user_id, proposal_id, vote_type, signature)
    
    async def validate_vote(
        self, 
        user_id: str, 
        proposal_id: str, 
        vote_type: VoteType
    ) -> Tuple[bool, List[str]]:
        """Validate reputation-based vote."""
        errors = []
        
        # Check minimum reputation requirement
        reputation = await self._get_user_reputation(user_id)
        if reputation < 50:
            errors.append("User does not meet minimum reputation requirement")
        
        # Other standard validations
        standard_errors = await self._standard_vote_validation(user_id, proposal_id)
        errors.extend(standard_errors)
        
        return len(errors) == 0, errors
    
    async def _get_user_reputation(self, user_id: str) -> float:
        """Get user's reputation score."""
