class VotingMetricsAnalyzer:
    """Analyzes voting patterns and metrics."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager
    ):
        self.db = db_connection
        self.cache = cache_manager
    
    async def analyze_voting_patterns(
        self,
        proposal_id: Optional[str] = None,
        time_frame: Optional[TimeFrame] = None,
        start_date: Optional[datetime] = None,
        end_date: Optional[datetime] = None
    ) -> VotingMetrics:
        """Analyze voting patterns for proposals."""
        try:
            # Get voting data
            voting_data = await self._get_voting_data(
                proposal_id, time_frame, start_date, end_date
            )
            
            if not voting_data:
                return VotingMetrics(
                    total_votes=0,
                    unique_voters=0,
                    average_voting_power=0.0,
                    power_distribution={},
                    participation_rate=0.0,
                    consensus_strength=0.0,
                    polarization_index=0.0,
                    time_to_consensus=None
                )
            
            # Calculate metrics
            total_votes = len(voting_data)
            unique_voters = len(set(vote['voter_id'] for vote in voting_data))
            
            # Calculate voting power metrics
            voting_powers = [vote['voting_power'] for vote in voting_data]
            average_voting_power = statistics.mean(voting_powers) if voting_powers else 0.0
            
            # Power distribution analysis
            power_distribution = await self._analyze_power_distribution(voting_data)
            
            # Participation rate (would need total eligible voters)
            total_eligible = await self._get_total_eligible_voters()
            participation_rate = unique_voters / max(total_eligible, 1)
            
            # Consensus strength
            consensus_strength = await self._calculate_consensus_strength(voting_data)
            
            # Polarization index
            polarization_index = await self._calculate_polarization(voting_data)
            
            # Time to consensus
            time_to_consensus = await self._calculate_time_to_consensus(voting_data)
            
            return VotingMetrics(
                total_votes=total_votes,
                unique_voters=unique_voters,
                average_voting_power=average_voting_power,
                power_distribution=power_distribution,
                participation_rate=participation_rate,
                consensus_strength=consensus_strength,
                polarization_index=polarization_index,
                time_to_consensus=time_to_consensus
            )
            
        except Exception as e:
            logger.error(f"Failed to analyze voting patterns: {str(e)}")
            return VotingMetrics(
                total_votes=0,
                unique_voters=0,
                average_voting_power=0.0,
                power_distribution={},
                participation_rate=0.0,
                consensus_strength=0.0,
                polarization_index=0.0,
                time_to_consensus=None
            )
    
    async def analyze_voter_behavior(
        self,
        voter_id: str,
        analysis_period_days: int = 90
    ) -> Dict[str, Any]:
        """Analyze individual voter behavior patterns."""
        try:
            end_date = datetime.utcnow()
            start_date = end_date - timedelta(days=analysis_period_days)
            
            # Get voter's voting history
            voter_history = await self._get_voter_history(voter_id, start_date, end_date)
            
            if not voter_history:
                return {
                    'voter_id': voter_id,
                    'analysis_period_days': analysis_period_days,
                    'voting_frequency': 0.0,
                    'average_response_time': None,
                    'voting_consistency': 0.0,
                    'power_usage_pattern': {},
                    'topic_preferences': {},
                    'alignment_with_majority': 0.0
                }
            
            # Calculate behavior metrics
            voting_frequency = len(voter_history) / analysis_period_days * 30  # Per month
            
            # Response time analysis
            response_times = []
            for vote in voter_history:
                if vote.get('proposal_start_time') and vote.get('vote_timestamp'):
                    response_time = (
                        datetime.fromisoformat(vote['vote_timestamp']) - 
                        datetime.fromisoformat(vote['proposal_start_time'])
                    ).total_seconds() / 3600  # Hours
                    response_times.append(response_time)
            
            average_response_time = statistics.mean(response_times) if response_times else None
            
            # Voting consistency
            consistency = await self._calculate_voting_consistency(voter_history)
            
            # Power usage pattern
            power_usage = await self._analyze_power_usage_pattern(voter_history)
            
            # Topic preferences
            topic_preferences = await self._analyze_topic_preferences(voter_history)
            
            # Alignment with majority
            majority_alignment = await self._calculate_majority_alignment(voter_history)
            
            return {
                'voter_id': voter_id,
                'analysis_period_days': analysis_period_days,
                'total_votes_cast': len(voter_history),
                'voting_frequency': voting_frequency,
                'average_response_time_hours': average_response_time,
                'voting_consistency': consistency,
                'power_usage_pattern': power_usage,
                'topic_preferences': topic_preferences,
                'alignment_with_majority': majority_alignment,
                'analyzed_at': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to analyze voter behavior: {str(e)}")
            return {}
    
    async def _get_voting_data(
        self,
        proposal_id: Optional[str],
        time_frame: Optional[TimeFrame],
        start_date: Optional[datetime],
        end_date: Optional[datetime]
    ) -> List[Dict[str, Any]]:
        """Get voting data for analysis."""
        # This would query the votes table
        # For now, return mock data
        return [
            {
                'voter_id': f'voter_{i}',
                'vote_type': 'for' if i % 3 != 0 else 'against',
                'voting_power': 100 + i * 10,
                'timestamp': datetime.utcnow() - timedelta(hours=i)
            }
            for i in range(50)
        ]
    
    async def _analyze_power_distribution(
        self, 
        voting_data: List[Dict[str, Any]]
    ) -> Dict[str, float]:
        """Analyze distribution of voting power."""
        powers = [vote['voting_power'] for vote in voting_data]
        if not powers:
            return {}
        
        powers_array = np.array(powers)
        
        return {
            'gini_coefficient': self._calculate_gini_coefficient(powers_array),
            'top_1_percent_power': float(np.percentile(powers_array, 99)),
            'top_10_percent_power': float(np.percentile(powers_array, 90)),
            'median_power': float(np.median(powers_array)),
            'power_concentration_ratio': float(np.sum(powers_array[-5:]) / np.sum(powers_array))
        }
    
    def _calculate_gini_coefficient(self, powers: np.ndarray) -> float:
        """Calculate Gini coefficient for power distribution."""
        if len(powers) == 0:
            return 0.0
        
        # Sort powers
        sorted_powers = np.sort(powers)
        n = len(sorted_powers)
        
        # Calculate Gini coefficient
        index = np.arange(1, n + 1)
        gini = (2 * np.sum(index * sorted_powers)) / (n * np.sum(sorted_powers)) - (n + 1) / n
        
        return float(gini)
    
    async def _get_total_eligible_voters(self) -> int:
        """Get total number of eligible voters."""
        # This would query user database for eligible voters
        return 1000  # Mock data
    
    async def _calculate_consensus_strength(
        self, 
        voting_data: List[Dict[str, Any]]
    ) -> float:
        """Calculate consensus strength based on vote distribution."""
        if not voting_data:
            return 0.0
        
        # Group by vote type and sum voting power
        vote_power_by_type = defaultdict(float)
        for vote in voting_data:
            vote_power_by_type[vote['vote_type']] += vote['voting_power']
        
        total_power = sum(vote_power_by_type.values())
        if total_power == 0:
            return 0.0
        
        # Calculate consensus as the proportion of the winning side
        max_power = max(vote_power_by_type.values())
        consensus_strength = max_power / total_power
        
        return consensus_strength
    
    async def _calculate_polarization(
        self, 
        voting_data: List[Dict[str, Any]]
    ) -> float:
        """Calculate polarization index."""
        if not voting_data:
            return 0.0
        
        # Count votes by type
        vote_counts = defaultdict(int)
        for vote in voting_data:
            vote_counts[vote['vote_type']] += 1
        
        total_votes = len(voting_data)
        
        # Calculate polarization (higher when votes are split)
        if len(vote_counts) <= 1:
            return 0.0
        
        # Calculate entropy as polarization measure
        polarization = 0.0
        for count in vote_counts.values():
            if count > 0:
                p = count / total_votes
                polarization -= p * np.log2(p)
        
        # Normalize to 0-1 range
        max_polarization = np.log2(len(vote_counts))
        return polarization / max_polarization if max_polarization > 0 else 0.0
    
    async def _calculate_time_to_consensus(
        self, 
        voting_data: List[Dict[str, Any]]
    ) -> Optional[float]:
        """Calculate time to reach consensus."""
        if not voting_data:
            return None
        
        # Sort by timestamp
        sorted_votes = sorted(voting_data, key=lambda x: x['timestamp'])
        
        # Find when consensus (>60% of final result) was reached
        final_consensus = await self._calculate_consensus_strength(voting_data)
        
        running_total = 0
        running_votes = []
        
        for vote in sorted_votes:
            running_votes.append(vote)
            current_consensus = await self._calculate_consensus_strength(running_votes)
            
            if current_consensus >= final_consensus * 0.9:  # 90% of final consensus
                time_to_consensus = (vote['timestamp'] - sorted_votes[0]['timestamp']).total_seconds() / 3600
                return time_to_consensus
        
        return None
    
    async def _get_voter_history(
        self, 
        voter_id: str, 
        start_date: datetime, 
        end_date: datetime
    ) -> List[Dict[str, Any]]:
        """Get voter's voting history."""
        # Mock implementation
        return [
            {
                'proposal_id': f'prop_{i}',
                'vote_type': 'for' if i % 2 == 0 else 'against',
                'voting_power': 100,
                'vote_timestamp': (datetime.utcnow() - timedelta(days=i)).isoformat(),
                'proposal_start_time': (datetime.utcnow() - timedelta(days=i+1)).isoformat(),
                'proposal_category': 'technical' if i % 3 == 0 else 'treasury'
            }
            for i in range(10)
        ]
    
    async def _calculate_voting_consistency(
        self, 
        voter_history: List[Dict[str, Any]]
    ) -> float:
        """Calculate voting consistency score."""
        if len(voter_history) < 2:
            return 1.0
        
        # Calculate consistency based on topic alignment
        topic_votes = defaultdict(list)
        for vote in voter_history:
            topic = vote.get('proposal_category', 'general')
            topic_votes[topic].append(vote['vote_type'])
        
        consistency_scores = []
        for topic, votes in topic_votes.items():
            if len(votes) > 1:
                # Calculate consistency within topic
                most_common_vote = max(set(votes), key=votes.count)
                consistency = votes.count(most_common_vote) / len(votes)
                consistency_scores.append(consistency)
        
        return statistics.mean(consistency_scores) if consistency_scores else 1.0
    
    async def _analyze_power_usage_pattern(
        self, 
        voter_history: List[Dict[str, Any]]
    ) -> Dict[str, Any]:
        """Analyze how voter uses their voting power."""
        powers = [vote['voting_power'] for vote in voter_history]
        
        if not powers:
            return {}
        
        return {
            'average_power_used': statistics.mean(powers),
            'power_variation': statistics.stdev(powers) if len(powers) > 1 else 0.0,
            'power_usage_trend': 'increasing' if powers[-1] > powers[0] else 'decreasing'
        }
    
    async def _analyze_topic_preferences(
        self, 
        voter_history: List[Dict[str, Any]]
    ) -> Dict[str, Any]:
        """Analyze voter's topic preferences."""
        topic_participation = defaultdict(int)
        topic_support = defaultdict(list)
        
        for vote in voter_history:
            topic = vote.get('proposal_category', 'general')
            topic_participation[topic] += 1
            topic_support[topic].append(1 if vote['vote_type'] == 'for' else 0)
        
        preferences = {}
        for topic, count in topic_participation.items():
            support_rate = statistics.mean(topic_support[topic])
            preferences[topic] = {
                'participation_count': count,
                'support_rate': support_rate
            }
        
        return preferences
    
    async def _calculate_majority_alignment(
        self, 
        voter_history: List[Dict[str, Any]]
    ) -> float:
        """Calculate alignment with majority decisions."""
        # This would require knowing the final outcomes
        # Mock implementation
        return 0.75


