    async def _get_participation_data(
        self, 
        time_frame: TimeFrame, 
        periods: int
    ) -> List[Dict[str, Any]]:
        """Get participation data for specified periods."""
        # Mock implementation
        return [
            {
                'period': i,
                'total_participants': 100 + i * 5,
                'active_participants': 80 + i * 3,
                'new_participants': 10 + i,
                'proposals_count': 5 + i // 2,
                'votes_count': 200 + i * 10,
                'engagement_score': 0.7 + (i % 3) * 0.1
            }
            for i in range(periods)
        ]
    
    async def _calculate_participation_trend(
        self, 
        participation_data: List[Dict[str, Any]]
    ) -> Dict[str, Any]:
        """Calculate participation trend analysis."""
        if len(participation_data) < 2:
            return {'trend': 'insufficient_data'}
        
        participants = [d['total_participants'] for d in participation_data]
        
        # Calculate linear trend
        x = np.arange(len(participants))
        slope, intercept = np.polyfit(x, participants, 1)
        
        # Calculate percentage change
        start_participants = participants[0]
        end_participants = participants[-1]
        percentage_change = ((end_participants - start_participants) / start_participants) * 100
        
        return {
            'trend_direction': 'increasing' if slope > 0 else 'decreasing' if slope < 0 else 'stable',
            'slope': float(slope),
            'percentage_change': percentage_change,
            'trend_strength': abs(slope) / max(participants) if max(participants) > 0 else 0
        }
    
    async def _calculate_engagement_trend(
        self, 
        participation_data: List[Dict[str, Any]]
    ) -> Dict[str, Any]:
        """Calculate engagement quality trend."""
        engagement_scores = [d.get('engagement_score', 0) for d in participation_data]
        
        if len(engagement_scores) < 2:
            return {'trend': 'insufficient_data'}
        
        x = np.arange(len(engagement_scores))
        slope, _ = np.polyfit(x, engagement_scores, 1)
        
        return {
            'engagement_trend': 'improving' if slope > 0 else 'declining' if slope < 0 else 'stable',
            'trend_magnitude': abs(slope),
            'current_engagement': engagement_scores[-1],
            'average_engagement': statistics.mean(engagement_scores)
        }
    
    async def _calculate_new_participant_trend(
        self, 
        participation_data: List[Dict[str, Any]]
    ) -> Dict[str, Any]:
        """Calculate new participant acquisition trend."""
        new_participants = [d.get('new_participants', 0) for d in participation_data]
        
        if not new_participants:
            return {'trend': 'no_data'}
        
        return {
            'average_new_participants': statistics.mean(new_participants),
            'acquisition_trend': 'increasing' if new_participants[-1] > new_participants[0] else 'decreasing',
            'acquisition_volatility': statistics.stdev(new_participants) if len(new_participants) > 1 else 0
        }
    
