import asyncio
import json
from abc import ABC, abstractmethod
from datetime import datetime, timedelta
from enum import Enum
from typing import Dict, List, Optional, Union, Any, Callable
from dataclasses import dataclass
from uuid import uuid4

from pydantic import BaseModel, Field
from sqlalchemy import Column, String, DateTime, Integer, Float, Boolean, JSON, Text
from sqlalchemy.ext.declarative import declarative_base

from ....core.database import DatabaseConnection
from ....core.cache import CacheManager
from ....core.security import SecurityManager
from ....utils.logger import get_logger
from ....integrations.smart_contracts import SmartContractManager
from ....integrations.treasury import TreasuryManager
from .proposal_manager import ProposalType, ProposalStatus

logger = get_logger(__name__)
Base = declarative_base()


class ExecutionStatus(Enum):
    """Status of governance execution."""
    PENDING = "pending"
    SCHEDULED = "scheduled"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"
    FAILED = "failed"
    ROLLED_BACK = "rolled_back"
    CANCELLED = "cancelled"
    TIMELOCKED = "timelocked"
    AWAITING_MULTISIG = "awaiting_multisig"


class ExecutionType(Enum):
    """Types of execution mechanisms."""
    AUTOMATED = "automated"
    MANUAL = "manual"
    TIMELOCK = "timelock"
    MULTISIG = "multisig"
    HYBRID = "hybrid"


@dataclass
class ExecutionResult:
    """Result of an execution attempt."""
    success: bool
    execution_id: str
    transaction_hash: Optional[str]
    gas_used: Optional[int]
    error_message: Optional[str]
    execution_time: datetime
    rollback_data: Optional[Dict[str, Any]]


class ExecutionModel(Base):
    """SQLAlchemy model for execution records."""
    __tablename__ = "governance_executions"
    
    id = Column(String, primary_key=True)
    proposal_id = Column(String, nullable=False)
    execution_type = Column(String(20), nullable=False)
    status = Column(String(20), nullable=False, default="pending")
    scheduled_time = Column(DateTime)
    started_at = Column(DateTime)
    completed_at = Column(DateTime)
    executor_id = Column(String)
    transaction_hash = Column(String)
    gas_used = Column(Integer)
    execution_data = Column(JSON)
    result_data = Column(JSON)
    error_message = Column(Text)
    rollback_data = Column(JSON)
    signatures_required = Column(Integer, default=1)
    signatures_collected = Column(JSON, default=list)
    timelock_expires = Column(DateTime)
    created_at = Column(DateTime, default=datetime.utcnow)
    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)


class ExecutionInterface(ABC):
    """Abstract interface for execution mechanisms."""
    
    @abstractmethod
    async def execute(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any],
        executor_id: str
    ) -> ExecutionResult:
        """Execute the proposal."""
        pass
    
    @abstractmethod
    async def validate_execution(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any]
    ) -> tuple[bool, List[str]]:
        """Validate execution parameters."""
        pass
    
    @abstractmethod
    async def rollback(self, execution_id: str) -> bool:
        """Rollback a failed execution."""
        pass


class AutomatedExecution(ExecutionInterface):
    """Automated execution for simple proposals."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager,
        smart_contract_manager: SmartContractManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        self.contracts = smart_contract_manager
        
    async def execute(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any],
        executor_id: str
    ) -> ExecutionResult:
        """Execute proposal automatically."""
        execution_id = str(uuid4())
        start_time = datetime.utcnow()
        
        try:
            logger.info(f"Starting automated execution {execution_id} for proposal {proposal_id}")
            
            # Create execution record
            execution = ExecutionModel(
                id=execution_id,
                proposal_id=proposal_id,
                execution_type=ExecutionType.AUTOMATED.value,
                status=ExecutionStatus.IN_PROGRESS.value,
                started_at=start_time,
                executor_id=executor_id,
                execution_data=execution_data
            )
            
            async with self.db.session() as session:
                session.add(execution)
                await session.commit()
            
            # Execute based on proposal type
            proposal_type = execution_data.get('proposal_type')
            result = await self._execute_by_type(proposal_type, execution_data)
            
            # Update execution record
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                execution.status = ExecutionStatus.COMPLETED.value if result.success else ExecutionStatus.FAILED.value
                execution.completed_at = datetime.utcnow()
                execution.transaction_hash = result.transaction_hash
                execution.gas_used = result.gas_used
                execution.result_data = {
                    'success': result.success,
                    'execution_time_seconds': (datetime.utcnow() - start_time).total_seconds()
                }
                if not result.success:
                    execution.error_message = result.error_message
                
                await session.commit()
            
            logger.info(f"Automated execution {execution_id} completed: {result.success}")
            
            return ExecutionResult(
                success=result.success,
                execution_id=execution_id,
                transaction_hash=result.transaction_hash,
                gas_used=result.gas_used,
                error_message=result.error_message,
                execution_time=datetime.utcnow(),
                rollback_data=result.rollback_data
            )
            
        except Exception as e:
            logger.error(f"Automated execution {execution_id} failed: {str(e)}")
            
            # Update execution record with error
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                execution.status = ExecutionStatus.FAILED.value
                execution.completed_at = datetime.utcnow()
                execution.error_message = str(e)
                await session.commit()
            
            return ExecutionResult(
                success=False,
                execution_id=execution_id,
                transaction_hash=None,
                gas_used=None,
                error_message=str(e),
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
    
    async def validate_execution(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any]
    ) -> tuple[bool, List[str]]:
        """Validate automated execution parameters."""
        errors = []
        
        # Check if proposal exists and is approved
        proposal_status = await self._get_proposal_status(proposal_id)
        if proposal_status != ProposalStatus.VOTING_PASSED.value:
            errors.append("Proposal is not approved for execution")
        
        # Validate execution data structure
        required_fields = ['proposal_type', 'parameters']
        for field in required_fields:
            if field not in execution_data:
                errors.append(f"Missing required field: {field}")
        
        # Type-specific validation
        proposal_type = execution_data.get('proposal_type')
        type_errors = await self._validate_type_specific(proposal_type, execution_data)
        errors.extend(type_errors)
        
        return len(errors) == 0, errors
    
    async def rollback(self, execution_id: str) -> bool:
        """Rollback automated execution."""
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution:
                    return False
                
                if not execution.rollback_data:
                    logger.warning(f"No rollback data available for execution {execution_id}")
                    return False
                
                # Perform rollback based on execution type
                rollback_success = await self._perform_rollback(execution.rollback_data)
                
                if rollback_success:
                    execution.status = ExecutionStatus.ROLLED_BACK.value
                    execution.updated_at = datetime.utcnow()
                    await session.commit()
                
                return rollback_success
                
        except Exception as e:
            logger.error(f"Failed to rollback execution {execution_id}: {str(e)}")
            return False
    
    async def _execute_by_type(
        self, 
        proposal_type: str, 
        execution_data: Dict[str, Any]
    ) -> ExecutionResult:
        """Execute based on proposal type."""
        if proposal_type == ProposalType.PARAMETER_CHANGE.value:
            return await self._execute_parameter_change(execution_data)
        elif proposal_type == ProposalType.TREASURY_ALLOCATION.value:
            return await self._execute_treasury_allocation(execution_data)
        elif proposal_type == ProposalType.PROTOCOL_UPGRADE.value:
            return await self._execute_protocol_upgrade(execution_data)
        else:
            raise ValueError(f"Unsupported proposal type for automated execution: {proposal_type}")
    
    async def _execute_parameter_change(self, execution_data: Dict[str, Any]) -> ExecutionResult:
        """Execute parameter change proposal."""
        try:
            parameters = execution_data['parameters']
            contract_address = parameters['contract_address']
            method_name = parameters['method_name']
            new_value = parameters['new_value']
            
            # Call smart contract method
            tx_hash = await self.contracts.call_contract_method(
                contract_address,
                method_name,
                [new_value]
            )
            
            return ExecutionResult(
                success=True,
                execution_id="",
                transaction_hash=tx_hash,
                gas_used=150000,
                error_message=None,
                execution_time=datetime.utcnow(),
                rollback_data={
                    'type': 'parameter_change',
                    'contract_address': contract_address,
                    'method_name': parameters.get('rollback_method', f'revert_{method_name}'),
                    'original_value': parameters.get('original_value')
                }
            )
            
        except Exception as e:
            return ExecutionResult(
                success=False,
                execution_id="",
                transaction_hash=None,
                gas_used=None,
                error_message=str(e),
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
    
    async def _execute_treasury_allocation(self, execution_data: Dict[str, Any]) -> ExecutionResult:
        """Execute treasury allocation proposal."""
        try:
            parameters = execution_data['parameters']
            recipient = parameters['recipient']
            amount = parameters['amount']
            currency = parameters['currency']
            
            # Use treasury manager to transfer funds
            treasury = TreasuryManager()
            tx_hash = await treasury.transfer_funds(recipient, amount, currency)
            
            return ExecutionResult(
                success=True,
                execution_id="",
                transaction_hash=tx_hash,
                gas_used=100000,
                error_message=None,
                execution_time=datetime.utcnow(),
                rollback_data={
                    'type': 'treasury_allocation',
                    'recipient': recipient,
                    'amount': amount,
                    'currency': currency,
                    'reverse_transfer': True
                }
            )
            
        except Exception as e:
            return ExecutionResult(
                success=False,
                execution_id="",
                transaction_hash=None,
                gas_used=None,
                error_message=str(e),
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
    
    async def _execute_protocol_upgrade(self, execution_data: Dict[str, Any]) -> ExecutionResult:
        """Execute protocol upgrade proposal."""
        try:
            parameters = execution_data['parameters']
            contract_address = parameters['contract_address']
            upgrade_data = parameters['upgrade_data']
            
            # Call upgrade function on smart contract
            tx_hash = await self.contracts.upgrade_contract(contract_address, upgrade_data)
            
            return ExecutionResult(
                success=True,
                execution_id="",
                transaction_hash=tx_hash,
                gas_used=500000,
                error_message=None,
                execution_time=datetime.utcnow(),
                rollback_data={
                    'type': 'protocol_upgrade',
                    'contract_address': contract_address,
                    'previous_version': parameters.get('previous_version'),
                    'rollback_data': parameters.get('rollback_data')
                }
            )
            
        except Exception as e:
            return ExecutionResult(
                success=False,
                execution_id="",
                transaction_hash=None,
                gas_used=None,
                error_message=str(e),
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
    
    async def _get_proposal_status(self, proposal_id: str) -> str:
        """Get proposal status."""
        # This would integrate with proposal manager
        return ProposalStatus.VOTING_PASSED.value
    
    async def _validate_type_specific(
        self, 
        proposal_type: str, 
        execution_data: Dict[str, Any]
    ) -> List[str]:
        """Validate type-specific execution data."""
        errors = []
        
        if proposal_type == ProposalType.PARAMETER_CHANGE.value:
            required = ['contract_address', 'method_name', 'new_value']
            parameters = execution_data.get('parameters', {})
            for field in required:
                if field not in parameters:
                    errors.append(f"Missing parameter: {field}")
        
        elif proposal_type == ProposalType.TREASURY_ALLOCATION.value:
            required = ['recipient', 'amount', 'currency']
            parameters = execution_data.get('parameters', {})
            for field in required:
                if field not in parameters:
                    errors.append(f"Missing parameter: {field}")
        
        return errors
    
    async def _perform_rollback(self, rollback_data: Dict[str, Any]) -> bool:
        """Perform rollback operation."""
        try:
            rollback_type = rollback_data.get('type')
            
            if rollback_type == 'parameter_change':
                return await self._rollback_parameter_change(rollback_data)
            elif rollback_type == 'treasury_allocation':
                return await self._rollback_treasury_allocation(rollback_data)
            elif rollback_type == 'protocol_upgrade':
                return await self._rollback_protocol_upgrade(rollback_data)
            
            return False
            
        except Exception as e:
            logger.error(f"Rollback failed: {str(e)}")
            return False
    
    async def _rollback_parameter_change(self, rollback_data: Dict[str, Any]) -> bool:
        """Rollback parameter change."""
        try:
            contract_address = rollback_data['contract_address']
            method_name = rollback_data['method_name']
            original_value = rollback_data['original_value']
            
            await self.contracts.call_contract_method(
                contract_address,
                method_name,
                [original_value]
            )
            
            return True
            
        except Exception as e:
            logger.error(f"Parameter change rollback failed: {str(e)}")
            return False
    
    async def _rollback_treasury_allocation(self, rollback_data: Dict[str, Any]) -> bool:
        """Rollback treasury allocation."""
        try:
            recipient = rollback_data['recipient']
            amount = rollback_data['amount']
            currency = rollback_data['currency']
            
            # Reverse the transfer (this would need proper implementation)
            treasury = TreasuryManager()
            await treasury.reverse_transfer(recipient, amount, currency)
            
            return True
            
        except Exception as e:
            logger.error(f"Treasury allocation rollback failed: {str(e)}")
            return False
    
    async def _rollback_protocol_upgrade(self, rollback_data: Dict[str, Any]) -> bool:
        """Rollback protocol upgrade."""
        try:
            contract_address = rollback_data['contract_address']
            previous_version = rollback_data['previous_version']
            
            await self.contracts.rollback_upgrade(contract_address, previous_version)
            
            return True
            
        except Exception as e:
            logger.error(f"Protocol upgrade rollback failed: {str(e)}")
            return False


class ManualExecution(ExecutionInterface):
    """Manual execution for complex proposals requiring human intervention."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        
    async def execute(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any],
        executor_id: str
    ) -> ExecutionResult:
        """Queue proposal for manual execution."""
        execution_id = str(uuid4())
        
        try:
            # Create execution record in pending state
            execution = ExecutionModel(
                id=execution_id,
                proposal_id=proposal_id,
                execution_type=ExecutionType.MANUAL.value,
                status=ExecutionStatus.PENDING.value,
                executor_id=executor_id,
                execution_data=execution_data,
                created_at=datetime.utcnow()
            )
            
            async with self.db.session() as session:
                session.add(execution)
                await session.commit()
            
            # Notify administrators
            await self._notify_administrators(proposal_id, execution_id)
            
            logger.info(f"Manual execution {execution_id} queued for proposal {proposal_id}")
            
            return ExecutionResult(
                success=True,
                execution_id=execution_id,
                transaction_hash=None,
                gas_used=None,
                error_message=None,
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
            
        except Exception as e:
            logger.error(f"Failed to queue manual execution: {str(e)}")
            return ExecutionResult(
                success=False,
                execution_id=execution_id,
                transaction_hash=None,
                gas_used=None,
                error_message=str(e),
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
    
    async def validate_execution(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any]
    ) -> tuple[bool, List[str]]:
        """Validate manual execution parameters."""
        errors = []
        
        # Basic validation for manual execution
        if not execution_data.get('instructions'):
            errors.append("Manual execution requires detailed instructions")
        
        if not execution_data.get('assigned_admin'):
            errors.append("Manual execution requires assigned administrator")
        
        return len(errors) == 0, errors
    
    async def rollback(self, execution_id: str) -> bool:
        """Rollback manual execution."""
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution:
                    return False
                
                execution.status = ExecutionStatus.CANCELLED.value
                execution.updated_at = datetime.utcnow()
                await session.commit()
                
                return True
                
        except Exception as e:
            logger.error(f"Failed to rollback manual execution {execution_id}: {str(e)}")
            return False
    
    async def complete_manual_execution(
        self, 
        execution_id: str, 
        admin_id: str,
        result_data: Dict[str, Any]
    ) -> bool:
        """Complete a manual execution."""
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution:
                    return False
                
                execution.status = ExecutionStatus.COMPLETED.value
                execution.completed_at = datetime.utcnow()
                execution.result_data = result_data
                execution.executor_id = admin_id
                await session.commit()
                
                logger.info(f"Manual execution {execution_id} completed by {admin_id}")
                return True
                
        except Exception as e:
            logger.error(f"Failed to complete manual execution: {str(e)}")
            return False
    
    async def _notify_administrators(self, proposal_id: str, execution_id: str):
        """Notify administrators of pending manual execution."""
        notification_data = {
            'type': 'manual_execution_required',
            'proposal_id': proposal_id,
            'execution_id': execution_id,
            'timestamp': datetime.utcnow().isoformat()
        }
        
        await self.cache.publish('admin_notifications', json.dumps(notification_data))


class TimelockExecution(ExecutionInterface):
    """Timelock execution with delay period for critical changes."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager,
        automated_executor: AutomatedExecution
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        self.automated_executor = automated_executor
        
    async def execute(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any],
        executor_id: str
    ) -> ExecutionResult:
        """Schedule execution with timelock delay."""
        execution_id = str(uuid4())
        
        try:
            # Calculate timelock expiry
            delay_hours = execution_data.get('timelock_delay_hours', 24)
            timelock_expires = datetime.utcnow() + timedelta(hours=delay_hours)
            
            # Create timelocked execution record
            execution = ExecutionModel(
                id=execution_id,
                proposal_id=proposal_id,
                execution_type=ExecutionType.TIMELOCK.value,
                status=ExecutionStatus.TIMELOCKED.value,
                scheduled_time=timelock_expires,
                executor_id=executor_id,
                execution_data=execution_data,
                timelock_expires=timelock_expires
            )
            
            async with self.db.session() as session:
                session.add(execution)
                await session.commit()
            
            # Schedule execution
            await self._schedule_execution(execution_id, timelock_expires)
            
            logger.info(f"Timelock execution {execution_id} scheduled for {timelock_expires}")
            
            return ExecutionResult(
                success=True,
                execution_id=execution_id,
                transaction_hash=None,
                gas_used=None,
                error_message=None,
                execution_time=timelock_expires,
                rollback_data=None
            )
            
        except Exception as e:
            logger.error(f"Failed to schedule timelock execution: {str(e)}")
            return ExecutionResult(
                success=False,
                execution_id=execution_id,
                transaction_hash=None,
                gas_used=None,
                error_message=str(e),
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
    
    async def validate_execution(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any]
    ) -> tuple[bool, List[str]]:
        """Validate timelock execution parameters."""
        errors = []
        
        # Validate timelock delay
        delay_hours = execution_data.get('timelock_delay_hours', 24)
        if delay_hours < 1:
            errors.append("Timelock delay must be at least 1 hour")
        
        # Validate underlying execution data
        automated_valid, automated_errors = await self.automated_executor.validate_execution(
            proposal_id, execution_data
        )
        errors.extend(automated_errors)
        
        return len(errors) == 0, errors
    
    async def rollback(self, execution_id: str) -> bool:
        """Cancel timelocked execution."""
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution:
                    return False
                
                if execution.status == ExecutionStatus.TIMELOCKED.value:
                    execution.status = ExecutionStatus.CANCELLED.value
                    execution.updated_at = datetime.utcnow()
                    await session.commit()
                    
                    # Cancel scheduled execution
                    await self._cancel_scheduled_execution(execution_id)
                    
                    return True
                elif execution.status == ExecutionStatus.COMPLETED.value:
                    # Rollback completed execution
                    return await self.automated_executor.rollback(execution_id)
                
                return False
                
        except Exception as e:
            logger.error(f"Failed to rollback timelock execution {execution_id}: {str(e)}")
            return False
    
    async def _schedule_execution(self, execution_id: str, execute_at: datetime):
        """Schedule execution using task scheduler."""
        # This would integrate with a task scheduler like Celery
        # For now, we'll use a simple in-memory scheduler
        delay_seconds = (execute_at - datetime.utcnow()).total_seconds()
        
        asyncio.create_task(self._delayed_execution(execution_id, delay_seconds))
    
    async def _delayed_execution(self, execution_id: str, delay_seconds: float):
        """Execute after delay."""
        await asyncio.sleep(delay_seconds)
        
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution or execution.status != ExecutionStatus.TIMELOCKED.value:
                    return
                
                # Update status to in progress
                execution.status = ExecutionStatus.IN_PROGRESS.value
                execution.started_at = datetime.utcnow()
                await session.commit()
                
                # Execute using automated executor
                result = await self.automated_executor.execute(
                    execution.proposal_id,
                    execution.execution_data,
                    execution.executor_id
                )
                
                # Update final status
                execution.status = ExecutionStatus.COMPLETED.value if result.success else ExecutionStatus.FAILED.value
                execution.completed_at = datetime.utcnow()
                execution.transaction_hash = result.transaction_hash
                execution.gas_used = result.gas_used
                execution.result_data = {'automated_result': result.__dict__}
                if not result.success:
                    execution.error_message = result.error_message
                
                await session.commit()
                
                logger.info(f"Delayed execution {execution_id} completed: {result.success}")
                
        except Exception as e:
            logger.error(f"Delayed execution {execution_id} failed: {str(e)}")
            
            # Update execution record with error
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if execution:
                    execution.status = ExecutionStatus.FAILED.value
                    execution.completed_at = datetime.utcnow()
                    execution.error_message = str(e)
                    await session.commit()
    
    async def _cancel_scheduled_execution(self, execution_id: str):
        """Cancel scheduled execution."""
        # This would cancel the scheduled task
        # Implementation depends on the task scheduler used
        pass


class MultiSigExecution(ExecutionInterface):
    """Multi-signature execution requiring multiple approvals."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager,
        automated_executor: AutomatedExecution
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        self.automated_executor = automated_executor
        
    async def execute(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any],
        executor_id: str
    ) -> ExecutionResult:
        """Create multi-sig execution requiring signatures."""
        execution_id = str(uuid4())
        
        try:
            signatures_required = execution_data.get('signatures_required', 3)
            
            # Create multi-sig execution record
            execution = ExecutionModel(
                id=execution_id,
                proposal_id=proposal_id,
                execution_type=ExecutionType.MULTISIG.value,
                status=ExecutionStatus.AWAITING_MULTISIG.value,
                executor_id=executor_id,
                execution_data=execution_data,
                signatures_required=signatures_required,
                signatures_collected=[]
            )
            
            async with self.db.session() as session:
                session.add(execution)
                await session.commit()
            
            # Notify signers
            await self._notify_signers(execution_id, proposal_id)
            
            logger.info(f"Multi-sig execution {execution_id} created, requiring {signatures_required} signatures")
            
            return ExecutionResult(
                success=True,
                execution_id=execution_id,
                transaction_hash=None,
                gas_used=None,
                error_message=None,
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
            
        except Exception as e:
            logger.error(f"Failed to create multi-sig execution: {str(e)}")
            return ExecutionResult(
                success=False,
                execution_id=execution_id,
                transaction_hash=None,
                gas_used=None,
                error_message=str(e),
                execution_time=datetime.utcnow(),
                rollback_data=None
            )
    
    async def validate_execution(
        self, 
        proposal_id: str, 
        execution_data: Dict[str, Any]
    ) -> tuple[bool, List[str]]:
        """Validate multi-sig execution parameters."""
        errors = []
        
        # Validate signature requirements
        signatures_required = execution_data.get('signatures_required', 3)
        if signatures_required < 2:
            errors.append("Multi-sig execution requires at least 2 signatures")
        
        # Validate authorized signers
        authorized_signers = execution_data.get('authorized_signers', [])
        if len(authorized_signers) < signatures_required:
            errors.append("Not enough authorized signers for required signatures")
        
        # Validate underlying execution data
        automated_valid, automated_errors = await self.automated_executor.validate_execution(
            proposal_id, execution_data
        )
        errors.extend(automated_errors)
        
        return len(errors) == 0, errors
    
    async def rollback(self, execution_id: str) -> bool:
        """Cancel multi-sig execution."""
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution:
                    return False
                
                if execution.status == ExecutionStatus.AWAITING_MULTISIG.value:
                    execution.status = ExecutionStatus.CANCELLED.value
                    execution.updated_at = datetime.utcnow()
                    await session.commit()
                    return True
                elif execution.status == ExecutionStatus.COMPLETED.value:
                    return await self.automated_executor.rollback(execution_id)
                
                return False
                
        except Exception as e:
            logger.error(f"Failed to rollback multi-sig execution {execution_id}: {str(e)}")
            return False
    
    async def add_signature(
        self, 
        execution_id: str, 
        signer_id: str, 
        signature: str
    ) -> Dict[str, Any]:
        """Add signature to multi-sig execution."""
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution:
                    raise ValueError("Execution not found")
                
                if execution.status != ExecutionStatus.AWAITING_MULTISIG.value:
                    raise ValueError("Execution is not awaiting signatures")
                
                # Verify signature
                execution_hash = self._calculate_execution_hash(execution.execution_data)
                if not await self.security.verify_signature(execution_hash, signature, signer_id):
                    raise ValueError("Invalid signature")
                
                # Check if signer is authorized
                authorized_signers = execution.execution_data.get('authorized_signers', [])
                if signer_id not in authorized_signers:
                    raise ValueError("Signer is not authorized")
                
                # Check if already signed
                signatures = execution.signatures_collected or []
                if any(sig['signer_id'] == signer_id for sig in signatures):
                    raise ValueError("Signer has already signed")
                
                # Add signature
                signatures.append({
                    'signer_id': signer_id,
                    'signature': signature,
                    'timestamp': datetime.utcnow().isoformat()
                })
                execution.signatures_collected = signatures
                
                # Check if enough signatures collected
                if len(signatures) >= execution.signatures_required:
                    # Execute the proposal
                    result = await self.automated_executor.execute(
                        execution.proposal_id,
                        execution.execution_data,
                        execution.executor_id
                    )
                    
                    execution.status = ExecutionStatus.COMPLETED.value if result.success else ExecutionStatus.FAILED.value
                    execution.completed_at = datetime.utcnow()
                    execution.transaction_hash = result.transaction_hash
                    execution.gas_used = result.gas_used
                    execution.result_data = {'automated_result': result.__dict__}
                    if not result.success:
                        execution.error_message = result.error_message
                
                await session.commit()
                
                logger.info(f"Signature added to execution {execution_id} by {signer_id}")
                
                return {
                    'execution_id': execution_id,
                    'signatures_collected': len(signatures),
                    'signatures_required': execution.signatures_required,
                    'status': execution.status,
                    'executed': execution.status == ExecutionStatus.COMPLETED.value
                }
                
        except Exception as e:
            logger.error(f"Failed to add signature: {str(e)}")
            raise
    
    def _calculate_execution_hash(self, execution_data: Dict[str, Any]) -> str:
        """Calculate hash of execution data for signature verification."""
        import hashlib
        data_str = json.dumps(execution_data, sort_keys=True)
        return hashlib.sha256(data_str.encode()).hexdigest()
    
    async def _notify_signers(self, execution_id: str, proposal_id: str):
        """Notify authorized signers."""
        notification_data = {
            'type': 'multisig_signature_required',
            'execution_id': execution_id,
            'proposal_id': proposal_id,
            'timestamp': datetime.utcnow().isoformat()
        }
        
        await self.cache.publish('signer_notifications', json.dumps(notification_data))


class GovernanceExecutor:
    """Main governance execution coordinator."""
    
    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager,
        security_manager: SecurityManager,
        smart_contract_manager: SmartContractManager
    ):
        self.db = db_connection
        self.cache = cache_manager
        self.security = security_manager
        
        # Initialize execution mechanisms
        self.automated = AutomatedExecution(
            db_connection, cache_manager, security_manager, smart_contract_manager
        )
        self.manual = ManualExecution(db_connection, cache_manager, security_manager)
        self.timelock = TimelockExecution(
            db_connection, cache_manager, security_manager, self.automated
        )
        self.multisig = MultiSigExecution(
            db_connection, cache_manager, security_manager, self.automated
        )
        
        self.executors = {
            ExecutionType.AUTOMATED.value: self.automated,
            ExecutionType.MANUAL.value: self.manual,
            ExecutionType.TIMELOCK.value: self.timelock,
            ExecutionType.MULTISIG.value: self.multisig
        }
    
    async def initialize(self):
        """Initialize the governance executor."""
        logger.info("Initializing Governance Executor")
        
        # Create database tables
        async with self.db.engine.begin() as conn:
            await conn.run_sync(Base.metadata.create_all)
        
        logger.info("Governance Executor initialized successfully")
    
    async def execute_proposal(
        self,
        proposal_id: str,
        execution_type: ExecutionType,
        execution_data: Dict[str, Any],
        executor_id: str
    ) -> ExecutionResult:
        """Execute a proposal using specified execution type."""
        if execution_type.value not in self.executors:
            raise ValueError(f"Unknown execution type: {execution_type.value}")
        
        executor = self.executors[execution_type.value]
        return await executor.execute(proposal_id, execution_data, executor_id)
    
    async def get_execution_status(self, execution_id: str) -> Optional[Dict[str, Any]]:
        """Get execution status."""
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution:
                    return None
                
                return {
                    'execution_id': execution.id,
                    'proposal_id': execution.proposal_id,
                    'execution_type': execution.execution_type,
                    'status': execution.status,
                    'scheduled_time': execution.scheduled_time.isoformat() if execution.scheduled_time else None,
                    'started_at': execution.started_at.isoformat() if execution.started_at else None,
                    'completed_at': execution.completed_at.isoformat() if execution.completed_at else None,
                    'transaction_hash': execution.transaction_hash,
                    'gas_used': execution.gas_used,
                    'error_message': execution.error_message,
                    'signatures_required': execution.signatures_required,
                    'signatures_collected': len(execution.signatures_collected or []),
                    'timelock_expires': execution.timelock_expires.isoformat() if execution.timelock_expires else None
                }
                
        except Exception as e:
            logger.error(f"Failed to get execution status for {execution_id}: {str(e)}")
            return None
    
    async def rollback_execution(self, execution_id: str) -> bool:
        """Rollback an execution."""
        try:
            async with self.db.session() as session:
                execution = await session.get(ExecutionModel, execution_id)
                if not execution:
                    return False
                
                executor = self.executors.get(execution.execution_type)
                if not executor:
                    return False
                
                return await executor.rollback(execution_id)
                
        except Exception as e:
            logger.error(f"Failed to rollback execution {execution_id}: {str(e)}")
            return False
