    def __init__(
        self,
        db_connection: DatabaseConnection,
        cache_manager: CacheManager
    ):
        self.db = db_connection
        self.cache = cache_manager
    
    async def update_trust_metrics(
        self,
        user_id: str,
        metric_updates: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Update trust metrics for user."""
        try:
            async with self.db.session() as session:
                trust_metrics = await session.get(TrustMetricModel, user_id)
                if not trust_metrics:
                    trust_metrics = TrustMetricModel(user_id=user_id)
                    session.add(trust_metrics)
                
                # Update metrics
                for metric, value in metric_updates.items():
                    if hasattr(trust_metrics, metric):
                        setattr(trust_metrics, metric, value)
                
                await session.commit()
            
            # Clear reputation cache
            await self.cache.delete(f"reputation:{user_id}")
            
            return {
                'user_id': user_id,
                'updated_metrics': list(metric_updates.keys()),
                'updated_at': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to update trust metrics: {str(e)}")
            return {}
    
