class AuditLogger:
    """Comprehensive audit logging system."""
    
    def __init__(self, redis_client: aioredis.Redis):
        self.redis_client = redis_client
        self.logger = logging.getLogger(__name__)
        self.encryption_key = Fernet.generate_key()
        self.fernet = Fernet(self.encryption_key)
    
    async def log_security_event(self, event: SecurityEvent) -> None:
        """Log security event with encryption."""
        try:
            # Prepare audit record
            audit_record = {
                'event_id': str(event.id),
                'timestamp': event.timestamp.isoformat(),
                'event_type': event.event_type.value,
                'threat_level': event.threat_level.value,
                'risk_score': event.risk_score,
                'source_address': event.source_address,
                'target_address': event.target_address,
                'transaction_hash': event.transaction_hash,
                'amount': str(event.amount) if event.amount else None,
                'indicators': event.indicators,
                'mitigation_actions': event.mitigation_actions,
                'metadata': event.metadata
            }
            
            # Encrypt sensitive data
            encrypted_record = self._encrypt_audit_record(audit_record)
            
            # Store in Redis with TTL
            await self.redis_client.setex(
                f"audit:security:{event.id}",
                timedelta(days=365).total_seconds(),  # 1 year retention
                encrypted_record
            )
            
            # Index by timestamp for querying
            await self.redis_client.zadd(
                "audit:security:timeline",
                {str(event.id): event.timestamp.timestamp()}
            )
            
            # Index by threat level
            await self.redis_client.sadd(
                f"audit:security:threat_level:{event.threat_level.value}",
                str(event.id)
            )
            
            self.logger.info(f"Security event logged: {event.id}")
            
        except Exception as e:
            self.logger.error(f"Failed to log security event: {e}")
    
    async def log_bridge_operation(self, 
                                  operation_type: str,
                                  transaction_data: Dict[str, Any],
                                  result: Dict[str, Any]) -> None:
        """Log bridge operation for audit trail."""
        try:
            audit_record = {
                'operation_id': str(uuid4()),
                'timestamp': datetime.utcnow().isoformat(),
                'operation_type': operation_type,
                'transaction_data': transaction_data,
                'result': result,
                'ip_address': transaction_data.get('ip_address'),
                'user_agent': transaction_data.get('user_agent')
            }
            
            encrypted_record = self._encrypt_audit_record(audit_record)
            
            # Store with 7-year retention for compliance
            await self.redis_client.setex(
                f"audit:bridge:{audit_record['operation_id']}",
                timedelta(days=365*7).total_seconds(),
                encrypted_record
            )
            
        except Exception as e:
            self.logger.error(f"Failed to log bridge operation: {e}")
    
    async def get_audit_trail(self, 
                             start_time: datetime,
                             end_time: datetime,
                             event_type: Optional[str] = None) -> List[Dict[str, Any]]:
        """Retrieve audit trail for specified time range."""
        try:
            # Get event IDs from timeline
            start_timestamp = start_time.timestamp()
            end_timestamp = end_time.timestamp()
            
            event_ids = await self.redis_client.zrangebyscore(
                "audit:security:timeline",
                start_timestamp,
                end_timestamp
            )
            
            # Retrieve and decrypt records
            audit_records = []
            for event_id in event_ids:
                encrypted_record = await self.redis_client.get(f"audit:security:{event_id}")
                if encrypted_record:
                    record = self._decrypt_audit_record(encrypted_record)
                    if not event_type or record.get('event_type') == event_type:
                        audit_records.append(record)
            
            return audit_records
            
        except Exception as e:
            self.logger.error(f"Failed to retrieve audit trail: {e}")
            return []
    
    def _encrypt_audit_record(self, record: Dict[str, Any]) -> bytes:
        """Encrypt audit record."""
        record_json = json.dumps(record, default=str)
        return self.fernet.encrypt(record_json.encode())
    
    def _decrypt_audit_record(self, encrypted_record: bytes) -> Dict[str, Any]:
        """Decrypt audit record."""
        decrypted_data = self.fernet.decrypt(encrypted_record)
        return json.loads(decrypted_data.decode())


