class BridgeSecurityManager(BaseService):
    """
    Advanced Bridge Security Management System.
    
    Features:
    - Real-time threat detection
    - Comprehensive audit logging
    - Compliance validation
    - Risk assessment and scoring
    - Automated incident response
    - Security metrics and monitoring
    """
    
    def __init__(self, 
                 redis_client: aioredis.Redis,
                 metrics_collector: MetricsCollector):
        super().__init__()
        self.redis_client = redis_client
        self.metrics_collector = metrics_collector
        self.logger = logging.getLogger(__name__)
        
        # Initialize components
        self.threat_detector = ThreatDetector(redis_client)
        self.audit_logger = AuditLogger(redis_client)
        self.security_metrics = SecurityMetrics(metrics_collector)
        self.compliance_validator = ComplianceValidator()
        
        # Security policies
        self.security_policies: Dict[str, SecurityPolicy] = {}
        self.active_incidents: Dict[UUID, SecurityEvent] = {}
        
        # Configuration
        self.auto_block_enabled = True
        self.alert_thresholds = {
            ThreatLevel.HIGH: 10,      # Alert after 10 high-risk events
            ThreatLevel.CRITICAL: 3,   # Alert after 3 critical events
            ThreatLevel.EMERGENCY: 1   # Immediate alert for emergency
        }
    
    async def initialize(self) -> None:
        """Initialize bridge security manager."""
        try:
            # Load security policies
            await self._load_security_policies()
            
            # Initialize threat detection models
            await self._initialize_threat_models()
            
            # Start monitoring tasks
            asyncio.create_task(self._security_monitor())
            asyncio.create_task(self._incident_response_processor())
            
            self.logger.info("Bridge security manager initialized successfully")
            
        except Exception as e:
            self.logger.error(f"Failed to initialize bridge security manager: {e}")
            raise
    
    async def validate_transaction_security(self, 
                                          transaction_data: Dict[str, Any]) -> Tuple[bool, SecurityEvent]:
        """Validate transaction security and compliance."""
        try:
            # Threat detection analysis
            security_event = await self.threat_detector.analyze_transaction(transaction_data)
            
            # Compliance validation
            compliance_status, compliance_issues = await self.compliance_validator.validate_compliance(
                address=transaction_data.get('from', ''),
                amount=Decimal(str(transaction_data.get('amount', 0))),
                country_code=transaction_data.get('country_code')
            )
            
            # Update security event with compliance info
            security_event.metadata['compliance_status'] = compliance_status.value
            security_event.metadata['compliance_issues'] = compliance_issues
            
            # Log security event
            await self.audit_logger.log_security_event(security_event)
            await self.security_metrics.record_security_event(security_event)
            
            # Determine if transaction should be allowed
            is_allowed = self._should_allow_transaction(security_event, compliance_status)
            
            # Handle high-risk transactions
            if not is_allowed:
                await self._handle_blocked_transaction(security_event, transaction_data)
            
            return is_allowed, security_event
            
        except Exception as e:
            self.logger.error(f"Security validation failed: {e}")
            # Fail secure - block transaction on error
            return False, SecurityEvent(
                risk_score=1.0,
                threat_level=ThreatLevel.CRITICAL,
                metadata={'error': str(e)}
            )
    
    async def report_security_incident(self, 
                                     incident_type: SecurityEventType,
                                     details: Dict[str, Any]) -> UUID:
        """Report security incident for investigation."""
        try:
            incident = SecurityEvent(
                event_type=incident_type,
                threat_level=ThreatLevel.HIGH,
                metadata=details
            )
            
            # Store incident
            self.active_incidents[incident.id] = incident
            
            # Log incident
            await self.audit_logger.log_security_event(incident)
            
            # Trigger incident response
            await self._trigger_incident_response(incident)
            
            return incident.id
            
        except Exception as e:
            self.logger.error(f"Failed to report security incident: {e}")
            raise
    
    async def get_security_status(self) -> Dict[str, Any]:
        """Get current security status and metrics."""
        try:
            return {
                'active_incidents': len(self.active_incidents),
                'security_policies': len(self.security_policies),
                'threat_level': await self._get_current_threat_level(),
                'dashboard_data': await self.security_metrics.get_security_dashboard_data(),
                'system_health': {
                    'threat_detection': 'operational',
                    'audit_logging': 'operational',
                    'compliance_validation': 'operational'
                }
            }
            
        except Exception as e:
            self.logger.error(f"Failed to get security status: {e}")
            return {'error': str(e)}
    
    def _should_allow_transaction(self, 
                                 security_event: SecurityEvent,
                                 compliance_status: ComplianceStatus) -> bool:
        """Determine if transaction should be allowed."""
        # Block if blacklisted
        if compliance_status == ComplianceStatus.BLACKLISTED:
            return False
        
        # Block if risk score exceeds threshold
        if security_event.risk_score >= 0.9:
            return False
        
        # Block critical and emergency threats
        if security_event.threat_level in [ThreatLevel.CRITICAL, ThreatLevel.EMERGENCY]:
            return False
        
        # Allow with manual review for high-risk transactions
        if security_event.threat_level == ThreatLevel.HIGH:
            security_event.metadata['requires_manual_review'] = True
        
        return True
    
    async def _handle_blocked_transaction(self, 
                                        security_event: SecurityEvent,
                                        transaction_data: Dict[str, Any]) -> None:
        """Handle blocked transaction."""
        try:
            # Log the block
            self.logger.warning(f"Transaction blocked: {security_event.id}")
            
            # Add to blocked transactions list
            await self.redis_client.sadd(
                "blocked_transactions",
                json.dumps({
                    'event_id': str(security_event.id),
                    'transaction_hash': transaction_data.get('hash'),
                    'reason': 'Security violation',
                    'timestamp': datetime.utcnow().isoformat()
                })
            )
            
            # Update metrics
            await self.security_metrics.record_bridge_metrics("block", True)
            
            # Trigger alerts if necessary
            if security_event.threat_level in [ThreatLevel.CRITICAL, ThreatLevel.EMERGENCY]:
                await self._send_security_alert(security_event)
            
        except Exception as e:
            self.logger.error(f"Failed to handle blocked transaction: {e}")
    
    async def _load_security_policies(self) -> None:
        """Load security policies from configuration."""
        # Default security policy
        default_policy = SecurityPolicy(
            name="default_bridge_policy",
            description="Default security policy for bridge operations",
            max_transaction_amount=Decimal('100000'),
            max_daily_volume=Decimal('1000000'),
            max_transactions_per_hour=50,
            max_transactions_per_day=500,
            risk_score_threshold=0.7,
            auto_block_threshold=0.9,
            aml_screening=True,
            sanctions_screening=True
        )
        
        self.security_policies['default'] = default_policy
    
    async def _initialize_threat_models(self) -> None:
        """Initialize threat detection models."""
        # Load known threat indicators
        await self._load_threat_indicators()
        
        # Initialize ML models (if available)
        await self._initialize_ml_models()
    
