"""Data Formatters - Display and Formatting Utilities
==================================================

Comprehensive formatting utilities for displaying blockchain data,
amounts, addresses, and other bridge-related information in a
user-friendly format for the Spotify AI Agent ecosystem.

Author: Fahed Mlaiel <mlaiel@live.de>
Copyright: © 2025 Fahed Mlaiel. All rights reserved.
"""
import re
import logging
from datetime import datetime, timedelta
from decimal import Decimal, ROUND_HALF_UP, ROUND_DOWN
from typing import Dict, List, Optional, Any, Union
from enum import Enum

from .constants import SUPPORTED_CHAINS, TOKEN_ADDRESSES


class DisplayFormat(Enum):
    """Display format options."""
    FULL = "full"
    SHORT = "short"
    COMPACT = "compact"
    MINIMAL = "minimal"


class AddressFormatter:
    """Address formatting utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
    
    def format_address(self, 
                      address: str,
                      format_type: DisplayFormat = DisplayFormat.SHORT,
                      include_checksum: bool = True) -> str:
        """Format address for display."""
        try:
            if not address or len(address) != 42:
                return "Invalid Address"
            
            # Apply checksum if requested
            if include_checksum:
                # Simple checksum implementation (in real use, use eth_utils)
                address = address.lower()
                formatted_address = '0x' + address[2:].lower()
            else:
                formatted_address = address.lower()
            
            # Apply formatting based on type
            if format_type == DisplayFormat.FULL:
                return formatted_address
            elif format_type == DisplayFormat.SHORT:
                return f"{formatted_address[:6]}...{formatted_address[-4:]}"
            elif format_type == DisplayFormat.COMPACT:
                return f"{formatted_address[:8]}...{formatted_address[-6:]}"
            elif format_type == DisplayFormat.MINIMAL:
                return f"{formatted_address[:4]}...{formatted_address[-2:]}"
            
            return formatted_address
            
        except Exception as e:
            self.logger.error(f"Address formatting error: {e}")
            return "Format Error"
    
    def format_contract_address(self, 
                              address: str,
                              contract_name: Optional[str] = None,
                              chain_id: Optional[int] = None) -> str:
        """Format contract address with additional context."""
        try:
            formatted_addr = self.format_address(address, DisplayFormat.SHORT)
            
            if contract_name:
                return f"{contract_name} ({formatted_addr})"
            
            # Try to identify known contracts
            if chain_id and chain_id in TOKEN_ADDRESSES:
                for token_symbol, token_address in TOKEN_ADDRESSES[chain_id].items():
                    if address.lower() == token_address.lower():
                        return f"{token_symbol} Token ({formatted_addr})"
            
            return formatted_addr
            
        except Exception as e:
            self.logger.error(f"Contract address formatting error: {e}")
            return "Format Error"
    
    def format_multiple_addresses(self, 
                                addresses: List[str],
                                max_display: int = 3) -> str:
        """Format multiple addresses for display."""
        try:
            if not addresses:
                return "No addresses"
            
            if len(addresses) <= max_display:
                formatted_addresses = [
                    self.format_address(addr, DisplayFormat.SHORT) 
                    for addr in addresses
                ]
                return ", ".join(formatted_addresses)
            else:
                formatted_addresses = [
                    self.format_address(addr, DisplayFormat.SHORT) 
                    for addr in addresses[:max_display]
                ]
                remaining = len(addresses) - max_display
                return f"{', '.join(formatted_addresses)} and {remaining} more"
            
        except Exception as e:
            self.logger.error(f"Multiple addresses formatting error: {e}")
            return "Format Error"


class AmountFormatter:
    """Amount and currency formatting utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
    
    def format_amount(self, 
                     amount: Union[str, int, float, Decimal],
                     decimals: int = 18,
                     display_decimals: int = 6,
                     use_thousands_separator: bool = True,
                     currency_symbol: Optional[str] = None) -> str:
        """Format amount for display."""
        try:
            # Convert to Decimal
            if isinstance(amount, str):
                decimal_amount = Decimal(amount)
            elif isinstance(amount, (int, float)):
                decimal_amount = Decimal(str(amount))
            else:
                decimal_amount = amount
            
            # Convert from wei if needed
            if decimals > 0:
                decimal_amount = decimal_amount / (Decimal("10") ** decimals)
            
            # Round to display decimals
            decimal_amount = decimal_amount.quantize(
                Decimal("0.1") ** display_decimals, 
                rounding=ROUND_HALF_UP
            )
            
            # Format with thousands separator if requested
            if use_thousands_separator:
                # Convert to string and add separators
                amount_str = f"{decimal_amount:,.{display_decimals}f}"
            else:
                amount_str = f"{decimal_amount:.{display_decimals}f}"
            
            # Remove trailing zeros after decimal point
            if '.' in amount_str:
                amount_str = amount_str.rstrip('0').rstrip('.')
            
            # Add currency symbol if provided
            if currency_symbol:
                amount_str = f"{amount_str} {currency_symbol}"
            
            return amount_str
            
        except Exception as e:
            self.logger.error(f"Amount formatting error: {e}")
            return "Format Error"
    
    def format_usd_amount(self, 
                         amount: Union[str, int, float, Decimal],
                         include_symbol: bool = True) -> str:
        """Format USD amount."""
        try:
            decimal_amount = Decimal(str(amount))
            
            # Determine appropriate decimal places based on amount
            if decimal_amount >= 1000000:  # $1M+
                display_decimals = 0
            elif decimal_amount >= 1000:   # $1K+
                display_decimals = 0
            elif decimal_amount >= 1:      # $1+
                display_decimals = 2
            else:                          # < $1
                display_decimals = 4
            
            # Round amount
            decimal_amount = decimal_amount.quantize(
                Decimal("0.1") ** display_decimals,
                rounding=ROUND_HALF_UP
            )
            
            # Format with thousands separator
            amount_str = f"{decimal_amount:,.{display_decimals}f}"
            
            # Add currency symbol
            if include_symbol:
                amount_str = f"${amount_str}"
            
            return amount_str
            
        except Exception as e:
            self.logger.error(f"USD amount formatting error: {e}")
            return "Format Error"
    
    def format_percentage(self, 
                         percentage: Union[str, int, float, Decimal],
                         decimal_places: int = 2,
                         include_symbol: bool = True) -> str:
        """Format percentage value."""
        try:
            decimal_percentage = Decimal(str(percentage))
            
            # Round to specified decimal places
            decimal_percentage = decimal_percentage.quantize(
                Decimal("0.1") ** decimal_places,
                rounding=ROUND_HALF_UP
            )
            
            percentage_str = f"{decimal_percentage:.{decimal_places}f}"
            
            if include_symbol:
                percentage_str = f"{percentage_str}%"
            
            return percentage_str
            
        except Exception as e:
            self.logger.error(f"Percentage formatting error: {e}")
            return "Format Error"
    
    def format_gas_price(self, 
                        gas_price_wei: Union[str, int, Decimal],
                        unit: str = "gwei") -> str:
        """Format gas price for display."""
        try:
            gas_price = Decimal(str(gas_price_wei))
            
            if unit == "gwei":
                # Convert from wei to gwei
                gas_price_gwei = gas_price / Decimal("10") ** 9
                return f"{gas_price_gwei:.2f} gwei"
            elif unit == "eth":
                # Convert from wei to eth
                gas_price_eth = gas_price / Decimal("10") ** 18
                return f"{gas_price_eth:.9f} ETH"
            else:
                return f"{gas_price} wei"
            
        except Exception as e:
            self.logger.error(f"Gas price formatting error: {e}")
            return "Format Error"
    
    def format_large_number(self, 
                           number: Union[str, int, float, Decimal],
                           use_abbreviations: bool = True) -> str:
        """Format large numbers with abbreviations (K, M, B)."""
        try:
            decimal_number = Decimal(str(number))
            
            if not use_abbreviations:
                return f"{decimal_number:,.0f}"
            
            if decimal_number >= Decimal("1000000000"):  # Billion
                abbreviated = decimal_number / Decimal("1000000000")
                return f"{abbreviated:.2f}B"
            elif decimal_number >= Decimal("1000000"):   # Million
                abbreviated = decimal_number / Decimal("1000000")
                return f"{abbreviated:.2f}M"
            elif decimal_number >= Decimal("1000"):      # Thousand
                abbreviated = decimal_number / Decimal("1000")
                return f"{abbreviated:.2f}K"
            else:
                return f"{decimal_number:.2f}"
            
        except Exception as e:
            self.logger.error(f"Large number formatting error: {e}")
            return "Format Error"


class TimeFormatter:
    """Time and date formatting utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
    
    def format_timestamp(self, 
                        timestamp: Union[datetime, int, float],
                        format_type: str = "readable",
                        timezone: Optional[str] = None) -> str:
        """Format timestamp for display."""
        try:
            # Convert to datetime if needed
            if isinstance(timestamp, (int, float)):
                dt = datetime.fromtimestamp(timestamp)
            else:
                dt = timestamp
            
            if format_type == "readable":
                return dt.strftime("%Y-%m-%d %H:%M:%S UTC")
            elif format_type == "short":
                return dt.strftime("%m/%d/%Y %H:%M")
            elif format_type == "date_only":
                return dt.strftime("%Y-%m-%d")
            elif format_type == "time_only":
                return dt.strftime("%H:%M:%S")
            elif format_type == "iso":
                return dt.isoformat()
            else:
                return dt.strftime(format_type)
            
        except Exception as e:
            self.logger.error(f"Timestamp formatting error: {e}")
            return "Format Error"
    
    def format_duration(self, 
                       duration_seconds: Union[int, float, timedelta],
                       format_type: str = "readable") -> str:
        """Format duration for display."""
        try:
            # Convert to seconds if timedelta
            if isinstance(duration_seconds, timedelta):
                total_seconds = int(duration_seconds.total_seconds())
            else:
                total_seconds = int(duration_seconds)
            
            if format_type == "readable":
                if total_seconds < 60:
                    return f"{total_seconds}s"
                elif total_seconds < 3600:
                    minutes = total_seconds // 60
                    seconds = total_seconds % 60
                    return f"{minutes}m {seconds}s"
                elif total_seconds < 86400:
                    hours = total_seconds // 3600
                    minutes = (total_seconds % 3600) // 60
                    return f"{hours}h {minutes}m"
                else:
                    days = total_seconds // 86400
                    hours = (total_seconds % 86400) // 3600
                    return f"{days}d {hours}h"
            elif format_type == "compact":
                if total_seconds < 60:
                    return f"{total_seconds}s"
                elif total_seconds < 3600:
                    return f"{total_seconds // 60}m"
                elif total_seconds < 86400:
                    return f"{total_seconds // 3600}h"
                else:
                    return f"{total_seconds // 86400}d"
            else:
                return f"{total_seconds}s"
            
        except Exception as e:
            self.logger.error(f"Duration formatting error: {e}")
            return "Format Error"
    
    def format_relative_time(self, timestamp: datetime) -> str:
        """Format time relative to now (e.g., '2 hours ago')."""
        try:
            now = datetime.utcnow()
            diff = now - timestamp
            
            if diff.total_seconds() < 60:
                return "just now"
            elif diff.total_seconds() < 3600:
                minutes = int(diff.total_seconds() // 60)
                return f"{minutes} minute{'s' if minutes != 1 else ''} ago"
            elif diff.total_seconds() < 86400:
                hours = int(diff.total_seconds() // 3600)
                return f"{hours} hour{'s' if hours != 1 else ''} ago"
            elif diff.days < 30:
                return f"{diff.days} day{'s' if diff.days != 1 else ''} ago"
            elif diff.days < 365:
                months = diff.days // 30
                return f"{months} month{'s' if months != 1 else ''} ago"
            else:
                years = diff.days // 365
                return f"{years} year{'s' if years != 1 else ''} ago"
            
        except Exception as e:
            self.logger.error(f"Relative time formatting error: {e}")
            return "Format Error"


class TransactionFormatter:
    """Transaction formatting utilities."""
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.address_formatter = AddressFormatter()
        self.amount_formatter = AmountFormatter()
