"""Advanced Code Protection & Blockchain Registry System
===================================================

Système avancé de protection du code source avec enregistrement blockchain,
smart contracts pour la preuve de propriété, et tracking distribué.

Features:
- Enregistrement des empreintes sur blockchain
- Smart contracts pour la propriété intellectuelle
- Système de notarisation décentralisé
- Tracking automatique des violations
- Preuves cryptographiques horodatées
- API de vérification distribuée
- Système d'alertes en temps réel

Author: Fahed Mlaiel
Date: 2025-07-28
Version: 1.0.0 (Blockchain Protected)
"""
import asyncio
import json
import hashlib
import time
from typing import Dict, List, Optional, Any, Tuple
from datetime import datetime, timedelta
from dataclasses import dataclass, field
from enum import Enum
import logging

# Blockchain & Web3 imports
try:
    from web3 import Web3, HTTPProvider
    from eth_account import Account
    WEB3_AVAILABLE = True
except ImportError:
    WEB3_AVAILABLE = False
    logging.warning("Web3 not available. Blockchain features disabled.")

# IPFS pour stockage décentralisé
try:
    import ipfshttpclient
    IPFS_AVAILABLE = True
except ImportError:
    IPFS_AVAILABLE = False
    logging.warning("IPFS client not available. Decentralized storage disabled.")

# Imports internes
from .code_fingerprinting import CodeFingerprint, CodeTheftDetector
from ..core.config import settings
from ..core.database import get_database_session
from ..utils.encryption import encrypt_data, decrypt_data
from ..utils.monitoring import performance_monitor

logger = logging.getLogger(__name__)


class ProtectionLevel(str, Enum):
    """Niveaux de protection disponibles."""
    BASIC = "basic"              # Empreinte locale uniquement
    ADVANCED = "advanced"        # + Blockchain registry
    ENTERPRISE = "enterprise"    # + Monitoring temps réel
    MAXIMUM = "maximum"          # + Smart contracts + IPFS


class ViolationType(str, Enum):
    """Types de violations détectées."""
    CODE_THEFT = "code_theft"           # Vol de code direct
    PATTERN_COPY = "pattern_copy"       # Copie de patterns spécifiques
    STRUCTURE_COPY = "structure_copy"   # Copie de structure
    LOGIC_THEFT = "logic_theft"         # Vol de logique métier
    UNAUTHORIZED_USE = "unauthorized_use" # Usage non autorisé


@dataclass
class BlockchainRecord:
    """Enregistrement blockchain pour la protection du code."""
    record_id: str
    file_hash: str
    author: str
    project: str
    fingerprint_id: str
    timestamp: datetime
    blockchain_hash: Optional[str] = None
    transaction_id: Optional[str] = None
    block_number: Optional[int] = None
    smart_contract_address: Optional[str] = None
    ipfs_hash: Optional[str] = None
    verification_count: int = 0
    status: str = "pending"


@dataclass
class ViolationAlert:
    """Alerte de violation de code."""
    alert_id: str
    violation_type: ViolationType
    suspected_file: str
    original_record: BlockchainRecord
    similarity_score: float
    detected_at: datetime
    evidence: Dict[str, Any]
    severity: str = "medium"
    status: str = "new"
    investigator_notes: List[str] = field(default_factory=list)


class BlockchainProtectionRegistry:
    """Registre de protection blockchain pour les codes sources."""
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        """Initialise le registre de protection blockchain."""
        self.config = config or {}
        self.web3 = None
        self.ipfs_client = None
        self.contract = None
        self.account = None
        
        # Smart contract ABI (simplifié)
        self.contract_abi = [
            {
                "inputs": [
                    {"name": "fileHash", "type": "string"},
                    {"name": "author", "type": "string"},
                    {"name": "fingerprintId", "type": "string"},
                    {"name": "ipfsHash", "type": "string"}
                ],
                "name": "registerCode",
                "outputs": [{"name": "", "type": "uint256"}],
                "type": "function"
            },
            {
                "inputs": [{"name": "fileHash", "type": "string"}],
                "name": "verifyCode",
                "outputs": [
                    {"name": "exists", "type": "bool"},
                    {"name": "author", "type": "string"},
                    {"name": "timestamp", "type": "uint256"}
                ],
                "type": "function"
            }
        ]
        
        # Statistiques du registre
        self.registry_stats = {
            "total_registrations": 0,
            "blockchain_transactions": 0,
            "ipfs_uploads": 0,
            "violations_detected": 0,
            "verification_requests": 0
        }
    
    async def initialize(self) -> None:
        """Initialise les connexions blockchain et IPFS."""
        try:
            # Initialiser Web3
            if WEB3_AVAILABLE:
                blockchain_url = self.config.get("blockchain_url", "https://polygon-rpc.com")
                self.web3 = Web3(HTTPProvider(blockchain_url))
                
                # Charger le compte (private key depuis config sécurisé)
                private_key = self.config.get("private_key")
                if private_key:
                    self.account = Account.from_key(private_key)
                
                logger.info("Blockchain connection initialized")
            
            # Initialiser IPFS
            if IPFS_AVAILABLE:
                ipfs_host = self.config.get("ipfs_host", "/ip4/127.0.0.1/tcp/5001")
                self.ipfs_client = ipfshttpclient.connect(ipfs_host)
                logger.info("IPFS connection initialized")
            
            # Initialiser le smart contract
            contract_address = self.config.get("contract_address")
            if self.web3 and contract_address:
                self.contract = self.web3.eth.contract(
                    address=contract_address,
                    abi=self.contract_abi
                )
                logger.info("Smart contract initialized")
            
        except Exception as e:
            logger.error(f"Failed to initialize blockchain protection: {e}")
            raise
    
    async def upload_to_ipfs(self, data: Dict[str, Any]) -> Optional[str]:
        """Upload des données vers IPFS."""
        if not self.ipfs_client:
            return None
        
        try:
            # Convertir en JSON et uploader
            json_data = json.dumps(data, indent=2, default=str)
            result = self.ipfs_client.add_json(data)
            
            self.registry_stats["ipfs_uploads"] += 1
            logger.info(f"Data uploaded to IPFS: {result}")
            
            return result
            
        except Exception as e:
            logger.error(f"IPFS upload failed: {e}")
            return None
    
    async def register_on_blockchain(self, record: BlockchainRecord) -> bool:
        """Enregistre le code sur la blockchain."""
        if not self.web3 or not self.contract or not self.account:
            logger.warning("Blockchain not available for registration")
            return False
        
        try:
            # Préparer la transaction
            transaction = self.contract.functions.registerCode(
                record.file_hash,
                record.author,
                record.fingerprint_id,
                record.ipfs_hash or ""
            ).buildTransaction({
                'from': self.account.address,
                'gas': 200000,
                'gasPrice': self.web3.toWei('20', 'gwei'),
                'nonce': self.web3.eth.getTransactionCount(self.account.address)
            })
            
            # Signer et envoyer la transaction
            signed_txn = self.account.sign_transaction(transaction)
            tx_hash = self.web3.eth.sendRawTransaction(signed_txn.rawTransaction)
            
            # Attendre la confirmation
            receipt = self.web3.eth.waitForTransactionReceipt(tx_hash)
            
            # Mettre à jour l'enregistrement
            record.transaction_id = receipt.transactionHash.hex()
            record.block_number = receipt.blockNumber
            record.blockchain_hash = tx_hash.hex()
            record.status = "confirmed"
            
            self.registry_stats["blockchain_transactions"] += 1
            logger.info(f"Code registered on blockchain: {record.transaction_id}")
            
            return True
            
        except Exception as e:
            logger.error(f"Blockchain registration failed: {e}")
            record.status = "failed"
            return False
    
    async def verify_on_blockchain(self, file_hash: str) -> Optional[Dict[str, Any]]:
        """Vérifie l'existence d'un code sur la blockchain."""
        if not self.web3 or not self.contract:
            return None
        
        try:
            result = self.contract.functions.verifyCode(file_hash).call()
            
            self.registry_stats["verification_requests"] += 1
            
            if result[0]:  # exists
                return {
                    "exists": True,
                    "author": result[1],
                    "timestamp": result[2],
                    "verified_at": datetime.utcnow()
                }
            else:
                return {"exists": False}
                
        except Exception as e:
            logger.error(f"Blockchain verification failed: {e}")
            return None
    
    @performance_monitor("register_code_protection")
    async def register_code_protection(self, file_path: str, 
                                     protection_level: ProtectionLevel = ProtectionLevel.ADVANCED,
                                     metadata: Optional[Dict[str, Any]] = None) -> BlockchainRecord:
        """Enregistre un fichier avec protection complète."""
        try:
            # Créer l'empreinte du code
            fingerprinter = CodeFingerprint()
            fingerprint_report = fingerprinter.create_comprehensive_fingerprint(
                file_path, metadata
            )
            
            # Lire le contenu du fichier
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
            
            # Calculer le hash du fichier
            file_hash = hashlib.sha256(content.encode()).hexdigest()
            
            # Créer l'enregistrement blockchain
            record = BlockchainRecord(
                record_id=fingerprint_report["fingerprint_id"],
                file_hash=file_hash,
                author=fingerprint_report["author"],
                project=fingerprint_report["project"],
                fingerprint_id=fingerprint_report["fingerprint_id"],
                timestamp=datetime.utcnow()
            )
            
            # Uploader vers IPFS si niveau de protection élevé
            if protection_level in [ProtectionLevel.ENTERPRISE, ProtectionLevel.MAXIMUM]:
                ipfs_data = {
                    "fingerprint_report": fingerprint_report,
                    "file_content": content,
                    "metadata": metadata or {},
                    "protection_level": protection_level.value
                }
                record.ipfs_hash = await self.upload_to_ipfs(ipfs_data)
            
            # Enregistrer sur blockchain si disponible
            if protection_level in [ProtectionLevel.ADVANCED, ProtectionLevel.ENTERPRISE, ProtectionLevel.MAXIMUM]:
                await self.register_on_blockchain(record)
            
            # Sauvegarder dans la base de données locale
            await self._save_record_to_db(record, fingerprint_report)
            
            self.registry_stats["total_registrations"] += 1
            logger.info(f"Code protection registered: {record.record_id}")
            
            return record
            
        except Exception as e:
            logger.error(f"Code protection registration failed: {e}")
            raise
    
    async def _save_record_to_db(self, record: BlockchainRecord, 
                               fingerprint_report: Dict[str, Any]) -> None:
        """Sauvegarde l'enregistrement dans la base de données."""
        try:
            db_session = await get_database_session()
            
            # Insérer l'enregistrement (structure simplifiée)
            insert_query = """
                INSERT INTO code_protection_registry 
                (record_id, file_hash, author, project, fingerprint_id, timestamp, 
                 blockchain_hash, transaction_id, block_number, ipfs_hash, status, fingerprint_data)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """
            
            await db_session.execute(insert_query, (
                record.record_id,
                record.file_hash,
                record.author,
                record.project,
                record.fingerprint_id,
                record.timestamp,
                record.blockchain_hash,
                record.transaction_id,
                record.block_number,
                record.ipfs_hash,
                record.status,
                json.dumps(fingerprint_report)
            ))
            
            await db_session.commit()
            
        except Exception as e:
            logger.error(f"Database save failed: {e}")
            raise
        finally:
            if db_session:
                await db_session.close()


class RealTimeViolationMonitor:
    """Moniteur temps réel des violations de code."""
    
    def __init__(self, registry: BlockchainProtectionRegistry):
        self.registry = registry
        self.active_monitors = {}
        self.violation_threshold = 0.75  # Seuil de détection
        self.monitoring_active = False
        
        # Canaux de notification
        self.notification_channels = {
            "email": [],
            "webhook": [],
            "slack": []
        }
    
    async def start_monitoring(self, directories: List[str]) -> None:
        """Démarre le monitoring temps réel."""
        self.monitoring_active = True
        logger.info(f"Starting real-time monitoring for {len(directories)} directories")
        
        # Créer des tâches de monitoring pour chaque répertoire
        monitoring_tasks = [
            self._monitor_directory(directory) for directory in directories
        ]
        
        await asyncio.gather(*monitoring_tasks)
    
    async def _monitor_directory(self, directory: str) -> None:
        """Monitore un répertoire spécifique."""
        import os
        from watchdog.observers import Observer
        from watchdog.events import FileSystemEventHandler
        
        class CodeChangeHandler(FileSystemEventHandler):
            def __init__(self, monitor_instance):
                self.monitor = monitor_instance
            
            def on_modified(self, event):
                if event.is_directory or not event.src_path.endswith('.py'):
                    return
                
                # Programmer la vérification (async)
                asyncio.create_task(
                    self.monitor._check_file_for_violations(event.src_path)
                )
        
        handler = CodeChangeHandler(self)
        observer = Observer()
        observer.schedule(handler, directory, recursive=True)
        observer.start()
        
        try:
            while self.monitoring_active:
                await asyncio.sleep(1)
        finally:
            observer.stop()
            observer.join()
    
    async def _check_file_for_violations(self, file_path: str) -> None:
        """Vérifie un fichier pour des violations potentielles."""
        try:
            # Lire le contenu du fichier
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
            
            # Calculer le hash du fichier
            file_hash = hashlib.sha256(content.encode()).hexdigest()
            
            # Vérifier sur la blockchain
            verification_result = await self.registry.verify_on_blockchain(file_hash)
            
            if verification_result and verification_result.get("exists"):
                # Le fichier existe déjà - violation potentielle
                original_author = verification_result.get("author")
                current_context = self._extract_file_context(file_path)
                
                # Vérifier si c'est le même auteur
                if original_author != current_context.get("author"):
                    await self._create_violation_alert(
                        file_path, verification_result, content
                    )
            
        except Exception as e:
            logger.error(f"File violation check failed: {e}")
    
    def _extract_file_context(self, file_path: str) -> Dict[str, Any]:
        """Extrait le contexte du fichier (auteur, projet, etc.)."""
        # Analyser le chemin et le contenu pour extraire les informations
        context = {
            "file_path": file_path,
            "author": "unknown",
            "project": "unknown"
        }
        
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
            
            # Rechercher les patterns d'auteur
            import re
            author_patterns = [
                r'Author:\s*([^\n]+)',
                r'@author\s+([^\n]+)',
                r'# Created by:\s*([^\n]+)'
            ]
            
            for pattern in author_patterns:
                match = re.search(pattern, content, re.IGNORECASE)
                if match:
                    context["author"] = match.group(1).strip()
                    break
            
            # Extraire le nom du projet depuis le chemin
            path_parts = file_path.split('/')
            for part in path_parts:
                if 'project' in part.lower() or 'app' in part.lower():
                    context["project"] = part
                    break
            
        except Exception as e:
            logger.error(f"Context extraction failed: {e}")
        
        return context
    
    async def _create_violation_alert(self, file_path: str, 
                                    verification_result: Dict[str, Any],
                                    content: str) -> None:
        """Crée une alerte de violation."""
        try:
            # Analyser la similarité avec les techniques de fingerprinting
            detector = CodeTheftDetector(b'secret_key')  # Clé à sécuriser
            
            # Pour cette démo, on simule la détection
            similarity_score = 0.85  # À remplacer par la vraie détection
            
            alert = ViolationAlert(
                alert_id=f"alert_{int(time.time())}",
                violation_type=ViolationType.CODE_THEFT,
                suspected_file=file_path,
                original_record=None,  # À récupérer depuis la DB
                similarity_score=similarity_score,
                detected_at=datetime.utcnow(),
                evidence={
                    "verification_result": verification_result,
                    "file_hash": hashlib.sha256(content.encode()).hexdigest(),
                    "detection_method": "blockchain_verification"
                },
                severity="high" if similarity_score > 0.9 else "medium"
            )
            
            # Sauvegarder l'alerte
            await self._save_violation_alert(alert)
            
            # Envoyer les notifications
            await self._send_violation_notifications(alert)
            
            self.registry.registry_stats["violations_detected"] += 1
            logger.warning(f"Code violation detected: {alert.alert_id}")
            
        except Exception as e:
            logger.error(f"Violation alert creation failed: {e}")
    
    async def _save_violation_alert(self, alert: ViolationAlert) -> None:
        """Sauvegarde l'alerte de violation."""
        try:
            db_session = await get_database_session()
            
            insert_query = """
                INSERT INTO violation_alerts 
                (alert_id, violation_type, suspected_file, similarity_score, 
                 detected_at, evidence, severity, status)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
            """
            
            await db_session.execute(insert_query, (
                alert.alert_id,
                alert.violation_type.value,
                alert.suspected_file,
                alert.similarity_score,
                alert.detected_at,
                json.dumps(alert.evidence, default=str),
                alert.severity,
                alert.status
            ))
            
            await db_session.commit()
            
        except Exception as e:
            logger.error(f"Alert save failed: {e}")
        finally:
            if db_session:
                await db_session.close()
    
    async def _send_violation_notifications(self, alert: ViolationAlert) -> None:
        """Envoie les notifications de violation."""
        notification_message = f"""
        🚨 CODE VIOLATION DETECTED 🚨
        
        Alert ID: {alert.alert_id}
        Type: {alert.violation_type.value}
        File: {alert.suspected_file}
        Similarity: {alert.similarity_score:.1%}
        Severity: {alert.severity.upper()}
        Time: {alert.detected_at.strftime('%Y-%m-%d %H:%M:%S')}
        
        Immediate investigation required!
        """
        
        # Log la violation
        logger.critical(notification_message)
        
